INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港（gǎng，第三声）指海边供船停靠的地方。"}, {"text": "刚", "is_correct": false, "explanation": "声调不同：刚读 gāng（第一声），意思是刚才，与 gǎng（第三声）不同。"}, {"text": "缸", "is_correct": false, "explanation": "声调不同：缸读 gāng（第一声），意思是盛水的器皿，与港不同。"}, {"text": "敢", "is_correct": false, "explanation": "韵母不同：敢读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是勇敢。"}, {"text": "杆", "is_correct": false, "explanation": "韵母不同：杆读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是杆子。"}], "explanations": {"港": "正确：港（gǎng，第三声）指海边供船停靠的地方。", "刚": "声调不同：刚读 gāng（第一声），意思是刚才，与 gǎng（第三声）不同。", "缸": "声调不同：缸读 gāng（第一声），意思是盛水的器皿，与港不同。", "敢": "韵母不同：敢读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是勇敢。", "杆": "韵母不同：杆读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是杆子。"}, "sentence_index": null, "correct_answer": "港"}, "level_3": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港是地方名词，可以用“安静”描述，也可以“没有什么人”。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是人多、声音大的活动，与“安静”“没有什么人”矛盾。"}, {"text": "酒会", "is_correct": false, "explanation": "语义：酒会以众人聚集为前提，“没有什么人”与之矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“小”修饰的是具体的地方，不说“小天空”，句子不通。"}], "explanations": {"港": "正确：港是地方名词，可以用“安静”描述，也可以“没有什么人”。", "演唱会": "语义：演唱会是人多、声音大的活动，与“安静”“没有什么人”矛盾。", "酒会": "语义：酒会以众人聚集为前提，“没有什么人”与之矛盾。", "天空": "搭配：“小”修饰的是具体的地方，不说“小天空”，句子不通。"}, "sentence_index": 6, "correct_answer": "港"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在港里借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，港是供船只靠泊的地方，不能在港里借书。"}, {"text": "汽车在港上飞快地行驶。", "explanation": "这里应该用〈马路〉。汽车在马路上行驶，港是供船只靠泊的地方，不能用来行车。"}, {"text": "农民在港里插秧。", "explanation": "这里应该用〈稻田〉。插秧要在稻田里，港是供船只靠泊的地方，不能用来插秧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只港很大，停着许多大船。", "corrected_sentence": "那个港很大，停着许多大船。", "error_description": "错误：“港”是地方，量词应用“个”，不能用“只”。应说“那个港”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥把船开进了一条港。", "corrected_sentence": "我哥把船开进了一个港。", "error_description": "错误：量词用错。“港”是地方，应用“个”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "江河或海边供船只停靠的地方。", "primary_collocate": null, "pronunciation": "gǎng", "ipa": "kɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "货船昨天已经进港了。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港水很深，大船也能进来。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民每天早上从港里出海。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风要来了，所有的船都回港了。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一个小港，常有船停靠。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长把船开进了港。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港每年有很多货船来。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上有雾，船不敢出港。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的船昨晚在这个港停了一夜。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个港离城里不远，坐车二十分钟。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "港口", "label": "复合"}, {"form": "港湾", "label": "复合"}], "register": "中性", "sense_fingerprint": "港：江河或海边供船只停靠的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港（gǎng，第三声）指江河或海边供船停靠的地方。"}, {"text": "纲", "is_correct": false, "explanation": "声调不同：纲读 gāng（第一声），意思是纲要，与 gǎng（第三声）的港不同。"}, {"text": "秆", "is_correct": false, "explanation": "韵母不同：秆读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是秸秆。"}, {"text": "杠", "is_correct": false, "explanation": "声调不同：杠读 gàng（第四声），意思是杠杆，与 gǎng（第三声）不同。"}, {"text": "敢", "is_correct": false, "explanation": "韵母不同：敢读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是勇敢。"}], "explanations": {"港": "正确：港（gǎng，第三声）指江河或海边供船停靠的地方。", "纲": "声调不同：纲读 gāng（第一声），意思是纲要，与 gǎng（第三声）的港不同。", "秆": "韵母不同：秆读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是秸秆。", "杠": "声调不同：杠读 gàng（第四声），意思是杠杆，与 gǎng（第三声）不同。", "敢": "韵母不同：敢读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是勇敢。"}, "sentence_index": null, "correct_answer": "港"}, "level_3": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港是供船停靠的地方，货船可以“进港”。"}, {"text": "厂房", "is_correct": false, "explanation": "语义：厂房是生产场所，货船不会进厂房。"}, {"text": "车库", "is_correct": false, "explanation": "语义：车库停放汽车，货船不会进车库。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，船不会进教室，“货船进教室了”不通。"}], "explanations": {"港": "正确：港是供船停靠的地方，货船可以“进港”。", "厂房": "语义：厂房是生产场所，货船不会进厂房。", "车库": "语义：车库停放汽车，货船不会进车库。", "教室": "语义：教室是上课的地方，船不会进教室，“货船进教室了”不通。"}, "sentence_index": 0, "correct_answer": "港"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这列火车准点进港了。", "explanation": "这里应该用〈车站〉。火车进车站，港是供船只靠泊的地方，火车不能进港。"}, {"text": "这架客机准时靠港了。", "explanation": "这里应该用〈机场〉。客机在机场降落，港供船只靠泊，客机不能靠港。"}, {"text": "农民们在港里插秧。", "explanation": "这里应该用〈稻田〉。插秧要在稻田里，港是供船只靠泊的地方，不能用来插秧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港（gǎng，第三声）指江河或海边供船停靠的地方。"}, {"text": "钢", "is_correct": false, "explanation": "声调不同：钢读 gāng（第一声），意思是钢铁，与 gǎng（第三声）不同。"}, {"text": "感", "is_correct": false, "explanation": "韵母不同：感读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是感觉。"}, {"text": "赶", "is_correct": false, "explanation": "韵母不同：赶读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是追赶。"}, {"text": "缸", "is_correct": false, "explanation": "声调不同：缸读 gāng（第一声），意思是盛水的器皿，与港不同。"}], "explanations": {"港": "正确：港（gǎng，第三声）指江河或海边供船停靠的地方。", "钢": "声调不同：钢读 gāng（第一声），意思是钢铁，与 gǎng（第三声）不同。", "感": "韵母不同：感读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是感觉。", "赶": "韵母不同：赶读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是追赶。", "缸": "声调不同：缸读 gāng（第一声），意思是盛水的器皿，与港不同。"}, "sentence_index": null, "correct_answer": "港"}, "level_3": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港是供船停靠的地方，货船可以“来港”。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不接收货船，货船不会来学校。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是货船来的地方，“每年有很多货船来”不通。"}, {"text": "剧场", "is_correct": false, "explanation": "语义：剧场是演出的地方，货船不会来剧场，“每年有很多货船来”不通。"}], "explanations": {"港": "正确：港是供船停靠的地方，货船可以“来港”。", "学校": "语义：学校不接收货船，货船不会来学校。", "医院": "语义：医院不是货船来的地方，“每年有很多货船来”不通。", "剧场": "语义：剧场是演出的地方，货船不会来剧场，“每年有很多货船来”不通。"}, "sentence_index": 6, "correct_answer": "港"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙放进了港。", "explanation": "这里应该用〈抽屉〉。钥匙要放进抽屉，港是供船只停靠的地方，不能用来放东西。"}, {"text": "他的父母在港种地。", "explanation": "这里应该用〈农村〉。种地要在农村，港是供船只停靠的地方，不能在港里种地。"}, {"text": "妈妈在港里晾衣服。", "explanation": "这里应该用〈院子〉。晾衣服要在院子里，港是供船只停靠的地方，不能用来晾衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河下游有一艘港。", "corrected_sentence": "这条河下游有一个港。", "error_description": "错误：量词用错。港是地方，应说“一个港”；“艘”用于船，不能用于港。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民把船开回了一条港。", "corrected_sentence": "渔民把船开回了一个港。", "error_description": "错误：量词用错。“港”是地方，应用“个”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
