INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在铁轨上行驶、由多节车厢组成的交通工具。", "primary_collocate": null, "pronunciation": "huǒ chē", "ipa": "xuo˨˩˦ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "这趟火车开往广州。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车有十二节车厢。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车慢慢地开出了车站。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢坐火车旅行。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车晚点了，我们要在车站等。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一列火车从山里开出来。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车上的人都在看窗外。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天坐火车去另一个城市上班。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车开过桥的时候声音很大。", "target_word": "火车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着窗外，火车正穿过山洞。", "target_word": "火车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列", "label": "量词"}, {"form": "趟", "label": "量词"}, {"form": "火車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "火车：在铁轨上行驶、由多节车厢组成的交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '171bfaad-7331-4fb7-ab07-ca6c9f52da30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火车", "is_correct": true, "explanation": "正确：「这趟火车」是指一班列车，「开往广州」符合句意。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：「电梯」只在楼层之间升降，不能「开往」城市。"}, {"text": "花园", "is_correct": false, "explanation": "语义：「花园」是地方，不是交通工具，不能「开往」广州。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：「开往」搭配的是车次或交通工具，「书包」不能开往广州。"}], "explanations": {"火车": "正确：「这趟火车」是指一班列车，「开往广州」符合句意。", "电梯": "语义：「电梯」只在楼层之间升降，不能「开往」城市。", "花园": "语义：「花园」是地方，不是交通工具，不能「开往」广州。", "书包": "搭配：「开往」搭配的是车次或交通工具，「书包」不能开往广州。"}, "sentence_index": 0, "correct_answer": "火车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最喜欢坐一个火车旅行。", "explanation": "量词：火车用「列」或「趟」，不用「个」，这里应说〈一列火车〉。"}, {"text": "我每天骑火车去上班。", "explanation": "这里应该用〈摩托车〉。「骑」用于自行车、摩托车这类车，火车不能「骑」。"}, {"text": "我把火车牵到了车站。", "explanation": "这里应该用〈马〉。「牵」用于马、狗这类牲畜，火车不能被牵着走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火车", "is_correct": true, "explanation": "正确：「火车上的人」指火车里的乘客，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：「黑板」是用来写字的，上面不会有人看窗外。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：「上的人」搭配的是可以乘坐的交通工具或平面家具，「地址上」不能有人。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：「钥匙」是小物件，不能坐人，也不能「看窗外」。"}], "explanations": {"火车": "正确：「火车上的人」指火车里的乘客，符合句意。", "黑板": "语义：「黑板」是用来写字的，上面不会有人看窗外。", "地址": "搭配：「上的人」搭配的是可以乘坐的交通工具或平面家具，「地址上」不能有人。", "钥匙": "语义：「钥匙」是小物件，不能坐人，也不能「看窗外」。"}, "sentence_index": 6, "correct_answer": "火车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看着窗外，火车正在水面上航行。", "explanation": "这里应该用〈轮船〉。火车只能在铁路上行驶，不能在水面上航行。"}, {"text": "他看着窗外，一只火车正从桥上开过。", "explanation": "量词：火车用「列」或「趟」，不用「只」，这里应说〈一列火车〉。"}, {"text": "他打火车去机场了。", "explanation": "这里应该用〈出租车〉。「打」多用于出租车、公交车，火车不能「打」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐了一列的火车去北京。", "corrected_sentence": "我们坐了一列火车去北京。", "error_description": "「一列」修饰名词时直接接在名词前，中间不加「的」，应说「一列火车」，不说「一列的火车」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前坐了过火车，很舒服。", "corrected_sentence": "我以前坐过火车，很舒服。", "error_description": "「了」和「过」不能同时用在同一个动词后；这里说的是过去的经历，只用「过」，应说「坐过火车」，不说「坐了过火车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
