INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90739, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "说完一件事，再加一件。", "primary_collocate": null, "pronunciation": "zài zé", "ipa": "tsai̯˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我不想去，一来太远，二来太累，再则也没有时间。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案有两个好处：一则省钱，再则省时间。", "target_word": "再则", "complexity_tier": "T3", "furigana": "zài zé", "sentence_source": "generated"}, {"text": "他说了价格的问题，再则又说了时间的问题。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做省时间，再则不花钱。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要做三件事：检查车，买水，再则给家人打电话。", "target_word": "再则", "complexity_tier": "T3", "furigana": "zài zé", "sentence_source": "generated"}, {"text": "一是怕麻烦你，再则怕耽误你的工作。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一是问我累不累，再则问我饿不饿。", "target_word": "再则", "complexity_tier": "T3", "furigana": "zài zé", "sentence_source": "generated"}, {"text": "搬家要找车，再则要找人帮忙。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一则感谢了大家，再则提出了明年的计划。", "target_word": "再则", "complexity_tier": "T3", "furigana": "zài zé", "sentence_source": "generated"}, {"text": "这次旅行要带的东西有很多，一则是衣服，再则是药。", "target_word": "再则", "complexity_tier": "T3", "furigana": "zài zé", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "列举事项时，说完前一项后接着再补上下一项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再则", "is_correct": true, "explanation": "正确：再则是列举中的后一项，与“一来……二来……”配合。"}, {"text": "然后", "is_correct": false, "explanation": "语义：然后表示先后顺序，此处是列举理由，不是先后。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接前面的动作，不接列举的理由。"}, {"text": "所以", "is_correct": false, "explanation": "语义：所以表示因果，此处列举的并非结果。"}], "explanations": {"再则": "正确：再则是列举中的后一项，与“一来……二来……”配合。", "然后": "语义：然后表示先后顺序，此处是列举理由，不是先后。", "于是": "搭配：“于是”承接前面的动作，不接列举的理由。", "所以": "语义：所以表示因果，此处列举的并非结果。"}, "sentence_index": 0, "correct_answer": "再则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "再则，我要先去超市。", "explanation": "这里应该用〈首先〉。再则是列举中的后一项，不能用于第一项。"}, {"text": "再则很累，我还是去了。", "explanation": "这里应该用〈虽然〉。再则表示补充，不表示让步，不能引出“虽然很累，但还是去了”的意思。"}, {"text": "这个东西再则很贵，他还是买了。", "explanation": "这里应该用〈尽管〉。再则表示补充，不表示让步，不能引出“尽管很贵，他还是买了”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再则", "is_correct": true, "explanation": "正确：再则在“一是”后引出第二项，与“一是”配合。"}, {"text": "而是", "is_correct": false, "explanation": "语义：而是表示对比否定，此处是并列列举，不是对比。"}, {"text": "因此", "is_correct": false, "explanation": "语义：因此表示结果，与并列询问的“累不累”“饿不饿”不符。"}, {"text": "否则", "is_correct": false, "explanation": "语义：否则表示假设的结果，此处不是假设。"}], "explanations": {"再则": "正确：再则在“一是”后引出第二项，与“一是”配合。", "而是": "语义：而是表示对比否定，此处是并列列举，不是对比。", "因此": "语义：因此表示结果，与并列询问的“累不累”“饿不饿”不符。", "否则": "语义：否则表示假设的结果，此处不是假设。"}, "sentence_index": 6, "correct_answer": "再则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很高兴，再则心里很难过。", "explanation": "这里应该用〈不过〉。再则表示补充，不表示转折，前后两个意思不应这样衔接。"}, {"text": "他说要来，再则没有来。", "explanation": "这里应该用〈却〉。再则只表示补充，不表示转折，不能引出“却没有来”的意思。"}, {"text": "再则很冷，我还是出门了。", "explanation": "这里应该用〈虽然〉。再则表示补充，不表示让步，不能引出“虽然很冷，还是出门了”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不去，一来忙，二来累，要再则也没有钱。", "corrected_sentence": "我不去，一来忙，二来累，再则也没有钱。", "error_description": "位置错误：“再则”应直接引出列举的后一项，前面不能加“要”。正确说法是“再则也没有钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一是要学习，再则了要锻炼身体。", "corrected_sentence": "一是要学习，再则要锻炼身体。", "error_description": "误加“了”：“再则”是连词，后面不能加“了”，应说“再则要锻炼身体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
