INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到一个地方去，走着看看里面的东西。", "primary_collocate": null, "pronunciation": "cān guān", "ipa": "tsʰan˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "周末我们去参观博物馆。", "target_word": "参观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客在导游带领下参观古老的寺庙。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学先参观了校园，再去教室。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友搬了新家，请我去参观。", "target_word": "参观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们参观了故宫，走了一整天。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想参观一下你的新办公室。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来北京的客人都想参观长城。", "target_word": "参观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友排着队参观动物园。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观完老城区，我们去吃晚饭。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你有空来参观我们的学校。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参观了", "label": "体标"}, {"form": "参观过", "label": "体标"}, {"form": "参观参观", "label": "重叠"}, {"form": "參觀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "到某个地方去，边走边看里面的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": true, "explanation": "正确：参观是到博物馆去边走边看，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象不是博物馆，不能说“去洗博物馆”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与去博物馆看展品的意思不符。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“博物馆”作宾语。"}], "explanations": {"参观": "正确：参观是到博物馆去边走边看，符合句意。", "洗": "搭配：“洗”的对象不是博物馆，不能说“去洗博物馆”。", "唱": "语义：“唱”指唱歌，与去博物馆看展品的意思不符。", "跳": "配价：“跳”是不及物动词，不能带“博物馆”作宾语。"}, "sentence_index": 0, "correct_answer": "参观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去医院参观生病的爷爷。", "explanation": "这里应该用〈探望〉。参观用于地方和展览，去医院看病人要用探望。"}, {"text": "我们在体育馆参观了比赛。", "explanation": "这里应该用〈观看〉。参观是到地方去看展品，比赛要用观看。"}, {"text": "他认真参观这个问题。", "explanation": "这里应该用〈思考〉。参观是实地看，不用于思考问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": true, "explanation": "正确：参观是到长城去边走边看，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，长城不能吃。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“长城”作宾语。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球类等，不能说“踢长城”。"}], "explanations": {"参观": "正确：参观是到长城去边走边看，符合句意。", "吃": "搭配：“吃”的对象是食物，长城不能吃。", "睡": "配价：“睡”是不及物动词，不能带“长城”作宾语。", "踢": "搭配：“踢”的对象是球类等，不能说“踢长城”。"}, "sentence_index": 6, "correct_answer": "参观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在音乐厅参观音乐。", "explanation": "这里应该用〈欣赏〉。参观是到地方去看展品，欣赏音乐要用欣赏。"}, {"text": "医生用听诊器参观病人的心跳。", "explanation": "这里应该用〈听〉。参观用于地方和展览，听心跳要用听。"}, {"text": "我参观了这里的温暖。", "explanation": "这里应该用〈感受〉。参观是实地看东西，温暖是要用心去感受的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在参观完博物馆，就回家了。", "corrected_sentence": "我们参观完博物馆，就回家了。", "error_description": "错误：“正在”表示动作进行中，与表示完成的结果补语“完”不能同用。正确：“我们参观完博物馆，就回家了”，去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没参观了那所学校。", "corrected_sentence": "我还没参观过那所学校。", "error_description": "错误：表示“还没有过经历”时，“参观”后应用“过”，不能用“了”。正确：“我还没参观过那所学校”，“过”表示经历过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
