INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "津贴是除了工资以外，另外发的一点钱。", "primary_collocate": null, "pronunciation": "jīn tiē", "ipa": "tɕin˥ tʰiɛ˥", "syllable_count": 2, "sentences": [{"text": "除了工资，公司每月还给我两百元津贴。", "target_word": "津贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了工资，他还有一份津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔津贴不多，但也是公司的心意。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工资之外，他每月还领一点津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工资以外，公司还发津贴。", "target_word": "津贴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月的津贴已经发给大家了。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王把这个月多发的津贴给了妈妈。", "target_word": "津贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天在外面干活很辛苦，公司多发了一点津贴。", "target_word": "津贴", "complexity_tier": "T3", "furigana": "xià tiān zài wài miàn gàn huó hěn xīn kǔ gōng sī duō fā le yì diǎn jīn tiē", "sentence_source": "generated"}, {"text": "我的工资不高，津贴也很少。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说下个月会多给我一点津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份津贴", "label": "量词"}, {"form": "一笔津贴", "label": "量词"}, {"form": "交通津贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "工资以外另外发的一点钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "津贴", "is_correct": true, "explanation": "津贴指工资以外另外发的钱，与“除了工资”相合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：句中已有“除了工资”，再说“两百元工资”与前文矛盾。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是被扣去的钱，不是公司发给我的，与“给我”相反。"}, {"text": "房租", "is_correct": false, "explanation": "配价：“给我”的钱由公司付出，房租是我付给房东的，不能说“给我”。"}], "explanations": {"津贴": "津贴指工资以外另外发的钱，与“除了工资”相合。", "工资": "语义：句中已有“除了工资”，再说“两百元工资”与前文矛盾。", "罚款": "语义：罚款是被扣去的钱，不是公司发给我的，与“给我”相反。", "房租": "配价：“给我”的钱由公司付出，房租是我付给房东的，不能说“给我”。"}, "sentence_index": 0, "correct_answer": "津贴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师因为他考了第一，奖给他一笔津贴。", "explanation": "这里应该用〈奖金〉。津贴是工资之外按规定发给的补助，不是因成绩而给的奖励，奖励要用奖金。"}, {"text": "每学期开学，他都要交一笔津贴。", "explanation": "这里应该用〈学费〉。津贴是发给人的钱，学费是要交出去的钱，方向不合，不能说交津贴。"}, {"text": "租房时，他交给房东一笔津贴。", "explanation": "这里应该用〈押金〉。押金是交给房东的钱，津贴是发给人的钱，方向不合，不能交给房东。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "津贴", "is_correct": true, "explanation": "津贴是多发的补助钱，可以发给家人，与句意相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是要交给学校的钱，不能由小王“多发”给妈妈。"}, {"text": "押金", "is_correct": false, "explanation": "搭配：“发”不接“押金”，押金是交出去的钱。"}, {"text": "房费", "is_correct": false, "explanation": "语义：房费是要付给房东的，与“多发”的补助方向不合。"}], "explanations": {"津贴": "津贴是多发的补助钱，可以发给家人，与句意相合。", "学费": "语义：学费是要交给学校的钱，不能由小王“多发”给妈妈。", "押金": "搭配：“发”不接“押金”，押金是交出去的钱。", "房费": "语义：房费是要付给房东的，与“多发”的补助方向不合。"}, "sentence_index": 6, "correct_answer": "津贴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他替邻居照看了一周孩子，邻居给了他一笔津贴。", "explanation": "这里应该用〈报酬〉。津贴是按规定发给的补助，邻里之间临时的酬劳不叫津贴。"}, {"text": "对方赔给他一笔津贴。", "explanation": "这里应该用〈赔偿金〉。津贴是按规定发给的补助，不是对损失的赔付。"}, {"text": "春节那天，叔叔给我一笔津贴。", "explanation": "这里应该用〈压岁钱〉。津贴是按规定发给的补助，春节时长辈给晚辈的礼钱不叫津贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司每月给我一只津贴。", "corrected_sentence": "公司每月给我一份津贴。", "error_description": "量词错误：津贴应与“份”或“笔”搭配，不能用“只”（“只”多用于动物或成对物件中的一个）。应说“一份津贴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月公司给我发了一只津贴。", "corrected_sentence": "这个月公司给我发了一笔津贴。", "error_description": "量词错误：津贴应说“笔”或“份”，“只”多用于动物或成对物件中的一个，不能用来计量津贴。应说“一笔津贴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
