INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工资以外按规定发给的补助费用。", "primary_collocate": null, "pronunciation": "jīn tiē", "ipa": "tɕin˥ tʰiɛ˥", "syllable_count": 2, "sentences": [{"text": "按规定，出差的人每天有津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校按规定给老师发津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家规定，医生上夜班可以拿津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出差的时候，公司每天发一百元津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份津贴是国家给学生的补助。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他申请了津贴，可是没有通过。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高温天气，按规定要给工人发津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔津贴是按规定算出来的。", "target_word": "津贴", "complexity_tier": "T3", "furigana": "zhè bǐ jīn tiē shì àn guī dìng suàn chū lai de", "sentence_source": "generated"}, {"text": "研究生每月可以领到学校的津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "领津贴的人要先填一张表。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份津贴", "label": "量词"}, {"form": "一笔津贴", "label": "量词"}, {"form": "住房津贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "按规定发给的补助费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "津贴", "is_correct": true, "explanation": "津贴是按规定发给的补助费用，与“按规定”“出差”相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是要交给学校的钱，出差的人不会“有”这笔钱作为每天的补助。"}, {"text": "假期", "is_correct": false, "explanation": "搭配：“每天”计量的是钱款或补助，“每天有假期”不成立。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位是学业的认定，与按规定每天发放的补助无关。"}], "explanations": {"津贴": "津贴是按规定发给的补助费用，与“按规定”“出差”相合。", "学费": "语义：学费是要交给学校的钱，出差的人不会“有”这笔钱作为每天的补助。", "假期": "搭配：“每天”计量的是钱款或补助，“每天有假期”不成立。", "学位": "语义：学位是学业的认定，与按规定每天发放的补助无关。"}, "sentence_index": 0, "correct_answer": "津贴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为成绩好，拿到了一笔津贴。", "explanation": "这里应该用〈奖学金〉。津贴是按规定发给的补助，因成绩好而颁发的钱要用奖学金。"}, {"text": "工厂因为事故，给工人一大笔津贴。", "explanation": "这里应该用〈赔偿金〉。津贴是按规定发给的补助，不是对事故损失的赔偿。"}, {"text": "他把钱存进银行，每年能拿到一笔津贴。", "explanation": "这里应该用〈利息〉。银行存款的收益叫利息，津贴是按规定发给的补助，不由银行发放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "津贴", "is_correct": true, "explanation": "津贴是按规定发给工人的补助，与高温天气的语境相合。"}, {"text": "罚单", "is_correct": false, "explanation": "语义：罚单是发给违章者的，与发给工人的补助不合。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：奖状是表彰成绩的，与高温天气下按规定的补助不符。"}, {"text": "病历", "is_correct": false, "explanation": "搭配：“发”不接“病历”，病历由医院开具，不能由单位发给工人当补助。"}], "explanations": {"津贴": "津贴是按规定发给工人的补助，与高温天气的语境相合。", "罚单": "语义：罚单是发给违章者的，与发给工人的补助不合。", "奖状": "语义：奖状是表彰成绩的，与高温天气下按规定的补助不符。", "病历": "搭配：“发”不接“病历”，病历由医院开具，不能由单位发给工人当补助。"}, "sentence_index": 6, "correct_answer": "津贴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他替邻居照看了一周孩子，邻居给了他一笔津贴。", "explanation": "这里应该用〈报酬〉。津贴是按规定发给的补助，邻里之间临时的酬劳不叫津贴。"}, {"text": "租房时，他交了一笔津贴。", "explanation": "这里应该用〈押金〉。押金是交给房东的钱，津贴是发给人的补助，方向不合。"}, {"text": "春节那天，叔叔给我一笔津贴。", "explanation": "这里应该用〈压岁钱〉。津贴是按规定发给的补助，春节时长辈给晚辈的礼钱不叫津贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂每月给工人发一条津贴。", "corrected_sentence": "工厂每月给工人发一份津贴。", "error_description": "量词错误：津贴应说“份”或“笔”，“条”用于细长的东西，不能用来计量津贴。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每月按规定领一只津贴。", "corrected_sentence": "他每月按规定领一笔津贴。", "error_description": "量词错误：津贴应说“笔”或“份”，“只”不能用来计量津贴。应说“领一笔津贴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "相同：与「相反」构成反义，表示口味或爱好一致，正是句中所说的反面。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色，与「相反」的意思没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：形容质地，与「相反」没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容清洁程度，与「相反」没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "相同：与「相反」构成反义，表示口味或爱好一致，正是句中所说的反面。", "明亮": "明亮：形容光线或颜色，与「相反」的意思没有反义关系。", "柔软": "柔软：形容质地，与「相反」没有反义关系。", "干净": "干净：形容清洁程度，与「相反」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "相同：与「相反」构成反义，表示爱好与哥哥一样，正是句中所说的反面。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面或气氛，与「相反」没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：形容表面质地，与「相反」没有反义关系。"}, {"text": "甜美", "is_correct": false, "explanation": "甜美：形容味道或声音，与「相反」没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "相同：与「相反」构成反义，表示爱好与哥哥一样，正是句中所说的反面。", "热闹": "热闹：形容场面或气氛，与「相反」没有反义关系。", "粗糙": "粗糙：形容表面质地，与「相反」没有反义关系。", "甜美": "甜美：形容味道或声音，与「相反」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相反是和这个正好不一样。", "primary_collocate": null, "pronunciation": "xiāng fǎn", "ipa": "ɕi̯ɑŋ˥ fan˨˩", "syllable_count": 2, "sentences": [{"text": "我和他的想法正好相反。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "结果和我想的相反。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你说的和他说的完全相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥爱吃甜的，我和他相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以为我会哭，我的反应却正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人的性格正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说好，只有他的看法相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去海边，妹妹想去山上，我们的想法相反。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的结果和大家的预测正好相反。", "target_word": "相反", "complexity_tier": "T3", "furigana": "zhè cì bǐ sài de jié guǒ hé dà jiā de yù cè zhèng hǎo xiāng fǎn。", "sentence_source": "generated"}, {"text": "我喜欢安静，弟弟和我正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相反地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "两个人或事的想法、结果、性格正好不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：与「我」的想法正好对立，与句中「正好」搭配。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」形容光线或颜色，不能用来形容想法。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」说的是味道，想法没有咸淡之分。"}, {"text": "热", "is_correct": false, "explanation": "搭配：「热」不能修饰「想法」，「我和他的想法正好热」不成立。"}], "explanations": {"相反": "相反：与「我」的想法正好对立，与句中「正好」搭配。", "明亮": "语义：「明亮」形容光线或颜色，不能用来形容想法。", "咸": "语义：「咸」说的是味道，想法没有咸淡之分。", "热": "搭配：「热」不能修饰「想法」，「我和他的想法正好热」不成立。"}, "sentence_index": 0, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两根绳子的长度相反。", "explanation": "这里应该用〈相同〉。相反表示方向、立场或作用完全对立，说长度要用相同或不同，不能说相反。"}, {"text": "他和哥哥的年龄很相反。", "explanation": "这里应该用〈相差〉。说两人年龄的差距要用相差，相反表示对立，不能用来说年龄。"}, {"text": "这对双胞胎长得很相反。", "explanation": "这里应该用〈相似〉。说外貌像不像要用相似，相反只表示两者对立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：与「大家都说好」形成对立，只有他的看法与众人相反。"}, {"text": "陡", "is_correct": false, "explanation": "语义：「陡」形容坡度，不能用来形容看法。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」说的是味道，看法没有甜不甜之分。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」说的是温度，不能修饰「看法」。"}], "explanations": {"相反": "相反：与「大家都说好」形成对立，只有他的看法与众人相反。", "陡": "语义：「陡」形容坡度，不能用来形容看法。", "甜": "语义：「甜」说的是味道，看法没有甜不甜之分。", "烫": "搭配：「烫」说的是温度，不能修饰「看法」。"}, "sentence_index": 6, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两张纸的面积相反。", "explanation": "这里应该用〈相等〉。比较面积的大小是否一样要用相等，相反表示对立，不能用来说面积。"}, {"text": "这两座山的高度相反。", "explanation": "这里应该用〈相近〉。说高度接近要用相近，相反只表示对立。"}, {"text": "这些书排得很相反。", "explanation": "这里应该用〈整齐〉。说摆放得整洁要用整齐，相反不能描述摆放的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的兴趣从妹妹正好相反。", "corrected_sentence": "我的兴趣和妹妹正好相反。", "error_description": "介词用错：“相反”前应用“和”（或“与”“跟”）引出对比对象，“从”不能用来引出相反的对象。应把“从”改为“和”，写作“我的兴趣和妹妹正好相反”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的爱好和哥哥正好相反地。", "corrected_sentence": "我的爱好和哥哥正好相反。", "error_description": "错误：「相反地」。正确：「相反」。「相反地」是副词，要修饰后面的动词，作谓语时应说「相反」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
