INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "相同：与「相反」构成反义，表示路线一致，正是句中所说的反面。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面或气氛，与「相反」没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：形容表面质地，与「相反」没有反义关系。"}, {"text": "甜美", "is_correct": false, "explanation": "甜美：形容味道或声音，与「相反」没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "相同：与「相反」构成反义，表示路线一致，正是句中所说的反面。", "热闹": "热闹：形容场面或气氛，与「相反」没有反义关系。", "粗糙": "粗糙：形容表面质地，与「相反」没有反义关系。", "甜美": "甜美：形容味道或声音，与「相反」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事物的两个方面互相对立；方向、位置等完全不同。", "primary_collocate": null, "pronunciation": "xiāng fǎn", "ipa": "ɕi̯ɑŋ˥ fan˨˩", "syllable_count": 2, "sentences": [{"text": "两辆车往相反的方向开。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们的意见完全相反。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐在桌子相反的两边。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风是从相反的方向吹来的。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种药的作用正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他朝着和我相反的方向走了。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的看法相反，所以吵了起来。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好和坏是相反的两个词。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校和家在相反的方向，我每天要走很远。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的路线相反，所以在路上没有遇到。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相反地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "方向、位置完全不同，或意见、作用互相对立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：指两个方向完全对立，修饰「方向」，符合句意。"}, {"text": "厚", "is_correct": false, "explanation": "语义：「厚」说的是物体的厚薄，不能用来指方向。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：「辣」说的是味道，不能修饰「方向」。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」说的是形状，不能用来指方向。"}], "explanations": {"相反": "相反：指两个方向完全对立，修饰「方向」，符合句意。", "厚": "语义：「厚」说的是物体的厚薄，不能用来指方向。", "辣": "搭配：「辣」说的是味道，不能修饰「方向」。", "圆": "语义：「圆」说的是形状，不能用来指方向。"}, "sentence_index": 0, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两张桌子的高度相反。", "explanation": "这里应该用〈相同〉。说高度是否一样要用相同或不同，相反表示对立，不能用来说高度。"}, {"text": "这两个人的体重很相反。", "explanation": "这里应该用〈相差〉。说两人体重的差距要用相差，相反表示对立，不能用来说体重。"}, {"text": "这对双胞胎长得很相反。", "explanation": "这里应该用〈相似〉。说外貌像不像要用相似，相反只表示两者对立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：两人的看法对立，所以才吵了起来，符合句意。"}, {"text": "脆", "is_correct": false, "explanation": "语义：「脆」形容食物或东西的质地，不能用来形容看法。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」说的是味道，看法没有咸淡之分。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」说的是温度，不能修饰「看法」。"}], "explanations": {"相反": "相反：两人的看法对立，所以才吵了起来，符合句意。", "脆": "语义：「脆」形容食物或东西的质地，不能用来形容看法。", "咸": "语义：「咸」说的是味道，看法没有咸淡之分。", "烫": "搭配：「烫」说的是温度，不能修饰「看法」。"}, "sentence_index": 6, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个杯子的容量相反。", "explanation": "这里应该用〈相等〉。比较容量是否一样要用相等，相反表示对立，不能用来说容量。"}, {"text": "这两座山的高度相反。", "explanation": "这里应该用〈相近〉。说高度接近要用相近，相反只表示对立。"}, {"text": "这些书排得很相反。", "explanation": "这里应该用〈整齐〉。说摆放得整洁要用整齐，相反不能描述摆放的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人朝着相反地方向跑去。", "corrected_sentence": "两个人朝着相反的方向跑去。", "error_description": "错误：「相反地方向」，「地」用错了。「相反地」是副词形式，「地」用于修饰动词，这里修饰名词「方向」，应该用「的」。正确：「相反的方向」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的看法正好被相反。", "corrected_sentence": "他们的看法正好相反。", "error_description": "错误：「被」字句。正确：去掉「被」，说「正好相反」。「相反」是形容词，不能用在「被」字句中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看情况是等到那时候，再看是怎么样，再决定。", "primary_collocate": null, "pronunciation": "kàn qíng kuàng", "ipa": "kʰan˥˩ tɕʰiŋ˧˥ kʰuaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我现在不知道去不去，到时候看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天会不会下雨还不知道，那天再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在先不买票，等出发前看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我去不去，我说到时候看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先不用决定，到了那里再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年要不要换工作，明年再看情况吧。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的计划还没定，到时候看情况吧。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想现在说，等他回来了再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后要不要出去走走，吃完了看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先走着，到了路口再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看情況", "label": "繁体"}, {"form": "看情况而定", "label": "复合"}], "register": "口语", "sense_fingerprint": "先不决定，等到那时候再看再定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指到时候再看具体情形再决定，与“不知道去不去”相符。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“到时候出发”预设已经决定去，与“不知道去不去”矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不同意，与“不知道去不去”的未定状态不符。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”表示同意，与“不知道去不去”的未定状态不符。"}], "explanations": {"看情况": "“看情况”指到时候再看具体情形再决定，与“不知道去不去”相符。", "出发": "语义：“到时候出发”预设已经决定去，与“不知道去不去”矛盾。", "拒绝": "语义：“拒绝”表示不同意，与“不知道去不去”的未定状态不符。", "答应": "语义：“答应”表示同意，与“不知道去不去”的未定状态不符。"}, "sentence_index": 0, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "合同规定下周一必须交货，我们现在还要看情况。", "explanation": "这里应该用〈确定〉。“看情况”表示还没定，与“规定下周一必须交货”的既定安排矛盾。"}, {"text": "太阳每天从东边升起，我们还要看情况。", "explanation": "这里应该用〈确定〉。“看情况”表示还没定，而太阳东升是确定的规律，不能这样说。"}, {"text": "他已经付了钱，还在看情况。", "explanation": "这里应该用〈已经决定〉。“看情况”表示还没定，与“已经付了钱”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指到时候再根据情形决定，与“计划还没定”相符。"}, {"text": "完成", "is_correct": false, "explanation": "语义：计划还没定，谈不上“完成”。"}, {"text": "结束", "is_correct": false, "explanation": "语义：计划还没开始，不能说“结束”。"}, {"text": "失败", "is_correct": false, "explanation": "语义：计划还没定，不会“失败”。"}], "explanations": {"看情况": "“看情况”指到时候再根据情形决定，与“计划还没定”相符。", "完成": "语义：计划还没定，谈不上“完成”。", "结束": "语义：计划还没开始，不能说“结束”。", "失败": "语义：计划还没定，不会“失败”。"}, "sentence_index": 6, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案只有一个正确选项，我们看情况选吧。", "explanation": "这里应该用〈确定〉。“看情况”表示还没定，只有一个正确选项时不能再看情况选。"}, {"text": "这份合同签了字，我们看情况再签。", "explanation": "这里应该用〈已经签好〉。“看情况”表示还没定，合同已签字时不能再说看情况。"}, {"text": "这道题我已经算出答案，还要看情况。", "explanation": "这里应该用〈已经确定〉。“看情况”表示还没定，答案已经算出，就不该再看情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事我们暂时不谈，等结果出来再看情况了。", "corrected_sentence": "这件事我们暂时不谈，等结果出来再看情况。", "error_description": "助词错误：“再看情况了”；正确：“再看情况”。“再”表示以后要做的动作，句中还没发生，不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题先放着，等下周开会再看情况的。", "corrected_sentence": "这个问题先放着，等下周开会再看情况。", "error_description": "助词错误：句末多出“的”；“再看情况”已是完整谓语，应说“等下周开会再看情况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
