INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据具体情况再作决定。", "primary_collocate": null, "pronunciation": "kàn qíng kuàng", "ipa": "kʰan˥˩ tɕʰiŋ˧˥ kʰuaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "要不要带伞，得看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一天学多少个字，看情况，不一定。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给不给孩子零花钱，要看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "什么时候吃药，医生说要看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁还是打车，看情况再决定。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每周见几次面，要看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买多大的房子，得看情况，钱够不够。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去不去参加比赛，我要看情况再决定。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱可以便宜多少，老板说看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不要请假，看情况，小病就不用了。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看情況", "label": "繁体"}, {"form": "看情况而定", "label": "复合"}], "register": "口语", "sense_fingerprint": "根据具体情况来决定，没有固定做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指根据具体情形再决定，与“要不要带伞”相符。"}, {"text": "看见", "is_correct": false, "explanation": "语义：要不要带伞是决定问题，“看见”与之不符。"}, {"text": "答应", "is_correct": false, "explanation": "配价：“答应”需要承诺的内容，“得答应”没有所指。"}, {"text": "带伞", "is_correct": false, "explanation": "语义：句中已有“带伞”，“得带伞”重复，也不表示判断依据。"}], "explanations": {"看情况": "“看情况”指根据具体情形再决定，与“要不要带伞”相符。", "看见": "语义：要不要带伞是决定问题，“看见”与之不符。", "答应": "配价：“答应”需要承诺的内容，“得答应”没有所指。", "带伞": "语义：句中已有“带伞”，“得带伞”重复，也不表示判断依据。"}, "sentence_index": 0, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条规定很明确：每天八点准时开会，要看情况。", "explanation": "这里应该用〈必须〉。“看情况”表示没有固定做法，与“规定很明确”的既定安排矛盾。"}, {"text": "地铁票价是固定的，要看情况。", "explanation": "这里应该用〈一律〉。“看情况”表示要根据具体情形决定，票价统一时不能这样说。"}, {"text": "他每天六点起床，这是一贯的习惯，看情况。", "explanation": "这里应该用〈一直〉。“看情况”表示要根据情形决定，习惯已经固定时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指要根据具体条件再决定，与“钱够不够”的判断相符。"}, {"text": "看中", "is_correct": false, "explanation": "语义：“看中”指喜欢，与“钱够不够”的判断不符。"}, {"text": "出租", "is_correct": false, "explanation": "语义：买房子不是出租房子，句意不通。"}, {"text": "说话", "is_correct": false, "explanation": "配价：“说话”不能带“多大的房子”作宾语，句子不通。"}], "explanations": {"看情况": "“看情况”指要根据具体条件再决定，与“钱够不够”的判断相符。", "看中": "语义：“看中”指喜欢，与“钱够不够”的判断不符。", "出租": "语义：买房子不是出租房子，句意不通。", "说话": "配价：“说话”不能带“多大的房子”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的答案只有一个，要看情况。", "explanation": "这里应该用〈唯一〉。“看情况”表示没有固定答案，题目答案唯一时不能用。"}, {"text": "一周有七天，我们要看情况。", "explanation": "这里应该用〈客观事实〉。“看情况”表示要根据具体情形决定，一周七天这类事实不能这样说。"}, {"text": "会议时间早就定好了，要看情况。", "explanation": "这里应该用〈已定〉。“看情况”表示还没有固定做法，会议时间已定时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天去不去爬山，要看情况了再决定。", "corrected_sentence": "明天去不去爬山，要看情况再决定。", "error_description": "多字错误：“看情况”是动词短语，后面不能直接加“了”，应说“要看情况再决定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个周末去不去，还得看情况了。", "corrected_sentence": "这个周末去不去，还得看情况。", "error_description": "助词错误：“得”表示尚未发生的必要，不能与完成态“了”同用；“看情况了”应去掉“了”，说“还得看情况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
