INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来做东西的东西。", "primary_collocate": null, "pronunciation": "liào", "ipa": "li̯ɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "这块料很软，做裙子正合适。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做桌子得先选好料。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "料不够，这件衣服做不成。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一批料，打算自己做家具。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种料不便宜，做起来也很难。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把料搬到了车间里。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批料是新到的，大家快来看。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好料才能做出好东西。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看这块料，做外套怎么样？", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的料都很好，价格也不高。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块料", "label": "量词"}, {"form": "一批料", "label": "量词"}, {"form": "材料", "label": "复合"}, {"form": "原料", "label": "复合"}], "register": "中性", "sense_fingerprint": "指布、木头等可以用来制作成品的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "料", "is_correct": true, "explanation": "料（liào）：可用来做东西的材料，与释义一致。"}, {"text": "聊", "is_correct": false, "explanation": "聊（liáo）与 liào 声调不同（第二声与第四声），意思是聊天。"}, {"text": "亮", "is_correct": false, "explanation": "亮（liàng）与 liào 韵母不同（-ang 与 -ao），意思是明亮。"}, {"text": "尿", "is_correct": false, "explanation": "尿（niào）与 liào 声母不同（n 与 l），意思是小便。"}], "explanations": {"料": "料（liào）：可用来做东西的材料，与释义一致。", "聊": "聊（liáo）与 liào 声调不同（第二声与第四声），意思是聊天。", "亮": "亮（liàng）与 liào 韵母不同（-ang 与 -ao），意思是明亮。", "尿": "尿（niào）与 liào 声母不同（n 与 l），意思是小便。"}, "sentence_index": null, "correct_answer": "料"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头很硬，与“很软”相矛盾，也做不成裙子。"}, {"text": "料", "is_correct": true, "explanation": "“料”指可用来做裙子的材料，与“很软”“做裙子”相合。"}, {"text": "铁", "is_correct": false, "explanation": "搭配：“铁”一般说硬，不与“很软”搭配。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板不能用来做裙子，“很软”也与木板的特性不合。"}], "explanations": {"石头": "语义：石头很硬，与“很软”相矛盾，也做不成裙子。", "料": "“料”指可用来做裙子的材料，与“很软”“做裙子”相合。", "铁": "搭配：“铁”一般说硬，不与“很软”搭配。", "木板": "语义：木板不能用来做裙子，“很软”也与木板的特性不合。"}, "sentence_index": 0, "correct_answer": "料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一批料，准备期末考试。", "explanation": "这里应该用〈材料〉。“料”指制作东西的原料，不指学习用的资料。"}, {"text": "他正在图书馆查阅料，准备论文。", "explanation": "这里应该用〈资料〉。“料”不指书面信息，查阅的应是资料。"}, {"text": "运动员们正在检查料，准备下午的比赛。", "explanation": "这里应该用〈器材〉。“料”指制作东西的材料，不指比赛用的器材，“检查器材”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90789, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "料", "is_correct": true, "explanation": "料（liào）：可用来做东西的材料，与释义一致。"}, {"text": "量", "is_correct": false, "explanation": "量（liàng）与 liào 韵母不同（-ang 与 -ao），意思是数量。"}, {"text": "烙", "is_correct": false, "explanation": "烙（lào）比 liào 少了介音 i，声调相同，意思是烙饼。"}, {"text": "撩", "is_correct": false, "explanation": "撩（liāo）与 liào 声调不同（第一声与第四声），意思是撩拨。"}], "explanations": {"料": "料（liào）：可用来做东西的材料，与释义一致。", "量": "量（liàng）与 liào 韵母不同（-ang 与 -ao），意思是数量。", "烙": "烙（lào）比 liào 少了介音 i，声调相同，意思是烙饼。", "撩": "撩（liāo）与 liào 声调不同（第一声与第四声），意思是撩拨。"}, "sentence_index": null, "correct_answer": "料"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不会“新到”，也不会让大家来看。"}, {"text": "料", "is_correct": true, "explanation": "“料”指一批运来的材料，与“新到的”“大家快来看”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“新到”的东西，句子不成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以“新到”的货物，“这批月亮是新到的”不成立。"}], "explanations": {"空气": "语义：空气不会“新到”，也不会让大家来看。", "料": "“料”指一批运来的材料，与“新到的”“大家快来看”相合。", "天气": "语义：天气不是可以“新到”的东西，句子不成立。", "月亮": "语义：月亮不是可以“新到”的货物，“这批月亮是新到的”不成立。"}, "sentence_index": 6, "correct_answer": "料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们店里进了一只料，价格也不高。", "explanation": "这里应该用〈批〉。“只”用于动物或成对器物中的一个，不能用来数料。"}, {"text": "仓库里进了一辆料，价格也不高。", "explanation": "这里应该用〈批〉。“辆”用于车辆，不能用来数料。"}, {"text": "仓库里堆着一座料，价格也不高。", "explanation": "这里应该用〈批〉。“座”用于山、桥、房屋等大型固定物，不能用来数料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两只料，够做一件外套。", "corrected_sentence": "他买了两块料，够做一件外套。", "error_description": "量词错误：“料”应用“块”或“批”计量，“只”用于动物或成对器物中的一个，不能用于料。应改为“两块料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天买着一批料，准备做夏装。", "corrected_sentence": "他昨天买了一批料，准备做夏装。", "error_description": "“着”误用：“买”表示已完成的动作应用“了”，“着”表示持续状态，与“昨天”的已完成时间矛盾。正确说法是“他昨天买了一批料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
