INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可供制作的材料。", "primary_collocate": null, "pronunciation": "liào", "ipa": "li̯ɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "厂里的料用完了，今天不能开工。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批料质量好，做出来的鞋很结实。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先把料切开，再慢慢打磨。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说这块料太小，做不了大桌子。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做衣服的料要先洗一洗。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有好料，做不出好东西。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在店里挑料。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种料很轻，做包最合适。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "料备好了，明天就可以开始做。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用剩下的料做了一把小椅子。", "target_word": "料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块料", "label": "量词"}, {"form": "一批料", "label": "量词"}, {"form": "材料", "label": "复合"}, {"form": "原料", "label": "复合"}], "register": "中性", "sense_fingerprint": "指工厂、作坊里供加工制作用的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "料", "is_correct": true, "explanation": "料（liào）：供工厂加工制作用的材料，与释义一致。"}, {"text": "聊", "is_correct": false, "explanation": "聊（liáo）与 liào 声调不同（第二声与第四声），意思是聊天。"}, {"text": "撩", "is_correct": false, "explanation": "撩（liāo）与 liào 声调不同（第一声与第四声），意思是撩拨。"}, {"text": "烙", "is_correct": false, "explanation": "烙（lào）比 liào 少了介音 i，声调相同，意思是烙饼。"}], "explanations": {"料": "料（liào）：供工厂加工制作用的材料，与释义一致。", "聊": "聊（liáo）与 liào 声调不同（第二声与第四声），意思是聊天。", "撩": "撩（liāo）与 liào 声调不同（第一声与第四声），意思是撩拨。", "烙": "烙（lào）比 liào 少了介音 i，声调相同，意思是烙饼。"}, "sentence_index": null, "correct_answer": "料"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是可以“用完”的消耗品，“用完”与“不能开工”没有因果关系。"}, {"text": "料", "is_correct": true, "explanation": "“料”指工厂加工用的材料，用完了就不能开工，与句意相合。"}, {"text": "工人", "is_correct": false, "explanation": "搭配：“用完”多用于物品，不用于人，“工人用完了”不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户与开工无关，“用完”也不适用于窗户。"}], "explanations": {"桌子": "语义：桌子不是可以“用完”的消耗品，“用完”与“不能开工”没有因果关系。", "料": "“料”指工厂加工用的材料，用完了就不能开工，与句意相合。", "工人": "搭配：“用完”多用于物品，不用于人，“工人用完了”不成立。", "窗户": "语义：窗户与开工无关，“用完”也不适用于窗户。"}, "sentence_index": 0, "correct_answer": "料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人正在组装料，准备出货。", "explanation": "这里应该用〈零件〉。“料”指加工前的材料，不能被“组装”。"}, {"text": "他去图书馆查料，准备写论文。", "explanation": "这里应该用〈资料〉。“料”指做东西的材料，不指书面信息，不能用来“查”。"}, {"text": "老师正在修理料，学生们在一旁看着。", "explanation": "这里应该用〈设备〉。“料”指可供制作的材料，不指需要修理的设备；“修理”搭配的是机器、电脑等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90790, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "料", "is_correct": true, "explanation": "料（liào）：供工厂加工制作用的材料，与释义一致。"}, {"text": "亮", "is_correct": false, "explanation": "亮（liàng）与 liào 韵母不同（-ang 与 -ao），意思是明亮。"}, {"text": "量", "is_correct": false, "explanation": "量（liàng）与 liào 韵母不同（-ang 与 -ao），意思是数量。"}, {"text": "尿", "is_correct": false, "explanation": "尿（niào）与 liào 声母不同（n 与 l），意思是小便。"}], "explanations": {"料": "料（liào）：供工厂加工制作用的材料，与释义一致。", "亮": "亮（liàng）与 liào 韵母不同（-ang 与 -ao），意思是明亮。", "量": "量（liàng）与 liào 韵母不同（-ang 与 -ao），意思是数量。", "尿": "尿（niào）与 liào 声母不同（n 与 l），意思是小便。"}, "sentence_index": null, "correct_answer": "料"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不能被“挑”，“店里挑空气”不成立。"}, {"text": "料", "is_correct": true, "explanation": "“料”指店里可供挑选的加工材料，与“挑”相合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：店里没有“作业”可挑，句子意思不通。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“挑”多用于选购物品，不说“挑病人”。"}], "explanations": {"空气": "语义：空气不能被“挑”，“店里挑空气”不成立。", "料": "“料”指店里可供挑选的加工材料，与“挑”相合。", "作业": "语义：店里没有“作业”可挑，句子意思不通。", "病人": "搭配：“挑”多用于选购物品，不说“挑病人”。"}, "sentence_index": 6, "correct_answer": "料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车间里放着一只料，等着加工。", "explanation": "这里应该用〈块〉或〈批〉。“只”用于动物或成对器物中的一个，不能用来数料。"}, {"text": "院子里停着一辆料，等着加工。", "explanation": "这里应该用〈块〉或〈批〉。“辆”用于车辆，不能用来数料。"}, {"text": "工地上堆着一座料，等着运走。", "explanation": "这里应该用〈块〉或〈批〉。“座”用于山、桥、房屋等大型固定物，不能用来数料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车间里刚进了一头料，今天可以开工。", "corrected_sentence": "车间里刚进了一批料，今天可以开工。", "error_description": "量词错误：“头”用于牲畜等大型动物，不能用来数料。料应用“批”或“块”计量，应改为“一批料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂里进了一批料好，马上就能开工。", "corrected_sentence": "工厂里进了一批好料，马上就能开工。", "error_description": "语序错误：修饰“料”的形容词“好”应放在名词前，说“好料”，不能说“料好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
