INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90805, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "用来说东西的长短、粗细、厚薄等的很小的长度单位。", "primary_collocate": null, "pronunciation": "háo mǐ", "ipa": "xaʊ˧˥ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这只小虫只有三毫米长。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玻璃厚五毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发只长了两毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根针比一毫米还细。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上有一道一毫米宽的线。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小蚂蚁大约四毫米长。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸薄得只有零点一毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铅笔芯只有零点五毫米粗。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这根线剪短两毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗米粒比五毫米还短。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方毫米", "label": "复合"}, {"form": "立方毫米", "label": "复合"}], "register": "中性", "sense_fingerprint": "毫米：说明东西很小、很短、很薄时用的小单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毫米", "is_correct": true, "explanation": "正确：毫米是长度单位，可以说小虫有三毫米长。"}, {"text": "公斤", "is_correct": false, "explanation": "搭配：“长”说的是长度，要用长度单位，“公斤”是重量单位，不能说“三公斤长”。"}, {"text": "小时", "is_correct": false, "explanation": "语义：小时是时间单位，不能用来量小虫的长短。"}, {"text": "公顷", "is_correct": false, "explanation": "语义：公顷是面积单位，不能用来量小虫的长度。"}], "explanations": {"毫米": "正确：毫米是长度单位，可以说小虫有三毫米长。", "公斤": "搭配：“长”说的是长度，要用长度单位，“公斤”是重量单位，不能说“三公斤长”。", "小时": "语义：小时是时间单位，不能用来量小虫的长短。", "公顷": "语义：公顷是面积单位，不能用来量小虫的长度。"}, "sentence_index": 0, "correct_answer": "毫米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼高一百毫米。", "explanation": "这里应该用〈米〉。毫米只用于很小的长度，大楼的高度要用米。"}, {"text": "他的体重是六十毫米。", "explanation": "这里应该用〈千克〉。毫米是长度单位，只能说长度，说体重要用千克。"}, {"text": "这块地的面积是五毫米。", "explanation": "这里应该用〈平方米〉。毫米是长度单位，说面积要用平方单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫米", "is_correct": true, "explanation": "正确：毫米是长度单位，可以说这张纸薄到零点一毫米。"}, {"text": "斤", "is_correct": false, "explanation": "语义：斤是重量单位，“薄”说的是厚度，不能用重量来量。"}, {"text": "秒", "is_correct": false, "explanation": "搭配：“薄”说的是厚薄，不能与时间单位搭配。"}, {"text": "亩", "is_correct": false, "explanation": "语义：亩是面积单位，不能用来量纸的厚度。"}], "explanations": {"毫米": "正确：毫米是长度单位，可以说这张纸薄到零点一毫米。", "斤": "语义：斤是重量单位，“薄”说的是厚度，不能用重量来量。", "秒": "搭配：“薄”说的是厚薄，不能与时间单位搭配。", "亩": "语义：亩是面积单位，不能用来量纸的厚度。"}, "sentence_index": 6, "correct_answer": "毫米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了三毫米苹果。", "explanation": "这里应该用〈个〉。毫米是长度单位，不能用来数苹果。"}, {"text": "我等了五毫米。", "explanation": "这里应该用〈分钟〉。毫米量长度，不量时间。"}, {"text": "他今年十毫米了。", "explanation": "这里应该用〈岁〉。毫米量长度，不能用来说年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗钉子长三个毫米。", "corrected_sentence": "这颗钉子长三毫米。", "error_description": "错误：数词和“毫米”之间多加了“个”。正确：“三毫米”。毫米本身是量词，数词后面直接接它，不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张卡片厚零点三的毫米。", "corrected_sentence": "这张卡片厚零点三毫米。", "error_description": "错误：数量和“毫米”之间多加了“的”。正确：“零点三毫米”。量词前面直接接数量，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
