INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90826, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "可以认为是；勉强称得上。", "primary_collocate": null, "pronunciation": "suàn shì", "ipa": "suan˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个房间很小，勉强算是一间卧室。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只会说几句，勉强算是学过汉语。", "target_word": "算是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只有一点雨，勉强算是下雨了。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只是一张桌子，勉强算是我的书房。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑完了，勉强算是完成比赛。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几个字写得不好看，但勉强算是会写。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只做了一道菜，勉强算是请客。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "六十分，勉强算是及格了。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小路很窄，勉强算是一条路。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚学了三天，勉强算是会游泳。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不算是", "label": "否定"}, {"form": "勉强算是", "label": "复合"}], "register": "口语", "sense_fingerprint": "勉强称得上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "算是", "is_correct": true, "explanation": "算是表示勉强可以认为是，与“很小”“勉强”的语境相合。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”不能接“卧室”，句子不成立。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与“勉强认为是一间卧室”的判断不合。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的对象不能是房间，“一间卧室”不能被打碎。"}], "explanations": {"算是": "算是表示勉强可以认为是，与“很小”“勉强”的语境相合。", "吃掉": "搭配：“吃掉”不能接“卧室”，句子不成立。", "讨厌": "语义：“讨厌”表示不喜欢，与“勉强认为是一间卧室”的判断不合。", "打碎": "搭配：“打碎”的对象不能是房间，“一间卧室”不能被打碎。"}, "sentence_index": 0, "correct_answer": "算是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气跑了三十公里，勉强算是跑步。", "explanation": "这里应该用〈真正〉。跑了三十公里远超跑步的门槛，〈勉强算是〉表示刚够标准，此处的说法与实际不符。"}, {"text": "一斤算是五百克。", "explanation": "这里应该用〈等于〉。换算关系是精确的，〈算是〉表示勉强称得上，不能用于换算。"}, {"text": "这块石头有十吨重，勉强算是轻的。", "explanation": "这里应该用〈沉重〉。十吨远超轻的标准，〈勉强算是〉表示刚够标准，用于此处不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算是", "is_correct": true, "explanation": "算是表示勉强可以认为是，与“只做了一道菜”的语境相合。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不许，与“勉强认为是请客”的评价相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，无法表示认定“是请客”的判断。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”不能接“请客”，请客不能被拆开。"}], "explanations": {"算是": "算是表示勉强可以认为是，与“只做了一道菜”的语境相合。", "禁止": "语义：“禁止”表示不许，与“勉强认为是请客”的评价相反。", "忘记": "语义：“忘记”指记不住，无法表示认定“是请客”的判断。", "拆开": "搭配：“拆开”不能接“请客”，请客不能被拆开。"}, "sentence_index": 6, "correct_answer": "算是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我身高一米八，勉强算是一米八。", "explanation": "这里应该用〈是〉。身高是确定的数字，〈算是〉表示勉强称得上，用于确定的数字不合适。"}, {"text": "这门课我考了满分，勉强算是及格。", "explanation": "这里的〈勉强算是〉只用于刚够标准的情况，考了满分远超及格线，应说〈轻松及格〉。"}, {"text": "他是全班第一，勉强算是优秀。", "explanation": "这里应该用〈十分优秀〉。全班第一已明显达标，〈勉强算是〉只用于刚够标准的情况，此处不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张小桌子勉强算是是书桌。", "corrected_sentence": "这张小桌子勉强算是书桌。", "error_description": "重复：“算是”已含“是”，不能再加一个“是”，应说“这张小桌子勉强算是书桌”，表示勉强可以认为是书桌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天只学一个小时，勉强算是是努力。", "corrected_sentence": "我每天只学一个小时，勉强算是努力。", "error_description": "重复：“算是”已含“是”，不能再加一个“是”，应说“勉强算是努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
