INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经费是做一件事要花的钱。", "primary_collocate": null, "pronunciation": "jīng fèi", "ipa": "tɕiŋ˥ fei˥˩", "syllable_count": 2, "sentences": [{"text": "学校今年的经费不够，不能买新书。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动需要多少经费？", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的经费只有五千元。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给小组一笔经费去做调查。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经费用完了，实验只好停下来。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在想办法找经费。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给旅行活动准备了一些经费。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的经费是谁出的？", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经费太少，我们没有租大教室。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长说明年会多给社团一点经费。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔经费", "label": "量词"}, {"form": "科研经费", "label": "复合"}, {"form": "教育经费", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事要花的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6318cb82-f6f5-4ae9-b8d4-8cf41127d09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经费", "is_correct": true, "explanation": "“经费”指办事用的钱，这里是学校的钱不够，买不了新书。"}, {"text": "操场", "is_correct": false, "explanation": "语义：“操场”是场地，与“经费不够，不能买新书”没有关系。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习的结果，说“成绩不够”无法导致“不能买新书”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说人或物的岁数，不说“学校今年的年龄”。"}], "explanations": {"经费": "“经费”指办事用的钱，这里是学校的钱不够，买不了新书。", "操场": "语义：“操场”是场地，与“经费不够，不能买新书”没有关系。", "成绩": "语义：“成绩”指学习的结果，说“成绩不够”无法导致“不能买新书”。", "年龄": "搭配：“年龄”一般说人或物的岁数，不说“学校今年的年龄”。"}, "sentence_index": 0, "correct_answer": "经费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家的经费发展得很快。", "explanation": "这里应该用〈经济〉。“经费”指办事用的钱，不能说“发展得很快”。"}, {"text": "这件衣服的经费太贵了，我没买。", "explanation": "这里应该用〈价格〉。“经费”指办事用的钱，不能用来说商品的价钱。"}, {"text": "他的经费很强，大家都佩服他。", "explanation": "这里应该用〈能力〉。“经费”指钱，不能用来形容人的办事本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经费", "is_correct": true, "explanation": "“经费”指用于办事的钱，这里是为旅行活动准备的钱。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“准备”不能带“天气”作宾语，不说“准备了一些天气”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能作“准备”的对象。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“地震”是自然灾害，不能拿来准备，与旅行活动无关。"}], "explanations": {"经费": "“经费”指用于办事的钱，这里是为旅行活动准备的钱。", "天气": "搭配：“准备”不能带“天气”作宾语，不说“准备了一些天气”。", "身高": "搭配：“身高”只用于人或动物，不能作“准备”的对象。", "地震": "语义：“地震”是自然灾害，不能拿来准备，与旅行活动无关。"}, "sentence_index": 6, "correct_answer": "经费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的经费很好吃，大家都喜欢。", "explanation": "这里应该用〈饭菜〉。“经费”是钱，不能用来形容味道。"}, {"text": "这份经费很贵，大家都很喜欢。", "explanation": "这里应该用〈礼物〉。“经费”是用来办事的钱，不能当作礼物来说“很贵，大家都很喜欢”。"}, {"text": "这次活动的经费很短，大家都没玩够。", "explanation": "这里应该用〈时间〉。“经费”是钱，不能用来说活动时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张经费要尽快批下来。", "corrected_sentence": "这笔经费要尽快批下来。", "error_description": "错误：“经费”是一笔款项，量词应用“笔”，不用“张”。正确：“这笔经费要尽快批下来。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把经费的用完了。", "corrected_sentence": "他把经费用完了。", "error_description": "错误：“经费”后面不能加结构助词“的”，“把”字句中“经费”直接作宾语。正确：“他把经费用完了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
