INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用某个东西的人。", "primary_collocate": null, "pronunciation": "yòng jiā", "ipa": "jʊŋ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这个手机的用家都说电池很好。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好用不好用，要问用家。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂家请用家写了一些意见。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种笔的用家大多是学生。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为这台电脑的用家，我很满意。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新款汽车的用家越来越多。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的用家都能免费下载，真划算。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用家说，这把伞太小了。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老用家都知道，这个按钮不能按。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店想听听用家的想法。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "使用某种东西或产品的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用家", "is_correct": true, "explanation": "用家指使用这个手机的人，填入后句意通顺。"}, {"text": "盒子", "is_correct": false, "explanation": "搭配：“都说……很好”的主语需要是能说话的人，“盒子”不能说话。"}, {"text": "铃声", "is_correct": false, "explanation": "语义：铃声不会评价电池，句意不通。"}, {"text": "屏幕", "is_correct": false, "explanation": "语义：屏幕是部件，不会“说”电池好，句意不通。"}], "explanations": {"用家": "用家指使用这个手机的人，填入后句意通顺。", "盒子": "搭配：“都说……很好”的主语需要是能说话的人，“盒子”不能说话。", "铃声": "语义：铃声不会评价电池，句意不通。", "屏幕": "语义：屏幕是部件，不会“说”电池好，句意不通。"}, "sentence_index": 0, "correct_answer": "用家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用家每天给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病的是医生，用家指使用某个东西的人，不能替病人诊治。"}, {"text": "用家在柜台前排队付款。", "explanation": "这里应该用〈顾客〉。排队付款的是顾客，用家指使用某个东西的人，不指到店排队的人。"}, {"text": "这个用家的门很大，我们一起进去。", "explanation": "这里把〈用家〉误当成房屋，用家指使用产品的人，不指地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用家", "is_correct": true, "explanation": "用家指使用这个软件的人，填入后句意通顺。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“免费下载”的对象应是软件或文件，“包装”不能被下载。"}, {"text": "按钮", "is_correct": false, "explanation": "语义：按钮是界面元素，不能被下载，句意不通。"}, {"text": "硬盘", "is_correct": false, "explanation": "语义：硬盘是硬件，不是用户，句中不能说它可以免费下载。"}], "explanations": {"用家": "用家指使用这个软件的人，填入后句意通顺。", "包装": "搭配：“免费下载”的对象应是软件或文件，“包装”不能被下载。", "按钮": "语义：按钮是界面元素，不能被下载，句意不通。", "硬盘": "语义：硬盘是硬件，不是用户，句中不能说它可以免费下载。"}, "sentence_index": 6, "correct_answer": "用家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用家负责收钱。", "explanation": "这里应该用〈营业员〉。收钱的是店方人员，用家指使用产品的人。"}, {"text": "用家在生产线上组装产品。", "explanation": "这里应该用〈工人〉。用家指使用产品的人，不在生产线上工作。"}, {"text": "用家在教室里讲课。", "explanation": "这里应该用〈老师〉。在教室里讲课的是老师，用家指使用某个东西的人，与讲课无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台冰箱的一台用家说，它很省电。", "corrected_sentence": "这台冰箱的一位用家说，它很省电。", "error_description": "量词错误：用家指人，量词应用「位」或「个」，不能用「台」（「台」用于机器）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条新用家说，这款电饭煲很好用。", "corrected_sentence": "一位新用家说，这款电饭煲很好用。", "error_description": "量词错误：用家指人，量词应用「位」，不能用「条」（「条」用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
