INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90845, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体觉得很难受，像被打了一样。", "primary_collocate": null, "pronunciation": "tòng", "ipa": "tʰʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他打了我一拳，我的肚子很痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天跑了十公里，今天腿很痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我摔了一跤，膝盖特别痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球打到他的头，他一直说痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你按这里的时候，会不会痛？", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一针打下去，我的手臂有点痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门夹到了儿子的脚，他痛得哭了。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打完篮球，我全身都痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻地按，我就不那么痛了。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人撞了我的背，现在还很痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头痛", "label": "复合"}, {"form": "牙痛", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体被打、撞或运动后觉得难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "痛", "is_correct": true, "explanation": "tòng（第四声）是“痛”，表示身体因被打而难受。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 tòng（第四声）声调不同，意思是相同。"}, {"text": "通", "is_correct": false, "explanation": "tōng（第一声）与 tòng（第四声）声调不同，意思是通过、通畅。"}, {"text": "洞", "is_correct": false, "explanation": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是洞穴。"}, {"text": "动", "is_correct": false, "explanation": "dòng 与 tòng 声母不同（d 与 t），意思是活动、移动。"}, {"text": "桶", "is_correct": false, "explanation": "tǒng（第三声）与 tòng（第四声）声调不同，意思是水桶。"}, {"text": "铜", "is_correct": false, "explanation": "tóng（第二声）与 tòng（第四声）声调不同，意思是铜。"}], "explanations": {"痛": "tòng（第四声）是“痛”，表示身体因被打而难受。", "同": "tóng（第二声）与 tòng（第四声）声调不同，意思是相同。", "通": "tōng（第一声）与 tòng（第四声）声调不同，意思是通过、通畅。", "洞": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是洞穴。", "动": "dòng 与 tòng 声母不同（d 与 t），意思是活动、移动。", "桶": "tǒng（第三声）与 tòng（第四声）声调不同，意思是水桶。", "铜": "tóng（第二声）与 tòng（第四声）声调不同，意思是铜。"}, "sentence_index": null, "correct_answer": "痛"}, "level_3": {"options": [{"text": "痛", "is_correct": true, "explanation": "“痛”正确：被打后肚子会感到疼痛，符合语境。"}, {"text": "乖", "is_correct": false, "explanation": "语义：“乖”形容孩子或动物听话，不能形容肚子的感觉。"}, {"text": "整", "is_correct": false, "explanation": "搭配：“整”说完整、整齐，不能用来形容身体的感觉。"}, {"text": "静", "is_correct": false, "explanation": "语义：“静”说环境或心情安静，与被打后的身体疼痛不合。"}], "explanations": {"痛": "“痛”正确：被打后肚子会感到疼痛，符合语境。", "乖": "语义：“乖”形容孩子或动物听话，不能形容肚子的感觉。", "整": "搭配：“整”说完整、整齐，不能用来形容身体的感觉。", "静": "语义：“静”说环境或心情安静，与被打后的身体疼痛不合。"}, "sentence_index": 0, "correct_answer": "痛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个柠檬很痛。", "explanation": "这里应该用〈酸〉。“酸”形容味道，柠檬的味道要说酸；“痛”只用于身体或心里的疼痛，不能形容味道。"}, {"text": "这个箱子很痛。", "explanation": "这里应该用〈重〉。“重”形容分量，箱子的轻重要说重；“痛”只用于身体或心里的疼痛，不能形容重量。"}, {"text": "这个房间很痛。", "explanation": "这里应该用〈宽〉。“宽”形容空间的大小，房间的宽敞要说宽；“痛”不能用来形容空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90845, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "痛", "is_correct": true, "explanation": "tòng（第四声）是“痛”，表示身体或心里的难受。"}, {"text": "童", "is_correct": false, "explanation": "tóng（第二声）与 tòng（第四声）声调不同，意思是儿童。"}, {"text": "统", "is_correct": false, "explanation": "tǒng（第三声）与 tòng（第四声）声调不同，意思是统一。"}, {"text": "冻", "is_correct": false, "explanation": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是冻结或受冷。"}, {"text": "捅", "is_correct": false, "explanation": "tǒng（第三声）与 tòng（第四声）声调不同，意思是用棍子等戳。"}], "explanations": {"痛": "tòng（第四声）是“痛”，表示身体或心里的难受。", "童": "tóng（第二声）与 tòng（第四声）声调不同，意思是儿童。", "统": "tǒng（第三声）与 tòng（第四声）声调不同，意思是统一。", "冻": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是冻结或受冷。", "捅": "tǒng（第三声）与 tòng（第四声）声调不同，意思是用棍子等戳。"}, "sentence_index": null, "correct_answer": "痛"}, "level_3": {"options": [{"text": "痛", "is_correct": true, "explanation": "“痛”正确：脚被门夹到，疼得哭了，符合语境。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度或程度，不能用来形容“得哭了”的状态。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明亮，与哭的情况无关。"}, {"text": "脆", "is_correct": false, "explanation": "语义：“脆”说食物或物体容易断，不能形容哭的样子。"}], "explanations": {"痛": "“痛”正确：脚被门夹到，疼得哭了，符合语境。", "高": "搭配：“高”说高度或程度，不能用来形容“得哭了”的状态。", "亮": "语义：“亮”说光线明亮，与哭的情况无关。", "脆": "语义：“脆”说食物或物体容易断，不能形容哭的样子。"}, "sentence_index": 6, "correct_answer": "痛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很痛。", "explanation": "这里应该用〈硬〉。“硬”形容物体的质地，椅子的坚硬要说硬；“痛”只用于身体或心里的感觉。"}, {"text": "这盏灯很痛。", "explanation": "这里应该用〈亮〉。“亮”形容光线的明暗，灯的亮度要说亮；“痛”不能用来形容光线。"}, {"text": "这壶茶很痛。", "explanation": "这里应该用〈烫〉。“烫”形容温度高，茶的温度要说烫；“痛”不能用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他摔了一跤，痛很站不起来。", "corrected_sentence": "他摔了一跤，痛得站不起来。", "error_description": "程度补语错误：“痛”后面表示程度要用“得”，不能用“很”；“痛很站不起来”不通，应说“痛得站不起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个孩子掉进水里，痛很大哭起来。", "corrected_sentence": "那个孩子掉进水里，痛得大哭起来。", "error_description": "程度补语错误：“痛”后面表示程度要用“得”，不能用“很”；“痛很大哭起来”不通，应说“痛得大哭起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
