INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90846, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "疼痛；因伤病而难受。", "primary_collocate": null, "pronunciation": "tòng", "ipa": "tʰʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我感冒了，喉咙又干又痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我：哪里痛？", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿受伤了，走路的时候很痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃了药，胃就不痛了。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙齿有问题，所以我吃饭时很痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生病了，头很痛，睡不着。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术以后，伤口还有一点痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病得很重，浑身都痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头不太痛，只是有点发烧。", "target_word": "痛", "complexity_tier": "T3", "furigana": "tā tóu bù tài tòng, zhǐ shì yǒu diǎn fā shāo.", "sentence_source": "generated"}, {"text": "手指割破了，洗的时候特别痛。", "target_word": "痛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头痛", "label": "复合"}, {"form": "牙痛", "label": "复合"}], "register": "中性", "sense_fingerprint": "因生病或受伤而疼痛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "痛", "is_correct": true, "explanation": "tòng（第四声）是“痛”，表示因伤病而疼痛。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 tòng（第四声）声调不同，意思是相同。"}, {"text": "通", "is_correct": false, "explanation": "tōng（第一声）与 tòng（第四声）声调不同，意思是通过、通畅。"}, {"text": "洞", "is_correct": false, "explanation": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是洞穴。"}, {"text": "动", "is_correct": false, "explanation": "dòng 与 tòng 声母不同（d 与 t），意思是活动、移动。"}, {"text": "桶", "is_correct": false, "explanation": "tǒng（第三声）与 tòng（第四声）声调不同，意思是水桶。"}, {"text": "铜", "is_correct": false, "explanation": "tóng（第二声）与 tòng（第四声）声调不同，意思是铜。"}], "explanations": {"痛": "tòng（第四声）是“痛”，表示因伤病而疼痛。", "同": "tóng（第二声）与 tòng（第四声）声调不同，意思是相同。", "通": "tōng（第一声）与 tòng（第四声）声调不同，意思是通过、通畅。", "洞": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是洞穴。", "动": "dòng 与 tòng 声母不同（d 与 t），意思是活动、移动。", "桶": "tǒng（第三声）与 tòng（第四声）声调不同，意思是水桶。", "铜": "tóng（第二声）与 tòng（第四声）声调不同，意思是铜。"}, "sentence_index": null, "correct_answer": "痛"}, "level_3": {"options": [{"text": "痛", "is_correct": true, "explanation": "“痛”正确：感冒后喉咙又干又疼，符合语境。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线或颜色，不能形容喉咙的干痛。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，与喉咙的感觉不合。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”说吃得满足，不能与“又干”并列描述喉咙。"}], "explanations": {"痛": "“痛”正确：感冒后喉咙又干又疼，符合语境。", "亮": "语义：“亮”说光线或颜色，不能形容喉咙的干痛。", "快": "语义：“快”说速度，与喉咙的感觉不合。", "饱": "搭配：“饱”说吃得满足，不能与“又干”并列描述喉咙。"}, "sentence_index": 0, "correct_answer": "痛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗药很痛。", "explanation": "这里应该用〈苦〉。“苦”形容味道，药的味道要说苦；“痛”不能形容味道。"}, {"text": "这条路很痛。", "explanation": "这里应该用〈远〉。“远”形容距离，路程的远近要说远；“痛”不能用来形容距离。"}, {"text": "这个箱子很痛。", "explanation": "这里应该用〈重〉。“重”形容分量，箱子的轻重要说重；“痛”不能用来形容重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90846, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "痛", "is_correct": true, "explanation": "tòng（第四声）是“痛”，表示身体因伤病而难受。"}, {"text": "童", "is_correct": false, "explanation": "tóng（第二声）与 tòng（第四声）声调不同，意思是儿童。"}, {"text": "统", "is_correct": false, "explanation": "tǒng（第三声）与 tòng（第四声）声调不同，意思是统一。"}, {"text": "冻", "is_correct": false, "explanation": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是冻结或受冷。"}, {"text": "捅", "is_correct": false, "explanation": "tǒng（第三声）与 tòng（第四声）声调不同，意思是用棍子等戳。"}], "explanations": {"痛": "tòng（第四声）是“痛”，表示身体因伤病而难受。", "童": "tóng（第二声）与 tòng（第四声）声调不同，意思是儿童。", "统": "tǒng（第三声）与 tòng（第四声）声调不同，意思是统一。", "冻": "dòng 与 tòng 声母不同（d 与 t），声调相同，意思是冻结或受冷。", "捅": "tǒng（第三声）与 tòng（第四声）声调不同，意思是用棍子等戳。"}, "sentence_index": null, "correct_answer": "痛"}, "level_3": {"options": [{"text": "痛", "is_correct": true, "explanation": "“痛”正确：手术后伤口还有疼痛感，符合语境。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高或高低，不能形容伤口的感觉。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与伤口的感觉不合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”不说伤口的感觉，“伤口还有一点高”不通。"}], "explanations": {"痛": "“痛”正确：手术后伤口还有疼痛感，符合语境。", "矮": "体貌：“矮”形容身高或高低，不能形容伤口的感觉。", "甜": "语义：“甜”说味道，与伤口的感觉不合。", "高": "搭配：“高”不说伤口的感觉，“伤口还有一点高”不通。"}, "sentence_index": 6, "correct_answer": "痛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水很痛。", "explanation": "这里应该用〈凉〉。“凉”形容温度，水的冷暖要说凉；“痛”不能用来形容温度。"}, {"text": "这朵花很痛。", "explanation": "这里应该用〈红〉。“红”形容颜色，花的颜色要说红；“痛”不能用来形容颜色。"}, {"text": "这块面包很痛。", "explanation": "这里应该用〈软〉。“软”形容质地，面包的柔软要说软；“痛”不能形容食物的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子的腿痛很走不了路。", "corrected_sentence": "孩子的腿痛得走不了路。", "error_description": "程度补语错误：“痛”后面表示程度要用“得”，不能用“很”；“痛很走不了路”不通，应说“痛得走不了路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的胃痛很睡不着觉。", "corrected_sentence": "他的胃痛得睡不着觉。", "error_description": "程度补语错误：“痛”后面表示程度要用“得”，不能用“很”；“痛很睡不着觉”不通，应说“痛得睡不着觉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
