INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "艺术家是会画画、唱歌、跳舞，做出很美的东西的人。", "primary_collocate": null, "pronunciation": "yì shù jiā", "ipa": "i˥˩ ʂu˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他是一位艺术家。", "target_word": "艺术家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的姐姐想当艺术家。", "target_word": "艺术家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位艺术家会画画，也会唱歌。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术家的房子里挂满了画。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人来看这位艺术家跳舞。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个艺术家画了一只很大的鸟。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术家正看着他的新画。", "target_word": "艺术家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候就想成为艺术家。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术家把画送给了我。", "target_word": "艺术家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是医生，是一位艺术家。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "藝術家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "艺术家：会画画、唱歌、跳舞，做出美的东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '171bfaad-7331-4fb7-ab07-ca6c9f52da30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "艺术家", "is_correct": true, "explanation": "正确：“他是一位”后接指人的身份名词，“艺术家”指从事艺术创作的人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“位”只用于指人，不能说“一位桌子”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“他是”后要说人的身份，“河流”不是人。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“他是”后要说人的身份，“手机”不是人。"}], "explanations": {"艺术家": "正确：“他是一位”后接指人的身份名词，“艺术家”指从事艺术创作的人。", "桌子": "搭配：量词“位”只用于指人，不能说“一位桌子”。", "河流": "语义：“他是”后要说人的身份，“河流”不是人。", "手机": "语义：“他是”后要说人的身份，“手机”不是人。"}, "sentence_index": 0, "correct_answer": "艺术家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一只艺术家。", "explanation": "这里应该用〈位〉。〈只〉多用于动物或器物，指人的名词要用〈位〉或〈个〉。"}, {"text": "那张艺术家很有名。", "explanation": "这里应该用〈位〉。〈张〉用于平面的东西，不用来数人。"}, {"text": "我的邻居是一台艺术家，每天在画室里画画。", "explanation": "这里应该用〈位〉。〈台〉用于机器、设备，不能用来数人，〈艺术家〉指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艺术家", "is_correct": true, "explanation": "正确：“艺术家”是能看画、创作的人，可以作“看着”的主语。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“看着”要求能看的主语，石头没有眼睛，不能看。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“看着”指有生命的人或动物用眼睛看，花瓶不能看。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“看着”需要能看的主体，冰箱不能看。"}], "explanations": {"艺术家": "正确：“艺术家”是能看画、创作的人，可以作“看着”的主语。", "石头": "配价：“看着”要求能看的主语，石头没有眼睛，不能看。", "花瓶": "语义：“看着”指有生命的人或动物用眼睛看，花瓶不能看。", "冰箱": "语义：“看着”需要能看的主体，冰箱不能看。"}, "sentence_index": 6, "correct_answer": "艺术家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那幅艺术家挂在客厅里，很好看。", "explanation": "这里指的是人，不能指作品。说作品要用〈画〉或〈作品〉。"}, {"text": "她有一座艺术家，所以每天练习。", "explanation": "这里应该用〈位〉或〈个〉。〈座〉用于山、楼等大型固定物，不能用来数人。"}, {"text": "这首歌是一位艺术家，我每天都听。", "explanation": "这里〈艺术家〉指人，不能指歌曲，说歌曲要用〈歌〉或〈作品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的叔叔是一只艺术家。", "corrected_sentence": "我的叔叔是一位艺术家。", "error_description": "错误：指人的“艺术家”前用了量词“只”，“只”多用于动物或器物，应为“一位艺术家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位艺术家们来了美术馆。", "corrected_sentence": "三位艺术家来了美术馆。", "error_description": "错误：“艺术家们”与数量词“三位”同时使用，重复表示复数；应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
