INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90871, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管着，不让随便做。", "primary_collocate": null, "pronunciation": "guǎn zhì", "ipa": "kwan˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "警察管制着这些犯人。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校管制学生使用手机。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲管制得非常严，我晚上不得外出。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监狱里的犯人受到严格管制。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不应该这样管制学生的言行。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父母管制他看电视的时间。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵管制着进出的人。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长不宜过度管制孩子，应当让孩子自己做决定。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司管制员工上班时上网。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂管制工人随便离开岗位。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管制了", "label": "体标"}, {"form": "管制着", "label": "体标"}], "register": "书面", "sense_fingerprint": "对人严加看管，不让他们随便行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招待", "is_correct": false, "explanation": "语义：“招待”指热情接待客人，与对犯人的严加看管相反。"}, {"text": "管制", "is_correct": true, "explanation": "管制：对人严加看管，不让随便行动，与“犯人”搭配。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的对象是木石等材料，不能用于人。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与对犯人严加看管的意思不符。"}], "explanations": {"招待": "语义：“招待”指热情接待客人，与对犯人的严加看管相反。", "管制": "管制：对人严加看管，不让随便行动，与“犯人”搭配。", "雕刻": "搭配：“雕刻”的对象是木石等材料，不能用于人。", "感谢": "语义：“感谢”表示谢意，与对犯人严加看管的意思不符。"}, "sentence_index": 0, "correct_answer": "管制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位经理管制公司的财务。", "explanation": "这里应该用〈管理〉。管制指对人严加看管、不让随便做，公司财务不是人，应当用管理。"}, {"text": "警察管制这起案件的线索。", "explanation": "这里应该用〈调查〉。管制指对人严加看管、不让随便做，案件线索不是人，查找线索要用调查。"}, {"text": "观众管制这位演员。", "explanation": "这里应该用〈欣赏〉。管制指对人严加看管或约束，观众对演员的表演表示赞赏要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”表示美好的祝愿，与对进出人员的管控不符。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”的对象多为子女或幼小者，不用于进出的成年人。"}, {"text": "管制", "is_correct": true, "explanation": "管制：对人严加看管，不让随便进出或行动，与“进出的人”搭配。"}, {"text": "宠爱", "is_correct": false, "explanation": "语义：“宠爱”表示偏爱疼惜，与“管制”的限制义相反。"}], "explanations": {"祝福": "语义：“祝福”表示美好的祝愿，与对进出人员的管控不符。", "抚养": "搭配：“抚养”的对象多为子女或幼小者，不用于进出的成年人。", "管制": "管制：对人严加看管，不让随便进出或行动，与“进出的人”搭配。", "宠爱": "语义：“宠爱”表示偏爱疼惜，与“管制”的限制义相反。"}, "sentence_index": 6, "correct_answer": "管制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂管制新员工的技术。", "explanation": "这里应该用〈培训〉。管制指对人行动的强制限制，向新员工传授技术要用培训。"}, {"text": "护士管制了他的伤口。", "explanation": "这里应该用〈包扎〉。管制指对人行为的强制约束，处理伤口要用包扎。"}, {"text": "领导管制了表现好的员工。", "explanation": "这里应该用〈表扬〉。管制指对人严加约束，对表现好的员工要用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶管制很严，孩子不能乱跑。", "corrected_sentence": "奶奶管制得很严，孩子不能乱跑。", "error_description": "错误形式：“管制很严”，漏掉了状态补语的“得”。正确形式：“管制得很严”。原因：“V得”后接状态补语，“管制很严”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父母每天管制了孩子玩游戏的时间。", "corrected_sentence": "父母每天管制孩子玩游戏的时间。", "error_description": "错误形式：“每天管制了”，多了“了”。正确形式：“每天管制”。原因：“每天”表示习惯性动作，不用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
