INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强制管理；限制。", "primary_collocate": null, "pronunciation": "guǎn zhì", "ipa": "kwan˨˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "政府严格管制枪支。", "target_word": "管制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府管制了市中心的交通。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，警察管制了这条路。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家管制刀具的买卖。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药受到国家管制，不能随便买。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在管制大城市的房价。", "target_word": "管制", "complexity_tier": "T3", "furigana": "zhèngfǔ zhèngzài guǎnzhì dàchéngshì de fángjià", "sentence_source": "generated"}, {"text": "机场附近的飞机航线由专人管制。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的用水被严格管制着。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有关部门管制了这种危险化学品。", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为什么要管制物价？", "target_word": "管制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管制了", "label": "体标"}, {"form": "管制着", "label": "体标"}, {"form": "交通管制", "label": "复合"}, {"form": "管制刀具", "label": "复合"}], "register": "书面", "sense_fingerprint": "政府或有关部门对事物、物品、交通等强制管理并加以限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放松", "is_correct": false, "explanation": "语义：“放松”与“严格”意思相反，严格放松枪支自相矛盾。"}, {"text": "管制", "is_correct": true, "explanation": "管制：强制管理、限制，与“严格”搭配，指政府对枪支实施管控。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于房间、物品等的美化，不能用于枪支的管理。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说参观枪支。"}], "explanations": {"放松": "语义：“放松”与“严格”意思相反，严格放松枪支自相矛盾。", "管制": "管制：强制管理、限制，与“严格”搭配，指政府对枪支实施管控。", "装饰": "搭配：“装饰”用于房间、物品等的美化，不能用于枪支的管理。", "参观": "搭配：“参观”的对象是场所或展览，不能说参观枪支。"}, "sentence_index": 0, "correct_answer": "管制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他管制了一顿丰盛的晚餐。", "explanation": "这里应该用〈准备〉。管制指强制管理或限制，做晚餐要用准备。"}, {"text": "她管制了一首优美的诗。", "explanation": "这里应该用〈朗诵〉。管制指强制管理或限制，朗读诗歌要用朗诵。"}, {"text": "他管制了一个温暖的拥抱。", "explanation": "这里应该用〈给〉。管制指强制管理或限制，给别人一个拥抱要用给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物，航线不能被品尝。"}, {"text": "管制", "is_correct": true, "explanation": "管制：强制管理、限制，可用于交通航线，由专人负责。"}, {"text": "教育", "is_correct": false, "explanation": "语义：“教育”的对象是人，航线不是人，不能被教育。"}, {"text": "烹调", "is_correct": false, "explanation": "搭配：“烹调”的对象是食材，航线无法被烹调。"}], "explanations": {"品尝": "搭配：“品尝”的对象是食物，航线不能被品尝。", "管制": "管制：强制管理、限制，可用于交通航线，由专人负责。", "教育": "语义：“教育”的对象是人，航线不是人，不能被教育。", "烹调": "搭配：“烹调”的对象是食材，航线无法被烹调。"}, "sentence_index": 6, "correct_answer": "管制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶管制了一碗热腾腾的粥。", "explanation": "这里应该用〈煮〉。管制指强制管理或限制，做一碗粥要用煮。"}, {"text": "妈妈管制了一桌好菜。", "explanation": "这里应该用〈烹饪〉。管制用于强制限制物品或交通，做饭要用烹饪。"}, {"text": "他管制了一个美好的早晨。", "explanation": "这里应该用〈度过〉。管制指强制管理或限制，过一个美好的早晨要用度过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府明天会管制了交通。", "corrected_sentence": "政府明天会管制交通。", "error_description": "错误形式：“会”表示将来，句中的“管制”后不能加“了”。正确形式：“政府明天会管制交通”。原因：“了”表示已完成，与将来时间词“明天”矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府对枪支管制的很严。", "corrected_sentence": "政府对枪支管制得很严。", "error_description": "错误形式：“管制的很严”，误用了“的”。正确形式：“管制得很严”。原因：“V得”后接状态补语，动词与补语之间须用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
