INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赛是比一比，看谁做得好、跑得快。", "primary_collocate": null, "pronunciation": "sài", "ipa": "sai̯˥˩", "syllable_count": 1, "sentences": [{"text": "我和弟弟赛一赛，看谁跑得快。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们赛着吃饭，看谁吃得快。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们赛赛谁先做完作业。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想跟我赛游泳，看谁游得快。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐跟我赛着写字，看谁写得好看。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来，咱们赛一次，看谁先到。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和儿子赛了一路，儿子先到家。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不跟你赛，你跑得比我快。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们赛着画画，看谁画得好。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他俩赛着做饭，看谁做得又快又好。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赛了", "label": "体标"}, {"form": "赛过", "label": "体标"}, {"form": "赛着", "label": "体标"}, {"form": "赛赛", "label": "重叠"}, {"form": "賽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "赛：比一比谁做得好、谁更快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赛", "is_correct": true, "explanation": "赛 sài：比一比谁做得好、谁更快，是该义项的正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 sài 声母不同（t/s），意思是太阳、太过。"}, {"text": "戴", "is_correct": false, "explanation": "dài 与 sài 声母不同（d/s），意思是戴上。"}, {"text": "晒", "is_correct": false, "explanation": "shài 与 sài 声母不同（sh/s），意思是晒太阳。"}, {"text": "塞", "is_correct": false, "explanation": "sāi（第一声）与 sài（第四声）声调不同，意思是塞入。"}], "explanations": {"赛": "赛 sài：比一比谁做得好、谁更快，是该义项的正确答案。", "太": "tài 与 sài 声母不同（t/s），意思是太阳、太过。", "戴": "dài 与 sài 声母不同（d/s），意思是戴上。", "晒": "shài 与 sài 声母不同（sh/s），意思是晒太阳。", "塞": "sāi（第一声）与 sài（第四声）声调不同，意思是塞入。"}, "sentence_index": null, "correct_answer": "赛"}, "level_3": {"options": [{"text": "赛", "is_correct": true, "explanation": "正确：“赛”表示比一比快慢，与“看谁跑得快”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与跑得快无关。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能接“比跑得快”的较量。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，不指比较快慢。"}], "explanations": {"赛": "正确：“赛”表示比一比快慢，与“看谁跑得快”相合。", "吃": "语义：“吃”指进食，与跑得快无关。", "穿": "搭配：“穿”的宾语是衣物，不能接“比跑得快”的较量。", "写": "语义：“写”指书写，不指比较快慢。"}, "sentence_index": 0, "correct_answer": "赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他赛了一部手机，很快就换了。", "explanation": "这里应该用〈买〉。“赛”指比一比、看谁做得好，不能与“手机”搭配表示购买。"}, {"text": "我们赛了一场电影。", "explanation": "这里应该用〈看〉。“赛”指比一比高下，不能与“电影”搭配表示观看。"}, {"text": "妈妈赛了一双鞋，很合脚。", "explanation": "这里应该用〈穿〉。“赛”指比一比，不能与“鞋”搭配表示穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赛", "is_correct": true, "explanation": "赛 sài：比一比谁做得好、谁更快，是该义项的正确答案。"}, {"text": "菜", "is_correct": false, "explanation": "cài 与 sài 声母不同（c/s），意思是蔬菜。"}, {"text": "再", "is_correct": false, "explanation": "zài 与 sài 声母不同（z/s），意思是again，再次。"}, {"text": "赖", "is_correct": false, "explanation": "lài 与 sài 声母不同（l/s），意思是赖皮。"}, {"text": "色", "is_correct": false, "explanation": "sè 与 sài 韵母不同（e/ai），意思是颜色。"}], "explanations": {"赛": "赛 sài：比一比谁做得好、谁更快，是该义项的正确答案。", "菜": "cài 与 sài 声母不同（c/s），意思是蔬菜。", "再": "zài 与 sài 声母不同（z/s），意思是again，再次。", "赖": "lài 与 sài 声母不同（l/s），意思是赖皮。", "色": "sè 与 sài 韵母不同（e/ai），意思是颜色。"}, "sentence_index": null, "correct_answer": "赛"}, "level_3": {"options": [{"text": "赛", "is_correct": true, "explanation": "正确：“赛”表示比较先后，与“爸爸和儿子……儿子先到家”相合。"}, {"text": "逛", "is_correct": false, "explanation": "语义：“逛”指随意走动游览，不能表示比较先后。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指入睡，与“儿子先到家”的比较语境冲突。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与比谁先到家不符。"}], "explanations": {"赛": "正确：“赛”表示比较先后，与“爸爸和儿子……儿子先到家”相合。", "逛": "语义：“逛”指随意走动游览，不能表示比较先后。", "睡": "语义：“睡”指入睡，与“儿子先到家”的比较语境冲突。", "唱": "语义：“唱”指歌唱，与比谁先到家不符。"}, "sentence_index": 6, "correct_answer": "赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里人赛神，求来年丰收。", "explanation": "这里应该用〈祭〉。“赛”在此指祭神酬谢，与比一比的义项不同。"}, {"text": "妈妈赛了一台冰箱，很省电。", "explanation": "这里应该用〈买〉。“赛”指比一比高下，不能表示购买。"}, {"text": "爸爸赛了一顶帽子，很好看。", "explanation": "这里应该用〈戴〉。“赛”指比一比，不能与“帽子”搭配表示戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val