INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和妹妹着赛画画，看谁画得快。", "corrected_sentence": "我和妹妹赛着画画，看谁画得快。", "error_description": "错误形式：“着”放在动词“赛”之前，写成“着赛”。正确形式：“赛着画画”，“着”应紧跟动词“赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩了赛一会儿，看谁先到。", "corrected_sentence": "我们俩赛了一会儿，看谁先到。", "error_description": "错误形式：“了”放在动词“赛”之前。正确形式：“赛了一会儿”，“了”应紧跟动词“赛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
