INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比赛；较量高下。", "primary_collocate": null, "pronunciation": "sài", "ipa": "sai̯˥˩", "syllable_count": 1, "sentences": [{"text": "咱们赛一赛，看谁的棋下得好。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我赛了一场乒乓球。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个队以前赛过三次。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你敢不敢跟我赛一局？", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我们班要跟三班赛一场足球。", "target_word": "赛", "complexity_tier": "T3", "furigana": "míng tiān wǒ men bān yào gēn sān bān sài yī chǎng zú qiú", "sentence_source": "generated"}, {"text": "他们赛着唱歌，谁也不服谁。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想和朋友赛一场羽毛球。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有本事就跟他赛一把。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩赛了半天，还是不分高下。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班和二班赛篮球，结果赢了。", "target_word": "赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赛了", "label": "体标"}, {"form": "赛过", "label": "体标"}, {"form": "赛着", "label": "体标"}, {"form": "赛赛", "label": "重叠"}, {"form": "賽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "赛：与人比赛、较量高下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赛", "is_correct": true, "explanation": "赛 sài：比赛、较量高下，是该义项的正确答案。"}, {"text": "晒", "is_correct": false, "explanation": "shài 与 sài 声母不同（sh/s），意思是晒太阳。"}, {"text": "菜", "is_correct": false, "explanation": "cài 与 sài 声母不同（c/s），意思是蔬菜。"}, {"text": "再", "is_correct": false, "explanation": "zài 与 sài 声母不同（z/s），意思是again，再次。"}, {"text": "塞", "is_correct": false, "explanation": "sāi（第一声）与 sài（第四声）声调不同，意思是塞入。"}, {"text": "赖", "is_correct": false, "explanation": "lài 与 sài 声母不同（l/s），意思是赖皮。"}], "explanations": {"赛": "赛 sài：比赛、较量高下，是该义项的正确答案。", "晒": "shài 与 sài 声母不同（sh/s），意思是晒太阳。", "菜": "cài 与 sài 声母不同（c/s），意思是蔬菜。", "再": "zài 与 sài 声母不同（z/s），意思是again，再次。", "塞": "sāi（第一声）与 sài（第四声）声调不同，意思是塞入。", "赖": "lài 与 sài 声母不同（l/s），意思是赖皮。"}, "sentence_index": null, "correct_answer": "赛"}, "level_3": {"options": [{"text": "赛", "is_correct": true, "explanation": "正确：“赛”表示较量，与“咱们……一……，看谁的棋下得好”相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与下棋的较量义搭配，“咱们洗一洗”不通。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连缀，与下棋无关。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污物，不指较量棋艺。"}], "explanations": {"赛": "正确：“赛”表示较量，与“咱们……一……，看谁的棋下得好”相合。", "洗": "搭配：“洗”不能与下棋的较量义搭配，“咱们洗一洗”不通。", "缝": "语义：“缝”指用针线连缀，与下棋无关。", "擦": "语义：“擦”指抹去污物，不指较量棋艺。"}, "sentence_index": 0, "correct_answer": "赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去赛了一场演唱会。", "explanation": "这里应该用〈看〉。“赛”指比一比、较量高下，不能与“演唱会”搭配表示观看。"}, {"text": "学校赛了一场晚会，很热闹。", "explanation": "这里应该用〈举办〉。“赛”指较量高下，不能用于举办晚会。"}, {"text": "他给我赛了一封信。", "explanation": "这里应该用〈写〉。“赛”指较量高下，不能用于写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赛", "is_correct": true, "explanation": "赛 sài：比赛、较量高下，是该义项的正确答案。"}, {"text": "色", "is_correct": false, "explanation": "sè 与 sài 韵母不同（e/ai），意思是颜色。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 sài 声母不同（t/s），意思是太阳、太过。"}, {"text": "寨", "is_correct": false, "explanation": "zhài 与 sài 声母不同（zh/s），意思是村寨。"}, {"text": "戴", "is_correct": false, "explanation": "dài 与 sài 声母不同（d/s），意思是戴上。"}], "explanations": {"赛": "赛 sài：比赛、较量高下，是该义项的正确答案。", "色": "sè 与 sài 韵母不同（e/ai），意思是颜色。", "太": "tài 与 sài 声母不同（t/s），意思是太阳、太过。", "寨": "zhài 与 sài 声母不同（zh/s），意思是村寨。", "戴": "dài 与 sài 声母不同（d/s），意思是戴上。"}, "sentence_index": null, "correct_answer": "赛"}, "level_3": {"options": [{"text": "赛", "is_correct": true, "explanation": "正确：“赛”表示比赛，与“羽毛球”相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能接“羽毛球”。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指口中出气，与打羽毛球无关。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能接球类。"}], "explanations": {"赛": "正确：“赛”表示比赛，与“羽毛球”相合。", "唱": "搭配：“唱”的对象是歌，不能接“羽毛球”。", "吹": "语义：“吹”指口中出气，与打羽毛球无关。", "煮": "搭配：“煮”的对象是食物，不能接球类。"}, "sentence_index": 6, "correct_answer": "赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赛了三块钱的青菜，很新鲜。", "explanation": "这里应该用〈买〉。“赛”指比较高下，不能表示买菜。"}, {"text": "老师赛了一个好建议，大家都同意。", "explanation": "这里应该用〈提〉。“赛”指较量高下，提建议不能用“赛”。"}, {"text": "我们班赛了一本书，大家都很喜欢。", "explanation": "这里应该用〈读〉。“赛”指较量高下，读书不能用“赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩着赛下棋，看谁先赢。", "corrected_sentence": "我们俩赛着下棋，看谁先赢。", "error_description": "错误形式：“着”放在动词“赛”之前，写成“着赛”。正确形式：“赛着下棋”，“着”应紧跟动词“赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们班跟三班了赛一场足球。", "corrected_sentence": "他们班跟三班赛了一场足球。", "error_description": "错误形式：“了”放在动词“赛”之前。正确形式：“赛了一场足球”，“了”应紧跟动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
