INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90877, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一次一次的数加在一起。", "primary_collocate": null, "pronunciation": "lěi jì", "ipa": "leɪ²¹⁴ tɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "请把每天的花费累计一下。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家的分数累计起来。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每月都会把家里的开支累计起来。", "target_word": "累计", "complexity_tier": "T3", "furigana": "mā ma měi yuè dōu huì bǎ jiā lǐ de kāi zhī lěi jì qǐ lái.", "sentence_source": "generated"}, {"text": "他在本子上累计每天的跑步距离。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计把全年的收入累计了一遍。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，裁判累计各队的得分。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你累计一下这三次的成绩。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生累计了病人每天的睡眠时间。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件会自动累计你每天的步数。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把五次考试的分数累计，再算平均分。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "累計", "label": "繁体"}, {"form": "累计了", "label": "体标"}], "register": "书面", "sense_fingerprint": "把多次的数目加起来算总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90877, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "累计", "is_correct": true, "explanation": "累计（lěi jì）指把一次一次的数加在一起，是正确答案。"}, {"text": "雷击", "is_correct": false, "explanation": "léi jī 的两个音节声调都与 lěi jì 不同（第二声、第一声），意思是雷电击中。"}, {"text": "泪迹", "is_correct": false, "explanation": "lèi jì 的第一音节为第四声，与 lěi（第三声）声调不同，意思是眼泪流过的痕迹。"}, {"text": "累及", "is_correct": false, "explanation": "lěi jí 的第二音节为第二声，与 jì（第四声）声调不同，意思是牵连、波及。"}], "explanations": {"累计": "累计（lěi jì）指把一次一次的数加在一起，是正确答案。", "雷击": "léi jī 的两个音节声调都与 lěi jì 不同（第二声、第一声），意思是雷电击中。", "泪迹": "lèi jì 的第一音节为第四声，与 lěi（第三声）声调不同，意思是眼泪流过的痕迹。", "累及": "lěi jí 的第二音节为第二声，与 jì（第四声）声调不同，意思是牵连、波及。"}, "sentence_index": null, "correct_answer": "累计"}, "level_3": {"options": [{"text": "累计", "is_correct": true, "explanation": "累计表示把一次一次的数加在一起，正用于“每天的花费”。"}, {"text": "打折", "is_correct": false, "explanation": "搭配：“打折”用于商品或票价，不能用于记录每天的花费。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是一种走路的活动，与对花费做处理毫不相干。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对损坏的物品，不能用于数字性质的“花费”。"}], "explanations": {"累计": "累计表示把一次一次的数加在一起，正用于“每天的花费”。", "打折": "搭配：“打折”用于商品或票价，不能用于记录每天的花费。", "散步": "语义：“散步”是一种走路的活动，与对花费做处理毫不相干。", "修理": "搭配：“修理”针对损坏的物品，不能用于数字性质的“花费”。"}, "sentence_index": 0, "correct_answer": "累计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书累计在桌子上。", "explanation": "这里应该用〈堆〉。累计只指数量的逐次相加，不指把东西堆放。"}, {"text": "请把房间累计一下。", "explanation": "这里应该用〈收拾〉。累计用于数的相加，不用于整理房间。"}, {"text": "他在笔记本上累计了每天的事情。", "explanation": "这里应该用〈记载〉。累计只用于数量相加，不用于记录事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "累计", "is_correct": true, "explanation": "累计表示把几次的数加在一起，正适合“这三次的成绩”，是正确答案。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”指操纵车辆，不能用于“成绩”。"}, {"text": "冒险", "is_correct": false, "explanation": "语义：“冒险”指冒着危险去做，与对成绩做处理无关。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：“熬夜”指晚上不睡觉，与计算三次成绩的意思不符。"}], "explanations": {"累计": "累计表示把几次的数加在一起，正适合“这三次的成绩”，是正确答案。", "驾驶": "搭配：“驾驶”指操纵车辆，不能用于“成绩”。", "冒险": "语义：“冒险”指冒着危险去做，与对成绩做处理无关。", "熬夜": "语义：“熬夜”指晚上不睡觉，与计算三次成绩的意思不符。"}, "sentence_index": 6, "correct_answer": "累计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把这些书累计整理。", "explanation": "这里应该用〈分类〉。累计只指数量的相加，不指按类别整理。"}, {"text": "我们应该累计一下计划。", "explanation": "这里应该用〈调整〉。累计只指数量相加，不指改变计划的安排。"}, {"text": "工人累计了屋顶。", "explanation": "这里应该用〈修补〉。累计只指数量相加，不指修理屋顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会计把每个月的开销把累计起来。", "corrected_sentence": "会计把每个月的开销累计起来。", "error_description": "结构错误：“把”字句中多用了一个“把”。正确写法是“会计把每个月的开销累计起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这三次的成绩了累计一下。", "corrected_sentence": "请你把这三次的成绩累计一下。", "error_description": "语法错误：“了”不能放在动词“累计”之前；这里直接说“把这三次的成绩累计一下”即可，不需要“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
