INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90878, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逐次相加合计。", "primary_collocate": null, "pronunciation": "lěi jì", "ipa": "leɪ²¹⁴ tɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "这个月我累计走了三百公里。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司累计卖出了一万本书。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累计迟到了五次，老师很生气。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店累计接待了二十万客人。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班累计捐了两千块钱。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明每天跑步，累计已经一百天了。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥开通以来，累计通过了五百万辆车。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累计看了二十部电影。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站累计的访问人数很多。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我累计学了三年汉语，还想继续学。", "target_word": "累计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "累計", "label": "繁体"}, {"form": "累计了", "label": "体标"}], "register": "书面", "sense_fingerprint": "数量逐次相加，总共达到多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "累计", "is_correct": true, "explanation": "累计（lěi jì）指把多次的数量逐次相加，是正确答案。"}, {"text": "雷击", "is_correct": false, "explanation": "léi jī 的两个音节声调都与 lěi jì 不同（第二声、第一声），意思是雷电击中。"}, {"text": "泪迹", "is_correct": false, "explanation": "lèi jì 的第一音节为第四声，与 lěi（第三声）声调不同，意思是眼泪流过的痕迹。"}, {"text": "累及", "is_correct": false, "explanation": "lěi jí 的第二音节为第二声，与 jì（第四声）声调不同，意思是牵连、波及。"}], "explanations": {"累计": "累计（lěi jì）指把多次的数量逐次相加，是正确答案。", "雷击": "léi jī 的两个音节声调都与 lěi jì 不同（第二声、第一声），意思是雷电击中。", "泪迹": "lèi jì 的第一音节为第四声，与 lěi（第三声）声调不同，意思是眼泪流过的痕迹。", "累及": "lěi jí 的第二音节为第二声，与 jì（第四声）声调不同，意思是牵连、波及。"}, "sentence_index": null, "correct_answer": "累计"}, "level_3": {"options": [{"text": "累计", "is_correct": true, "explanation": "累计表示把多次的数量逐次相加，用来说这个月走的总里程，正合句意。"}, {"text": "损失", "is_correct": false, "explanation": "搭配：“损失”的对象是钱物、时间，不能与“走了三百公里”组合。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指没有按时到达，与走了多少公里的计算毫无关系。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：“节约”用于钱、时间、资源，不能用来计量“走”的距离。"}], "explanations": {"累计": "累计表示把多次的数量逐次相加，用来说这个月走的总里程，正合句意。", "损失": "搭配：“损失”的对象是钱物、时间，不能与“走了三百公里”组合。", "迟到": "语义：“迟到”指没有按时到达，与走了多少公里的计算毫无关系。", "节约": "搭配：“节约”用于钱、时间、资源，不能用来计量“走”的距离。"}, "sentence_index": 0, "correct_answer": "累计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工作中累计了很多经验。", "explanation": "这里应该用〈积累〉。累计只用于数量的逐次相加，不用于经验、知识的聚集。"}, {"text": "垃圾累计在路边。", "explanation": "这里应该用〈堆积〉。累计指数量的逐次相加，不指东西堆在一处。"}, {"text": "力量累计在一起。", "explanation": "这里应该用〈积聚〉。累计用于数量的相加，不用于力量等聚集在一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "累计", "is_correct": true, "explanation": "累计表示把多次的数目逐次相加，与“开通以来”的总数相符，是正确答案。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与“通过了五百万辆车”的事实相反。"}, {"text": "翻修", "is_correct": false, "explanation": "搭配：“翻修”针对房屋、道路的修缮，不能与“通过”这样的动词搭配。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”的对象是损失、钱款，不能与“通过车辆”组合。"}], "explanations": {"累计": "累计表示把多次的数目逐次相加，与“开通以来”的总数相符，是正确答案。", "拒绝": "语义：“拒绝”是不接受，与“通过了五百万辆车”的事实相反。", "翻修": "搭配：“翻修”针对房屋、道路的修缮，不能与“通过”这样的动词搭配。", "赔偿": "搭配：“赔偿”的对象是损失、钱款，不能与“通过车辆”组合。"}, "sentence_index": 6, "correct_answer": "累计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个新计划正在累计中。", "explanation": "这里应该用〈酝酿〉。累计只指数量的逐次相加，不指计划逐渐形成。"}, {"text": "学校要累计学生的能力。", "explanation": "这里应该用〈培养〉。累计是数量的相加，不能用于培养能力。"}, {"text": "这座古城累计了千年的历史。", "explanation": "这里应该用〈积淀〉。累计只指数量的逐次相加，不指历史、文化的沉淀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把每月的工资把累计起来。", "corrected_sentence": "他把每月的工资累计起来。", "error_description": "结构错误：“把”字句中多用了一个“把”。正确写法是“他把每月的工资累计起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店累计着卖出了十万件商品。", "corrected_sentence": "这家店累计卖出了十万件商品。", "error_description": "体标错误：“累计”表示数量逐次相加，不表示持续状态，后面不能加“着”，应写作“累计卖出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
