INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90880, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向法院提出诉讼，要求依法处理。", "primary_collocate": null, "pronunciation": "qǐ sù", "ipa": "tɕʰi˨˩˦ su˥˩", "syllable_count": 2, "sentences": [{"text": "他决定向法院起诉那家公司。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师建议我马上起诉。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人起诉了自己的邻居。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为工资问题起诉老板。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民起诉那家工厂，因为它污染河水。", "target_word": "起诉", "complexity_tier": "T3", "furigana": "qǐ sù", "sentence_source": "generated"}, {"text": "你可以去法院起诉对方。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司起诉他偷了商业资料。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太小，他不想起诉。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的司机起诉了那家汽车店。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备明天上午起诉那家银行。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起诉了", "label": "体标"}, {"form": "起诉过", "label": "体标"}, {"form": "起诉书", "label": "复合"}], "register": "书面", "sense_fingerprint": "向法院提出诉讼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6318cb82-f6f5-4ae9-b8d4-8cf41127d09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起诉", "is_correct": true, "explanation": "正确：起诉指向法院提出诉讼，与“向法院”及“那家公司”的句意相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定对方的好表现，与法院处理公司的诉讼无关。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”是到某地去看，不能说“向法院参观”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢是对别人的好意表示谢意，与提出诉讼的行为无关。"}], "explanations": {"起诉": "正确：起诉指向法院提出诉讼，与“向法院”及“那家公司”的句意相符。", "表扬": "语义：表扬是肯定对方的好表现，与法院处理公司的诉讼无关。", "参观": "搭配：“参观”是到某地去看，不能说“向法院参观”。", "感谢": "语义：感谢是对别人的好意表示谢意，与提出诉讼的行为无关。"}, "sentence_index": 0, "correct_answer": "起诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去派出所起诉小偷。", "explanation": "这里应该用〈控告〉。起诉要向法院提出，去派出所报案或反映情况应说控告。"}, {"text": "他去老师那儿起诉同学。", "explanation": "这里应该用〈告〉。起诉是向法院提出诉讼，向老师反映同学的错误应说告。"}, {"text": "我向物业起诉漏水的邻居。", "explanation": "这里应该用〈投诉〉。起诉只能向法院提出，向物业反映问题应说投诉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起诉", "is_correct": true, "explanation": "正确：起诉可指向法院控告他人偷窃，与“偷了商业资料”的内容相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：奖励是对好行为的褒奖，与“偷了商业资料”的行为相反。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺是为好事高兴，与“偷了商业资料”这类不法行为不符。"}, {"text": "出版", "is_correct": false, "explanation": "配价：“出版”的宾语应是书籍或作品，不能接“他偷了商业资料”这样的小句。"}], "explanations": {"起诉": "正确：起诉可指向法院控告他人偷窃，与“偷了商业资料”的内容相符。", "奖励": "语义：奖励是对好行为的褒奖，与“偷了商业资料”的行为相反。", "祝贺": "语义：祝贺是为好事高兴，与“偷了商业资料”这类不法行为不符。", "出版": "配价：“出版”的宾语应是书籍或作品，不能接“他偷了商业资料”这样的小句。"}, "sentence_index": 6, "correct_answer": "起诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天向老板起诉工资太低。", "explanation": "这里应该用〈抱怨〉。起诉是向法院提起诉讼，对老板表示不满只能说抱怨。"}, {"text": "我们昨天起诉了新的计划。", "explanation": "这里应该用〈讨论〉。起诉的对象必须是当事人，计划这类事情不能被起诉。"}, {"text": "老师当众起诉了那个迟到的学生。", "explanation": "这里应该用〈批评〉。起诉是提起诉讼的法律行为，老师在班上指出学生的错误应说批评。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想给法院起诉这家商店。", "corrected_sentence": "我想向法院起诉这家商店。", "error_description": "错误在介词：起诉是向法院提出诉讼，“法院”要用“向”引出，不能说“给法院”。把“给”改为“向”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们起诉着那家医院。", "corrected_sentence": "我们起诉过那家医院。", "error_description": "错误在“着”：表示曾经经历过的动作要用经历体“过”，“着”表示动作的持续状态，不符合句意。应把“着”改为“过”，说“我们起诉过那家医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c850582-cdfb-4923-b553-7b3659adb069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
