INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "载", "is_correct": true, "explanation": "载 zài：用交通工具装运，是本义，正确答案。"}, {"text": "栽", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是栽种。"}, {"text": "债", "is_correct": false, "explanation": "zhài 与 zài 声母不同（zh/z），意思是债务。"}, {"text": "赛", "is_correct": false, "explanation": "sài 与 zài 声母不同（s/z），意思是比赛。"}, {"text": "带", "is_correct": false, "explanation": "dài 与 zài 声母不同（d/z），意思是带领。"}], "explanations": {"载": "载 zài：用交通工具装运，是本义，正确答案。", "栽": "zāi（第一声）与 zài（第四声）声调不同，意思是栽种。", "债": "zhài 与 zài 声母不同（zh/z），意思是债务。", "赛": "sài 与 zài 声母不同（s/z），意思是比赛。", "带": "dài 与 zài 声母不同（d/z），意思是带领。"}, "sentence_index": null, "correct_answer": "载"}, "level_3": {"options": [{"text": "载", "is_correct": true, "explanation": "正确：“载货”指用卡车装运货物，与“不载人”相呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说卡车吃货。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能接“货”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是清洗对象，不能指卡车装运货物。"}], "explanations": {"载": "正确：“载货”指用卡车装运货物，与“不载人”相呼应。", "吃": "语义：“吃”指进食，不能说卡车吃货。", "穿": "搭配：“穿”的宾语是衣物，不能接“货”。", "洗": "搭配：“洗”的宾语是清洗对象，不能指卡车装运货物。"}, "sentence_index": 0, "correct_answer": "载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈载着菜步行去市场。", "explanation": "这里应该用〈拎〉。“载”指借助车船等交通工具运送，步行拎着菜要用〈拎〉。"}, {"text": "他把水果载进了箱子里。", "explanation": "这里应该用〈放〉。“载”指用交通工具装运，把水果放进箱子要用〈放〉。"}, {"text": "他载着两桶水回家。", "explanation": "这里应该用〈挑〉。“载”的运送者须是交通工具，用肩挑水要用〈挑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90886, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "载", "is_correct": true, "explanation": "载 zài：用交通工具装运，是本义，正确答案。"}, {"text": "灾", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。"}, {"text": "造", "is_correct": false, "explanation": "zào 与 zài 韵母不同（ao/ai），意思是制造。"}, {"text": "宰", "is_correct": false, "explanation": "zǎi（第三声）与 zài（第四声）声调不同，意思是宰杀。"}, {"text": "菜", "is_correct": false, "explanation": "cài 与 zài 声母不同（c/z），意思是蔬菜。"}], "explanations": {"载": "载 zài：用交通工具装运，是本义，正确答案。", "灾": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。", "造": "zào 与 zài 韵母不同（ao/ai），意思是制造。", "宰": "zǎi（第三声）与 zài（第四声）声调不同，意思是宰杀。", "菜": "cài 与 zài 声母不同（c/z），意思是蔬菜。"}, "sentence_index": null, "correct_answer": "载"}, "level_3": {"options": [{"text": "载", "is_correct": true, "explanation": "正确：“载”表示用飞机运送乘客，与“客人”相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与运送客人不符。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”指用肩扛重物，飞机不能扛客人。"}, {"text": "驮", "is_correct": false, "explanation": "配价：“驮”的主语须是牲畜，不能以飞机为主语。"}], "explanations": {"载": "正确：“载”表示用飞机运送乘客，与“客人”相合。", "唱": "语义：“唱”指发声歌唱，与运送客人不符。", "扛": "搭配：“扛”指用肩扛重物，飞机不能扛客人。", "驮": "配价：“驮”的主语须是牲畜，不能以飞机为主语。"}, "sentence_index": 6, "correct_answer": "载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她载着一束花走进教室。", "explanation": "这里应该用〈捧〉。“载”指借助车船等交通工具运送，双手捧着花步行要用〈捧〉。"}, {"text": "工人们徒手载着大木箱进了仓库。", "explanation": "这里应该用〈抬〉。“载”指借助车船等交通工具运送，徒手抬箱子要用〈抬〉。"}, {"text": "他载着一袋米步行回家。", "explanation": "这里应该用〈扛〉。“载”指借助车船等交通工具运送，步行扛米要用〈扛〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "轮船着载很多集装箱驶向港口。", "corrected_sentence": "轮船载着很多集装箱驶向港口。", "error_description": "错误形式：“着”放在动词“载”之前，写成“着载”。正确形式：“载着”，“着”应紧跟动词“载”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天这艘渡轮了载很多乘客过江。", "corrected_sentence": "昨天这艘渡轮载了很多乘客过江。", "error_description": "错误形式：“了”放在动词“载”之前。正确形式：“载了很多乘客”，“了”应紧跟动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
