INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人头上长的毛。", "primary_collocate": null, "pronunciation": "tóu fa", "ipa": "tʰoʊ˧˥ fa", "syllable_count": 2, "sentences": [{"text": "她的头发很长，一直到腰。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈每天早上都梳头发。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发是黑色的。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "洗完澡以后，我用吹风机吹头发。", "target_word": "头发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的头发白了，他已经老了。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去理发店，把头发剪短一点。", "target_word": "头发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她染了头发，现在是金黄色的。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大，吹乱了我的头发。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子的头发又黑又亮。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他生病以后，头发掉了很多。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "頭髮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人头上长的毛；可梳、洗、剪、染", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55774ed-ddc3-49eb-a960-56e3f2d39f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包不会长到腰，句子说不通。"}, {"text": "手指", "is_correct": false, "explanation": "体貌：手指不会长到腰那么长，不符合人的身体特征。"}, {"text": "头发", "is_correct": true, "explanation": "正确：头发是长在头上的毛，可以长到腰。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“很长”不能用来形容眼睛。"}], "explanations": {"书包": "语义：书包不会长到腰，句子说不通。", "手指": "体貌：手指不会长到腰那么长，不符合人的身体特征。", "头发": "正确：头发是长在头上的毛，可以长到腰。", "眼睛": "搭配：“很长”不能用来形容眼睛。"}, "sentence_index": 0, "correct_answer": "头发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的枕头上有一粒头发。", "explanation": "这里应该用〈根〉。“粒”用于小颗粒，头发是细长的，要用“根”。"}, {"text": "弟弟把头发当成零食吃了。", "explanation": "这里应该用〈饼干〉。饼干是食物，可以当零食吃；头发不是食物，不能吃。"}, {"text": "她用头发写字，字写得很好。", "explanation": "这里应该用〈钢笔〉。钢笔是工具，可以用来写字；头发不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "搭配：“染”不用于墙，墙要说“刷”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不能被染成金黄色，句子说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能被染成颜色，句子说不通。"}, {"text": "头发", "is_correct": true, "explanation": "正确：头发可以染色，染完会变成金黄色。"}], "explanations": {"墙": "搭配：“染”不用于墙，墙要说“刷”。", "作业": "语义：作业不能被染成金黄色，句子说不通。", "房子": "语义：房子不能被染成颜色，句子说不通。", "头发": "正确：头发可以染色，染完会变成金黄色。"}, "sentence_index": 6, "correct_answer": "头发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的头发，我很喜欢他。", "explanation": "头发是长在头上的毛，不指人。这里把头发当成了人，说不通。"}, {"text": "我把头发借给了朋友，他很开心。", "explanation": "这里把头发当成了可以借出的物品。头发长在头上，是身体的一部分，不是物品，不能借给朋友。"}, {"text": "头发每天都去学校上学。", "explanation": "头发不会去学校，这里把头发当成了有行动能力的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块头发是我的。", "corrected_sentence": "这根头发是我的。", "error_description": "量词错误：“块”用于块状的东西，头发是细长的，要用“根”。应把“这块头发”改为“这根头发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我掉了一张头发在地上。", "corrected_sentence": "我掉了一根头发在地上。", "error_description": "量词错误：“张”用于扁平的东西，头发要用“根”。应把“一张头发”改为“一根头发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把所有钱加在一起的总数。", "primary_collocate": null, "pronunciation": "zǒng é", "ipa": "tsʊŋ˨˩˦ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我把所有的钱加起来，总额是五百元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买菜花的钱，总额一共是六十元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟数了数存钱罐，总额有两百元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三张发票的总额是一千二百元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人的钱，总额够买这台电脑。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把每个月的房租加在一起，总额很大。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看账本，说今年花的总额不少。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这些东西的总额。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱的总额比我想的少。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市小票上的总额是四十五元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把各笔钱加起来得到的总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总额", "is_correct": true, "explanation": "“总额”正确：把所有钱加起来的数目就是总额，符合语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用于钱的数目。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“地址”指位置，不能说“地址是五百元”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指年数，与钱的数目不合。"}], "explanations": {"总额": "“总额”正确：把所有钱加起来的数目就是总额，符合语境。", "身材": "体貌：“身材”指人的体形，不能用于钱的数目。", "地址": "搭配：“地址”指位置，不能说“地址是五百元”。", "年龄": "语义：“年龄”指年数，与钱的数目不合。"}, "sentence_index": 0, "correct_answer": "总额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货的总额是三百箱。", "explanation": "这里应该用〈数量〉。“总额”指钱的总数，货物的件数要说“数量”。"}, {"text": "这台电脑的总额是十五寸。", "explanation": "这里应该用〈尺寸〉。“总额”指金额，屏幕大小要说“尺寸”。"}, {"text": "这座城市的总额是两百万。", "explanation": "这里应该用〈人口〉。“总额”只用于金额，城市的人数要说“人口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总额", "is_correct": true, "explanation": "“总额”正确：今年花的钱合计起来不少，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用于花的钱。"}, {"text": "路线", "is_correct": false, "explanation": "搭配：“路线”指行走的路径，不能说“花的路线”。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：“时刻”指时间点，与花钱的数目不合。"}], "explanations": {"总额": "“总额”正确：今年花的钱合计起来不少，符合语境。", "身高": "体貌：“身高”指人的高矮，不能用于花的钱。", "路线": "搭配：“路线”指行走的路径，不能说“花的路线”。", "时刻": "语义：“时刻”指时间点，与花钱的数目不合。"}, "sentence_index": 6, "correct_answer": "总额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的总额是一米八。", "explanation": "这里应该用〈身高〉。“总额”指钱的总数，人的高矮要说“身高”。"}, {"text": "比赛的总额是两小时。", "explanation": "这里应该用〈时间〉。“总额”指金额，比赛的时长要说“时间”。"}, {"text": "这箱苹果的总额是十斤。", "explanation": "这里应该用〈重量〉。“总额”指金额，不能用来说斤两，表示轻重要说“重量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一季的这张花费总额多得惊人。", "corrected_sentence": "这一季的这笔花费总额多得惊人。", "error_description": "量词错误：“总额”是金额，量词应用“笔”，不能用“张”（“张”用于纸张、票据等平面物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只总额是两千元。", "corrected_sentence": "这笔总额是两千元。", "error_description": "量词错误：“总额”是金额，量词应用“笔”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
