INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全部金额的总数。", "primary_collocate": null, "pronunciation": "zǒng é", "ipa": "tsʊŋ˨˩˦ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个月的收入总额是八千元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的销售总额很高。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你算一下这些费用的总额。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "账单上写着总额两千元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总额超过一万元，就不能用现金。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年全班捐款的总额是三千元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的存款总额增加了。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家交的钱的总额写在黑板上。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资和奖金的总额不到一万。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这张表里的总额对不对？", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "收入、销售、费用等全部金额的总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总额", "is_correct": true, "explanation": "“总额”正确：收入的全部金额要用“总额”，符合语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能与收入的金额搭配。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”指人的数目，不能与“八千元”这样的金额搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻或时长，与收入的金额意义不合。"}], "explanations": {"总额": "“总额”正确：收入的全部金额要用“总额”，符合语境。", "身材": "体貌：“身材”指人的体形，不能与收入的金额搭配。", "人数": "搭配：“人数”指人的数目，不能与“八千元”这样的金额搭配。", "时间": "语义：“时间”指时刻或时长，与收入的金额意义不合。"}, "sentence_index": 0, "correct_answer": "总额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的总额是四十人。", "explanation": "这里应该用〈总数〉。“总额”指钱的总数，人数要说“总数”。"}, {"text": "这件衣服的总额是一米二。", "explanation": "这里应该用〈长度〉。“总额”指金额，衣服的长短要说“长度”。"}, {"text": "这个小区的总额是五千人。", "explanation": "这里应该用〈人口〉。“总额”只用于钱的总数，统计人口要说“人口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总额", "is_correct": true, "explanation": "“总额”正确：存款的全部金额合计起来增加了，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用于存款。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指年数，与存款的金额不合。"}, {"text": "路线", "is_correct": false, "explanation": "搭配：“路线”指行走的路径，不能说存款的路线增加。"}], "explanations": {"总额": "“总额”正确：存款的全部金额合计起来增加了，符合语境。", "身高": "体貌：“身高”指人的高矮，不能用于存款。", "年龄": "语义：“年龄”指年数，与存款的金额不合。", "路线": "搭配：“路线”指行走的路径，不能说存款的路线增加。"}, "sentence_index": 6, "correct_answer": "总额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他的总额是九十分。", "explanation": "这里应该用〈总分〉。“总额”指钱的总数，分数的合计要说“总分”。"}, {"text": "他的总额是七十公斤。", "explanation": "这里应该用〈体重〉。“总额”不用于重量，人的重量要说“体重”。"}, {"text": "两地之间的总额是五百公里。", "explanation": "这里应该用〈距离〉。“总额”指金额，两地的远近要说“距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店上个月的这张销售总额增加得很快。", "corrected_sentence": "这家店上个月的这笔销售总额增加得很快。", "error_description": "量词错误：“销售总额”是金额，量词应用“笔”，不能用“张”（“张”用于纸张、票据等平面物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张总额是八千元。", "corrected_sentence": "这笔总额是八千元。", "error_description": "量词错误：“总额”是金额，量词应用“笔”，不能用“张”（“张”用于纸张、票据等平面物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
