INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由人造成的或由人做的。", "primary_collocate": null, "pronunciation": "rén wéi", "ipa": "ɻən˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这次事故不是天气的问题，是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误是人为造成的，可以避免。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树少了，这是人为的结果。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现，这次火灾是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人为的错误可以避免，自然的灾害不能。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的垃圾太多了，是人为的问题。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥断了，不是地震，而是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想知道，这次停电是不是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气变差，有自然的原因，也有人为的原因。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的污染主要是人为造成的。", "target_word": "人为", "complexity_tier": "T3", "furigana": "zhè tiáo hé de wū rǎn zhǔ yào shì rén wéi zào chéng de", "sentence_source": "generated"}], "morphological_forms": [{"form": "人为的", "label": "的字结构"}, {"form": "人为地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "由人引起的、不是自然发生的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '171bfaad-7331-4fb7-ab07-ca6c9f52da30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人为", "is_correct": true, "explanation": "正确：“人为”指由人造成的，不是自然发生的。"}, {"text": "人文", "is_correct": false, "explanation": "wén（第二声）与 wéi（第二声）韵母不同（en 与 ei），意思是人文学科或人文精神。"}, {"text": "认为", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是认定、觉得。"}, {"text": "人味", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是人情味。"}], "explanations": {"人为": "正确：“人为”指由人造成的，不是自然发生的。", "人文": "wén（第二声）与 wéi（第二声）韵母不同（en 与 ei），意思是人文学科或人文精神。", "认为": "rèn（第四声）与 rén（第二声）声调不同，意思是认定、觉得。", "人味": "wèi（第四声）与 wéi（第二声）声调不同，意思是人情味。"}, "sentence_index": null, "correct_answer": "人为"}, "level_3": {"options": [{"text": "人为", "is_correct": true, "explanation": "正确：与“不是天气的问题”对照，表示由人引起的。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“事故”不能用“聪明”形容。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“事故”不能“安静”，与“是……的”的说明不通。"}, {"text": "灵活", "is_correct": false, "explanation": "搭配：“灵活”形容动作或思维，不能说“事故灵活”。"}], "explanations": {"人为": "正确：与“不是天气的问题”对照，表示由人引起的。", "聪明": "搭配：“事故”不能用“聪明”形容。", "安静": "语义：“事故”不能“安静”，与“是……的”的说明不通。", "灵活": "搭配：“灵活”形容动作或思维，不能说“事故灵活”。"}, "sentence_index": 0, "correct_answer": "人为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察发现，这次火灾是人为地，不是天气造成的。", "explanation": "这里〈人为地〉是副词，不能作谓语，应说〈是人为的〉。"}, {"text": "警察发现，这次火灾是人为智能控制的，不是天气造成的。", "explanation": "这里应该用〈人工〉，如“人工智能”。〈人为〉不能修饰〈智能〉。"}, {"text": "警察发现，那位消防员是人为的。", "explanation": "〈人为〉用于事物或现象，不用来指人，应说明他的行为是故意的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人为", "is_correct": true, "explanation": "正确：与“不是地震”对照，表示由人造成的。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“桥”不会“勇敢”，“勇敢”形容有胆量的人。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”只用于人的态度，桥断了不能热情。"}, {"text": "大方", "is_correct": false, "explanation": "语义：“大方”形容人的举止，不能用来说明桥断的原因。"}], "explanations": {"人为": "正确：与“不是地震”对照，表示由人造成的。", "勇敢": "搭配：“桥”不会“勇敢”，“勇敢”形容有胆量的人。", "热情": "语义：“热情”只用于人的态度，桥断了不能热情。", "大方": "语义：“大方”形容人的举止，不能用来说明桥断的原因。"}, "sentence_index": 6, "correct_answer": "人为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的污染主要是人为智能造成的。", "explanation": "这里〈人为〉不能修饰〈智能〉，应说〈人工〉智能。"}, {"text": "这条河的污染是人为地。", "explanation": "这里〈人为地〉是副词，不能作谓语，应说〈是人为的〉。"}, {"text": "这条河的污染主要是人为的小孩造成的。", "explanation": "〈人为〉用于事物或现象，不用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雾是自然形成的，不是人为了的。", "corrected_sentence": "这场大雾是自然形成的，不是人为的。", "error_description": "错误：“人为的”中间多加了“了”，形容词不能带“了”，应为“人为的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座工厂的废水是人为了排放的。", "corrected_sentence": "这座工厂的废水是人为排放的。", "error_description": "错误：“人为”作状语修饰“排放”，后面不能加“了”，应为“人为排放的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
