INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个州里管事情的最大的人。", "primary_collocate": null, "pronunciation": "zhōu zhǎng", "ipa": "ʈʂoʊ˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "州长是一个州里管事最大的人。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们州的州长五十岁。", "target_word": "州长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "州长住在州政府的大楼里。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有大问题，大家都要问州长。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "州长每天都有很多工作。", "target_word": "州长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校请州长来参加毕业典礼。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个州的人都喜欢新州长。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "州长坐着车去了机场。", "target_word": "州长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "州长和市长一起开会。", "target_word": "州长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在报纸上看到过州长的照片。", "target_word": "州长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "州長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个州里管事最大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55774ed-ddc3-49eb-a960-56e3f2d39f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90939, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "州长", "is_correct": true, "explanation": "州长指一个州里管事最大的人，与定义相符。"}, {"text": "市长", "is_correct": false, "explanation": "语义：市长管的是一座城市，不是全州管事最大的人。"}, {"text": "县长", "is_correct": false, "explanation": "语义：县长管的是一个县，不是整个州。"}, {"text": "州政府", "is_correct": false, "explanation": "搭配：“是……人”要接人，州政府是机构，不能这样说。"}], "explanations": {"州长": "州长指一个州里管事最大的人，与定义相符。", "市长": "语义：市长管的是一座城市，不是全州管事最大的人。", "县长": "语义：县长管的是一个县，不是整个州。", "州政府": "搭配：“是……人”要接人，州政府是机构，不能这样说。"}, "sentence_index": 0, "correct_answer": "州长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的州长很严格。", "explanation": "这里应该用〈校长〉。州长管一个州，学校的负责人要说校长。"}, {"text": "他把州长放进了书包里。", "explanation": "这里应该用〈书〉。州长是人，不能放进书包；放进书包的东西要说书、本子等物品。"}, {"text": "我们班的州长很负责。", "explanation": "这里应该用〈班长〉。州长管整个州，班级里的负责人要说班长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "州长", "is_correct": true, "explanation": "“新州长”指新任的州里管事最大的人，与句意相符。"}, {"text": "首相", "is_correct": false, "explanation": "语义：首相是国家的政府首脑，不是州里的管事人，与“这个州的人”不符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然形成的，不能说“新海洋”。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是天气现象，不是人，不能被人喜欢。"}], "explanations": {"州长": "“新州长”指新任的州里管事最大的人，与句意相符。", "首相": "语义：首相是国家的政府首脑，不是州里的管事人，与“这个州的人”不符。", "海洋": "语义：海洋是自然形成的，不能说“新海洋”。", "气温": "语义：气温是天气现象，不是人，不能被人喜欢。"}, "sentence_index": 6, "correct_answer": "州长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上喝州长。", "explanation": "这里应该用〈牛奶〉。州长是人，不是饮料，不能喝；能喝的东西要说牛奶等。"}, {"text": "州长的重量是三公斤。", "explanation": "这里应该用〈包裹〉。州长是人，说他的重量是三公斤，等于把人当成了包裹一类的小物件。"}, {"text": "我们在州长里喝水。", "explanation": "这里应该用〈州政府〉。州长是人，不能作为喝水的地方，地点要说州政府等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张州长今天在议会上发言了。", "corrected_sentence": "这位州长今天在议会上发言了。", "error_description": "量词“张”用于平面物件，不能用于人。州长是人，应用量词“位”，正确形式为“这位州长今天在议会上发言了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只州长来过我们学校。", "corrected_sentence": "这位州长来过我们学校。", "error_description": "量词“只”用于动物或一般物件，不能用于人。州长是人，应用量词“位”，正确形式为“这位州长来过我们学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
