INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体后部大腿根与腰之间隆起的部分。", "primary_collocate": null, "pronunciation": "pì gu", "ipa": "pʰi˥˩ ku", "syllable_count": 2, "sentences": [{"text": "小孩摔倒了，屁股很疼。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士让他趴着，在屁股上打针。", "target_word": "屁股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的裤子太小，屁股那里破了。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈轻轻拍了拍宝宝的屁股。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马的屁股后面有一条长尾巴。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步以后，我觉得屁股有点酸。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗摇着尾巴，屁股也跟着扭。", "target_word": "屁股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子的屁股是红色的。", "target_word": "屁股", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他滑了一跤，屁股重重地摔在地上。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游泳圈太小，我的屁股卡住了。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "屁股蛋", "label": "复合"}], "register": "口语", "sense_fingerprint": "人体后部隆起的部位，指身体部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "屁股", "is_correct": true, "explanation": "正确答案。屁股（pì gu）指人体后部、大腿根与腰之间隆起的部分，是口语说法。"}, {"text": "皮鼓", "is_correct": false, "explanation": "pí（第二声）与 pì（第四声）声调不同，皮鼓（pí gǔ）指用皮革蒙面的鼓。"}, {"text": "皮骨", "is_correct": false, "explanation": "pí（第二声）与 pì（第四声）声调不同，皮骨（pí gǔ）指皮和骨头，常见于“皮包骨”。"}, {"text": "皮箍", "is_correct": false, "explanation": "pí（第二声）与 pì（第四声）声调不同，皮箍（pí gū）指皮革做的箍。"}, {"text": "鼻骨", "is_correct": false, "explanation": "bí（第二声）与 pì 声母不同（b 与 p），声调也不同，鼻骨（bí gǔ）指鼻子的骨头。"}], "explanations": {"屁股": "正确答案。屁股（pì gu）指人体后部、大腿根与腰之间隆起的部分，是口语说法。", "皮鼓": "pí（第二声）与 pì（第四声）声调不同，皮鼓（pí gǔ）指用皮革蒙面的鼓。", "皮骨": "pí（第二声）与 pì（第四声）声调不同，皮骨（pí gǔ）指皮和骨头，常见于“皮包骨”。", "皮箍": "pí（第二声）与 pì（第四声）声调不同，皮箍（pí gū）指皮革做的箍。", "鼻骨": "bí（第二声）与 pì 声母不同（b 与 p），声调也不同，鼻骨（bí gǔ）指鼻子的骨头。"}, "sentence_index": null, "correct_answer": "屁股"}, "level_3": {"options": [{"text": "屁股", "is_correct": true, "explanation": "屁股是身体部位，摔倒后会感到疼，符合语境。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，没有痛感，不会感到疼。"}, {"text": "哭声", "is_correct": false, "explanation": "搭配：“疼”说的是身体的感觉，一般不用来形容声音。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不会感到疼。"}], "explanations": {"屁股": "屁股是身体部位，摔倒后会感到疼，符合语境。", "书包": "语义：书包是物品，没有痛感，不会感到疼。", "哭声": "搭配：“疼”说的是身体的感觉，一般不用来形容声音。", "窗户": "语义：窗户是建筑部件，不会感到疼。"}, "sentence_index": 0, "correct_answer": "屁股"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃得太多，屁股撑得难受。", "explanation": "这里应该用〈肚子〉。屁股指臀部，吃撑了胃肠胀得难受要说肚子，不说屁股。"}, {"text": "他唱了一晚上歌，屁股哑了。", "explanation": "这里应该用〈嗓子〉。屁股是臀部，发不出声，唱累了嗓子哑要说嗓子。"}, {"text": "床上躺着一条屁股。", "explanation": "这里应该用〈个〉。量词“条”用于细长的东西，不能用来数“屁股”，屁股应搭配“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屁股", "is_correct": true, "explanation": "屁股能随身体一起扭动，与“摇着尾巴”的语境相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不能跟着小狗扭动。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“扭”一般说身体部位或动物的动作，不说桌子扭。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不会自己扭动。"}], "explanations": {"屁股": "屁股能随身体一起扭动，与“摇着尾巴”的语境相符。", "课本": "语义：课本是书籍，不能跟着小狗扭动。", "桌子": "搭配：“扭”一般说身体部位或动物的动作，不说桌子扭。", "沙发": "语义：沙发是家具，不会自己扭动。"}, "sentence_index": 6, "correct_answer": "屁股"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弯下屁股捡起了钱包。", "explanation": "这里应该用〈腰〉。“弯腰”指上身向前弯，屁股不能弯，“弯下屁股”不是习惯说法。"}, {"text": "他感冒了，屁股一直不通气。", "explanation": "这里应该用〈鼻子〉。屁股是臀部，不能说不通气，鼻塞要说鼻子。"}, {"text": "我在地上捡到一块屁股。", "explanation": "这里应该用〈个〉。量词“块”用于块状的东西，不能用来数“屁股”，屁股应搭配“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他摔了一跤，屁股的很疼。", "corrected_sentence": "他摔了一跤，屁股很疼。", "error_description": "“屁股”后多加了“的”，写成“屁股的很疼”，“的”使“屁股”变成所属修饰语，句子不完整；正确为“屁股很疼”，“屁股”作主语，后面直接接谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐在台阶上，屁股了凉。", "corrected_sentence": "他坐在台阶上，屁股凉了。", "error_description": "“凉了”中的“了”表示变化，位于“凉”之后；写成“了凉”语序错误，正确为“屁股凉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
