INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90961, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感染是细小的坏东西跑进身体里，让人生病。", "primary_collocate": null, "pronunciation": "gǎn rǎn", "ipa": "kan²¹⁴ ʐan²¹⁴", "syllable_count": 2, "sentences": [{"text": "他的手受伤了，伤口感染了。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子感冒了，我怕自己也会感染。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，伤口感染会发烧。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没洗手就吃饭，感染了细菌。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个医院很干净，病人很少感染。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去过那个地方，后来感染了病毒。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口太脏，很容易感染。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感染了流感，在家休息三天。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的耳朵感染了，一直在抓。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打了针，就不容易感染这种病毒。", "target_word": "感染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感染了", "label": "体标（完成）"}, {"form": "感染过", "label": "体标（经历）"}, {"form": "感染者", "label": "复合"}], "register": "中性", "sense_fingerprint": "细菌或病毒进入身体，使人或动物生病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感染", "is_correct": true, "explanation": "感染：细菌或病毒进入身体，伤口因此发炎，与“伤口”搭配。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”需要有表情的人，伤口不会微笑。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”的主体是能发声的人，伤口不能唱歌。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”的主语须是能付钱的人，伤口不能做“买”的主语。"}], "explanations": {"感染": "感染：细菌或病毒进入身体，伤口因此发炎，与“伤口”搭配。", "微笑": "语义：“微笑”需要有表情的人，伤口不会微笑。", "唱歌": "语义：“唱歌”的主体是能发声的人，伤口不能唱歌。", "买": "配价：“买”的主语须是能付钱的人，伤口不能做“买”的主语。"}, "sentence_index": 0, "correct_answer": "感染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "衣服不小心感染了油渍。", "explanation": "这里应该用〈沾染〉。感染指病原体侵入人或动物的身体，衣服沾上油渍应用沾染。"}, {"text": "药物感染了他的病，他很快就好了。", "explanation": "这里应该用〈治愈〉。感染是病原体侵入身体，不能用来说药物让病好。"}, {"text": "他感染了一块石头。", "explanation": "这里应该用〈污染〉。感染只指病原体侵入人或动物的身体，石头不能被感染；使物体受污染应用“污染”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感染", "is_correct": true, "explanation": "感染：伤口脏了容易被病菌侵入，与“很容易”搭配。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：伤口不会跳舞，“很容易跳舞”说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：伤口不会睡觉，“很容易睡觉”不成立。"}, {"text": "写作", "is_correct": false, "explanation": "配价：“写作”的施事须是人，伤口不能做“写作”的主语。"}], "explanations": {"感染": "感染：伤口脏了容易被病菌侵入，与“很容易”搭配。", "跳舞": "语义：伤口不会跳舞，“很容易跳舞”说不通。", "睡觉": "语义：伤口不会睡觉，“很容易睡觉”不成立。", "写作": "配价：“写作”的施事须是人，伤口不能做“写作”的主语。"}, "sentence_index": 6, "correct_answer": "感染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块白布被感染成了红色。", "explanation": "这里的“感染”不能表示给布上色，它只指病原体进入身体引起疾病。"}, {"text": "他感染了一瓶牛奶。", "explanation": "这里的“感染”指病原体进入人或动物的身体，不能指食物被污染。"}, {"text": "他感染了一阵风。", "explanation": "这里应该用〈影响〉。感染只指病原体侵入人或动物的身体，风这类自然现象不能被感染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子感染很得厉害，发烧到三十九度。", "corrected_sentence": "孩子感染得很厉害，发烧到三十九度。", "error_description": "补语位置错误：“得”后应接补语“很厉害”，应为“感染得很厉害”，不能说“感染很得厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年感染了过肺炎，所以很小心。", "corrected_sentence": "他去年感染过肺炎，所以很小心。", "error_description": "体标错误：动词后的“了”与“过”不能同时出现，表示经历只用“过”，应为“感染过肺炎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
