INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90963, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不要了，没有用，丢掉。", "primary_collocate": null, "pronunciation": "fèi", "ipa": "fei˥˩", "syllable_count": 1, "sentences": [{"text": "这双旧鞋已经废了，扔掉吧。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些笔都没水了，废了，扔掉吧。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧电池没电了，废了就扔进垃圾桶。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑太慢了，我打算把它废掉。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧报纸没用了，都废掉吧。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子摔成了两半，只好废了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的旧手机掉进水里，彻底废了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画错了，就把那张纸废了，重新画。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧裤子穿不了了，该废了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣柜里的旧袜子都破了，可以废掉了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "废了", "label": "体标"}, {"form": "废纸", "label": "复合"}, {"form": "废物", "label": "复合"}, {"form": "廢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "废：东西没有用了、不要了，扔掉或不再留着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90963, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。废指东西没用了、不要了，扔掉。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，意思是飞。"}, {"text": "肥", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，意思是肥胖、肥料。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 fèi 声母不同（p/f），意思是配合、搭配。"}, {"text": "份", "is_correct": false, "explanation": "fèn 与 fèi 韵母不同（n/i），意思是份额、一份。"}], "explanations": {"废": "正确。废指东西没用了、不要了，扔掉。", "飞": "fēi（第一声）与 fèi（第四声）声调不同，意思是飞。", "肥": "féi（第二声）与 fèi（第四声）声调不同，意思是肥胖、肥料。", "配": "pèi 与 fèi 声母不同（p/f），意思是配合、搭配。", "份": "fèn 与 fèi 韵母不同（n/i），意思是份额、一份。"}, "sentence_index": null, "correct_answer": "废"}, "level_3": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。“已经废了”表示鞋子已不能用，与“扔掉吧”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖了”说明已经出售，与“扔掉吧”的语境矛盾。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者（送给某人），单说“已经送了”不完整，且与“扔掉吧”矛盾。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”表示修好，与旧鞋已坏、该扔掉的语境矛盾。"}], "explanations": {"废": "正确。“已经废了”表示鞋子已不能用，与“扔掉吧”相符。", "卖": "语义：“卖了”说明已经出售，与“扔掉吧”的语境矛盾。", "送": "配价：“送”需要接受者（送给某人），单说“已经送了”不完整，且与“扔掉吧”矛盾。", "修": "语义：“修”表示修好，与旧鞋已坏、该扔掉的语境矛盾。"}, "sentence_index": 0, "correct_answer": "废"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机坏了，废一下还能用。", "explanation": "这里应该用〈修〉。废表示东西已经没用、要扔掉，不能用来说修好后还能用。"}, {"text": "他在家废了一上午，什么也没干。", "explanation": "这里的〈废〉指荒废、白白耗费时间，与本句需要的“东西没用了、扔掉”的义项不同。"}, {"text": "我把旧衣服废给了希望小学。", "explanation": "这里应该用〈送〉。废表示把没用的东西扔掉，不能带接受者，不能说“废给”某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90963, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。废指东西没用了、不要了，扔掉。"}, {"text": "非", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，意思是不是、非。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 fèi（第四声）声调不同，意思是土匪。"}, {"text": "佩", "is_correct": false, "explanation": "pèi 与 fèi 声母不同（p/f），意思是佩带。"}, {"text": "奋", "is_correct": false, "explanation": "fèn 与 fèi 韵母不同（n/i），意思是奋力、奋斗。"}], "explanations": {"废": "正确。废指东西没用了、不要了，扔掉。", "非": "fēi（第一声）与 fèi（第四声）声调不同，意思是不是、非。", "匪": "fěi（第三声）与 fèi（第四声）声调不同，意思是土匪。", "佩": "pèi 与 fèi 声母不同（p/f），意思是佩带。", "奋": "fèn 与 fèi 韵母不同（n/i），意思是奋力、奋斗。"}, "sentence_index": null, "correct_answer": "废"}, "level_3": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。“彻底废了”表示手机已损坏、不能再用。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指购入，与“掉进水里、彻底”的语境不合，句意不通。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借”表示向人借用，与手机损坏的语境不合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般用于衣物等可清洗的东西，不说“彻底洗了”来形容手机损坏。"}], "explanations": {"废": "正确。“彻底废了”表示手机已损坏、不能再用。", "买": "语义：“买”指购入，与“掉进水里、彻底”的语境不合，句意不通。", "借": "语义：“借”表示向人借用，与手机损坏的语境不合。", "洗": "搭配：“洗”一般用于衣物等可清洗的东西，不说“彻底洗了”来形容手机损坏。"}, "sentence_index": 6, "correct_answer": "废"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想废一台新电脑。", "explanation": "这里应该用〈买〉。废表示东西没用了要扔掉，用在想要的新电脑上不合理。"}, {"text": "政府决定废了这条旧税。", "explanation": "这里的〈废〉指废除、取消的意思，与本句“东西没用了、扔掉”的义项不同。"}, {"text": "妈妈把脏衣服废干净了。", "explanation": "这里应该用〈洗〉。废是东西不要了、扔掉的意思，不能说把脏衣服“废干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把那堆旧报纸废了了，拿去回收吧。", "corrected_sentence": "我把那堆旧报纸废了，拿去回收吧。", "error_description": "错误在“了”多出一个。“废了”的“了”只用一次，应说“我把那堆旧报纸废了，拿去回收吧”，“废了了”重复了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那把旧伞了废，拿去扔掉吧。", "corrected_sentence": "我把那把旧伞废了，拿去扔掉吧。", "error_description": "“了”应紧跟动词，应说“废了”；“了废”的语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
