INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90969, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人有高兴的事，我们说好话让他更高兴。", "primary_collocate": null, "pronunciation": "gōng xǐ", "ipa": "kʊŋ˥ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "你赢了比赛，恭喜恭喜！", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新年到了，大家见面都说恭喜。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "恭喜你，你的小狗生宝宝了！", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我说一声恭喜，他笑得很开心。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时，孩子对爷爷说：“恭喜，恭喜！”", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "恭喜你们，希望你们永远幸福。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了新房子，我对他说一声恭喜。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，大家对冠军说恭喜。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她收到了好消息，我高兴地说：“恭喜你！”", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到你当爸爸了，我真想亲口对你说恭喜。", "target_word": "恭喜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恭喜恭喜", "label": "重叠"}], "register": "口语", "sense_fingerprint": "遇到别人的喜事时说出的祝贺话，常作客套话或感叹用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。恭喜作客套话，用于遇到别人的喜事时说祝贺的话。"}, {"text": "工细", "is_correct": false, "explanation": "gōngxì 与 gōngxǐ 只差声调（第四声与第三声），意思是精细。"}, {"text": "公子", "is_correct": false, "explanation": "gōngzǐ 与 gōngxǐ 第二个音节声母不同（z/x），意思是公子。"}, {"text": "公使", "is_correct": false, "explanation": "gōngshǐ 与 gōngxǐ 第二个音节声母不同（sh/x），意思是公使。"}, {"text": "供给", "is_correct": false, "explanation": "gōngjǐ 与 gōngxǐ 第二个音节只差声母（j/x），意思是供给。"}], "explanations": {"恭喜": "正确。恭喜作客套话，用于遇到别人的喜事时说祝贺的话。", "工细": "gōngxì 与 gōngxǐ 只差声调（第四声与第三声），意思是精细。", "公子": "gōngzǐ 与 gōngxǐ 第二个音节声母不同（z/x），意思是公子。", "公使": "gōngshǐ 与 gōngxǐ 第二个音节声母不同（sh/x），意思是公使。", "供给": "gōngjǐ 与 gōngxǐ 第二个音节只差声母（j/x），意思是供给。"}, "sentence_index": null, "correct_answer": "恭喜"}, "level_3": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。“你赢了比赛，恭喜恭喜！”是遇到喜事时的祝贺话。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”表示认错，与赢了比赛的喜事语境矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示伤心，与赢了比赛的喜庆语境不合。"}, {"text": "节哀", "is_correct": false, "explanation": "语域：“节哀”是书面化的安慰语，不用于口语中贺喜的场合。"}], "explanations": {"恭喜": "正确。“你赢了比赛，恭喜恭喜！”是遇到喜事时的祝贺话。", "道歉": "语义：“道歉”表示认错，与赢了比赛的喜事语境矛盾。", "哭": "语义：“哭”表示伤心，与赢了比赛的喜庆语境不合。", "节哀": "语域：“节哀”是书面化的安慰语，不用于口语中贺喜的场合。"}, "sentence_index": 0, "correct_answer": "恭喜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去医院恭喜病人。", "explanation": "这里应该用〈慰问〉。恭喜用于祝贺喜事，不能用于探望生病的人。"}, {"text": "他考试没考好，我恭喜他。", "explanation": "这里应该用〈同情〉。恭喜是祝贺喜事，考试失利时不能说恭喜。"}, {"text": "他生病了，我恭喜他。", "explanation": "这里应该用〈安慰〉。恭喜是祝贺喜事，对方生病时不能说恭喜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90969, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。恭喜作客套话，用于遇到别人的喜事时说祝贺的话。"}, {"text": "公主", "is_correct": false, "explanation": "gōngzhǔ 与 gōngxǐ 第二个音节只差声母（zh/x），意思是公主。"}, {"text": "工序", "is_correct": false, "explanation": "gōngxù 与 gōngxǐ 只差声调（第四声与第三声），意思是工序。"}, {"text": "公鸡", "is_correct": false, "explanation": "gōngjī 与 gōngxǐ 第二个音节声母不同（j/x）且声调不同，意思是公鸡。"}], "explanations": {"恭喜": "正确。恭喜作客套话，用于遇到别人的喜事时说祝贺的话。", "公主": "gōngzhǔ 与 gōngxǐ 第二个音节只差声母（zh/x），意思是公主。", "工序": "gōngxù 与 gōngxǐ 只差声调（第四声与第三声），意思是工序。", "公鸡": "gōngjī 与 gōngxǐ 第二个音节声母不同（j/x）且声调不同，意思是公鸡。"}, "sentence_index": null, "correct_answer": "恭喜"}, "level_3": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。“他买了新房子，我对他说一声恭喜”表示祝贺。"}, {"text": "哀悼", "is_correct": false, "explanation": "语义：“哀悼”表示悼念去世的人，与买了新房子的喜事不合。"}, {"text": "吐槽", "is_correct": false, "explanation": "语义：“吐槽”指调侃或抱怨，与祝贺新房的语境不合。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表示不满，与祝贺的语境相反。"}], "explanations": {"恭喜": "正确。“他买了新房子，我对他说一声恭喜”表示祝贺。", "哀悼": "语义：“哀悼”表示悼念去世的人，与买了新房子的喜事不合。", "吐槽": "语义：“吐槽”指调侃或抱怨，与祝贺新房的语境不合。", "抱怨": "语义：“抱怨”表示不满，与祝贺的语境相反。"}, "sentence_index": 6, "correct_answer": "恭喜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈恭喜我的画。", "explanation": "这里应该用〈赞美〉。恭喜是对喜事的祝贺，不能用来称赞画作。"}, {"text": "我们在车站恭喜，互相挥手。", "explanation": "这里应该用〈告别〉。恭喜是祝贺的话，不能用来表示分别时的动作。"}, {"text": "妈妈恭喜我不听话。", "explanation": "这里应该用〈责备〉。恭喜是祝贺喜事，不能用来指责别人的错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试你拿了第一，恭喜的你！", "corrected_sentence": "这次考试你拿了第一，恭喜你！", "error_description": "“恭喜”是动词，后面直接接宾语“你”，中间不能插入“的”，应说“恭喜你！”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
