INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90970, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向人表示祝贺。", "primary_collocate": null, "pronunciation": "gōng xǐ", "ipa": "kʊŋ˥ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他考上大学了，我去恭喜他。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说你结婚了，恭喜你！", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们都来恭喜我拿到了第一名。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打电话恭喜姐姐生了女儿。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事们都来恭喜他升职。", "target_word": "恭喜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想恭喜你们，你们的店开张了。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家站起来，恭喜新郎和新娘。", "target_word": "恭喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着花来恭喜我的好朋友。", "target_word": "恭喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师笑着恭喜我们取得好成绩。", "target_word": "恭喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没有恭喜你得了冠军呢，现在补上。", "target_word": "恭喜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恭喜恭喜", "label": "重叠"}], "register": "口语", "sense_fingerprint": "对别人的喜事表示祝贺，常带对象：恭喜某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。恭喜指向别人的喜事表示祝贺。"}, {"text": "工细", "is_correct": false, "explanation": "gōngxì 与 gōngxǐ 只差声调（第四声与第三声），意思是精细。"}, {"text": "公子", "is_correct": false, "explanation": "gōngzǐ 与 gōngxǐ 第二个音节声母不同（z/x），意思是公子。"}, {"text": "公使", "is_correct": false, "explanation": "gōngshǐ 与 gōngxǐ 第二个音节声母不同（sh/x），意思是公使。"}, {"text": "供给", "is_correct": false, "explanation": "gōngjǐ 与 gōngxǐ 第二个音节只差声母（j/x），意思是供给。"}], "explanations": {"恭喜": "正确。恭喜指向别人的喜事表示祝贺。", "工细": "gōngxì 与 gōngxǐ 只差声调（第四声与第三声），意思是精细。", "公子": "gōngzǐ 与 gōngxǐ 第二个音节声母不同（z/x），意思是公子。", "公使": "gōngshǐ 与 gōngxǐ 第二个音节声母不同（sh/x），意思是公使。", "供给": "gōngjǐ 与 gōngxǐ 第二个音节只差声母（j/x），意思是供给。"}, "sentence_index": null, "correct_answer": "恭喜"}, "level_3": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。“他考上大学了，我去恭喜他”表示祝贺喜事。"}, {"text": "慰问", "is_correct": false, "explanation": "搭配：“慰问”多用于病人、灾区等，不用于考上大学的人。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”表示宽慰，与“考上大学”的喜事语境不合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出错误，与喜事的语境矛盾。"}], "explanations": {"恭喜": "正确。“他考上大学了，我去恭喜他”表示祝贺喜事。", "慰问": "搭配：“慰问”多用于病人、灾区等，不用于考上大学的人。", "安慰": "语义：“安慰”表示宽慰，与“考上大学”的喜事语境不合。", "批评": "语义：“批评”指指出错误，与喜事的语境矛盾。"}, "sentence_index": 0, "correct_answer": "恭喜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐失恋了，我打电话恭喜她。", "explanation": "这里应该用〈安慰〉。恭喜用于对方有喜事时的祝贺，对方失恋时不能说恭喜。"}, {"text": "他帮了我很多，我恭喜他。", "explanation": "这里应该用〈感谢〉。恭喜是对喜事的祝贺，不能用来表示对帮助的感谢。"}, {"text": "他做错事后，他向我恭喜。", "explanation": "这里应该用〈道歉〉。恭喜是祝贺喜事，不能用来表示认错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。恭喜指向别人的喜事表示祝贺。"}, {"text": "公主", "is_correct": false, "explanation": "gōngzhǔ 与 gōngxǐ 第二个音节只差声母（zh/x），意思是公主。"}, {"text": "工序", "is_correct": false, "explanation": "gōngxù 与 gōngxǐ 只差声调（第四声与第三声），意思是工序。"}, {"text": "公鸡", "is_correct": false, "explanation": "gōngjī 与 gōngxǐ 第二个音节声母不同（j/x）且声调不同，意思是公鸡。"}], "explanations": {"恭喜": "正确。恭喜指向别人的喜事表示祝贺。", "公主": "gōngzhǔ 与 gōngxǐ 第二个音节只差声母（zh/x），意思是公主。", "工序": "gōngxù 与 gōngxǐ 只差声调（第四声与第三声），意思是工序。", "公鸡": "gōngjī 与 gōngxǐ 第二个音节声母不同（j/x）且声调不同，意思是公鸡。"}, "sentence_index": null, "correct_answer": "恭喜"}, "level_3": {"options": [{"text": "恭喜", "is_correct": true, "explanation": "正确。“大家站起来，恭喜新郎和新娘”表示祝贺。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”表示驱逐，与婚礼祝贺的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讽刺，与祝贺新人的语境不合。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”表示斥责，与祝贺新人的场合相反。"}], "explanations": {"恭喜": "正确。“大家站起来，恭喜新郎和新娘”表示祝贺。", "赶走": "语义：“赶走”表示驱逐，与婚礼祝贺的语境相反。", "嘲笑": "语义：“嘲笑”带有讽刺，与祝贺新人的语境不合。", "骂": "语义：“骂”表示斥责，与祝贺新人的场合相反。"}, "sentence_index": 6, "correct_answer": "恭喜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师恭喜我的作文写得好。", "explanation": "这里应该用〈夸奖〉。恭喜是对对方喜事的祝贺，不能用来评价作文，也不能带作文作宾语。"}, {"text": "大家都在恭喜他的离世。", "explanation": "这里应该用〈哀悼〉。恭喜用于喜事，不能用于表示悼念去世的人。"}, {"text": "班主任恭喜我上课迟到。", "explanation": "这里应该用〈责备〉。恭喜是祝贺喜事，不能用来指责迟到的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听说你升职了，恭喜的你！", "corrected_sentence": "听说你升职了，恭喜你！", "error_description": "“恭喜”是动词，后面直接接宾语“你”，中间不能插入“的”，应说“恭喜你！”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚才恭喜着你，你没听到吧。", "corrected_sentence": "我刚才恭喜了你，你没听到吧。", "error_description": "表示动作已完成应用“了”，“恭喜着你”中的“着”表示持续状态，与“刚才”的已完成语境不符，应说“恭喜了你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
