INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搭是把东西放在一起，做成一个架子或房子。", "primary_collocate": null, "pronunciation": "dā", "ipa": "ta˥", "syllable_count": 1, "sentences": [{"text": "爸爸在院子里搭了一个小棚子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山上搭帐篷过夜。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用积木搭了一座房子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在搭一个高架子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想搭一间小木屋。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，大家把帐篷搭好了。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用竹子搭了个架子，让黄瓜往上长。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个台子是谁搭的？", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边搭着一个大帐篷。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用纸盒搭了一个小城堡。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搭了", "label": "体标"}, {"form": "搭着", "label": "体标"}, {"form": "搭过", "label": "体标"}, {"form": "搭建", "label": "复合"}, {"form": "搭好", "label": "复合"}], "register": "通用", "sense_fingerprint": "搭：把东西拼起来做成架子或房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搭", "is_correct": true, "explanation": "正确：搭（dā）表示把东西拼起来做成架子或房子。"}, {"text": "打", "is_correct": false, "explanation": "dǎ（第三声）与 dā（第一声）声调不同，意思是“打”，指击打。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dā（第一声）声调不同，意思是“大”。"}, {"text": "答", "is_correct": false, "explanation": "dá（第二声）与 dā（第一声）声调不同，意思是“回答”。"}, {"text": "他", "is_correct": false, "explanation": "tā 与 dā 声母不同（t 与 d），意思是“他”。"}, {"text": "灯", "is_correct": false, "explanation": "dēng 与 dā 韵母不同（eng 与 a），意思是“灯”。"}], "explanations": {"搭": "正确：搭（dā）表示把东西拼起来做成架子或房子。", "打": "dǎ（第三声）与 dā（第一声）声调不同，意思是“打”，指击打。", "大": "dà（第四声）与 dā（第一声）声调不同，意思是“大”。", "答": "dá（第二声）与 dā（第一声）声调不同，意思是“回答”。", "他": "tā 与 dā 声母不同（t 与 d），意思是“他”。", "灯": "dēng 与 dā 韵母不同（eng 与 a），意思是“灯”。"}, "sentence_index": null, "correct_answer": "搭"}, "level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "语义：挖是掘土，不能挖出一个小棚子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不能用来做小棚子。"}, {"text": "搭", "is_correct": true, "explanation": "正确：搭表示架设、搭建，“爸爸在院子里搭了一个小棚子”成立。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于能骑的东西，不能说“骑一个小棚子”。"}], "explanations": {"挖": "语义：挖是掘土，不能挖出一个小棚子。", "唱": "语义：唱是唱歌，不能用来做小棚子。", "搭": "正确：搭表示架设、搭建，“爸爸在院子里搭了一个小棚子”成立。", "骑": "搭配：“骑”用于能骑的东西，不能说“骑一个小棚子”。"}, "sentence_index": 0, "correct_answer": "搭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座摩天大楼是他们搭的。", "explanation": "这里应该用〈建〉。搭指搭建简单的架子或棚子，摩天大楼这样的大型建筑要用“建”。"}, {"text": "他在纸上搭了一只猫。", "explanation": "这里应该用〈画〉。搭不表示在纸上画画。"}, {"text": "孩子们在教室里搭了一首歌。", "explanation": "这里应该用〈唱〉。搭不表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搭", "is_correct": true, "explanation": "正确：搭（dā）表示把东西拼起来做成架子或房子。"}, {"text": "八", "is_correct": false, "explanation": "bā 与 dā 声母不同（b 与 d），意思是“八”。"}, {"text": "哈", "is_correct": false, "explanation": "hā 与 dā 声母不同（h 与 d），意思是“哈”。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dā 韵母不同（ang 与 a），意思是“当”。"}, {"text": "都", "is_correct": false, "explanation": "dōu 与 dā 韵母不同（ou 与 a），意思是“都”。"}, {"text": "低", "is_correct": false, "explanation": "dī 与 dā 韵母不同（i 与 a），意思是“低”。"}, {"text": "达", "is_correct": false, "explanation": "dá（第二声）与 dā（第一声）声调不同，意思是“到达”。"}], "explanations": {"搭": "正确：搭（dā）表示把东西拼起来做成架子或房子。", "八": "bā 与 dā 声母不同（b 与 d），意思是“八”。", "哈": "hā 与 dā 声母不同（h 与 d），意思是“哈”。", "当": "dāng 与 dā 韵母不同（ang 与 a），意思是“当”。", "都": "dōu 与 dā 韵母不同（ou 与 a），意思是“都”。", "低": "dī 与 dā 韵母不同（i 与 a），意思是“低”。", "达": "dá（第二声）与 dā（第一声）声调不同，意思是“到达”。"}, "sentence_index": null, "correct_answer": "搭"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：烧是使东西燃烧，竹子烧了就做不成架子。"}, {"text": "搭", "is_correct": true, "explanation": "正确：搭表示用材料做成架子，“爷爷用竹子搭了个架子”成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是吃东西，竹子不能吃，也做不成架子。"}, {"text": "敲", "is_correct": false, "explanation": "搭配：“敲”是打击动作，不能说“敲了个架子”。"}], "explanations": {"烧": "语义：烧是使东西燃烧，竹子烧了就做不成架子。", "搭": "正确：搭表示用材料做成架子，“爷爷用竹子搭了个架子”成立。", "吃": "语义：吃是吃东西，竹子不能吃，也做不成架子。", "敲": "搭配：“敲”是打击动作，不能说“敲了个架子”。"}, "sentence_index": 6, "correct_answer": "搭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里搭了一排白菜。", "explanation": "这里应该用〈种〉。搭表示架设或搭建，不表示种植。"}, {"text": "他每天搭一个苹果当早饭。", "explanation": "这里应该用〈吃〉。搭不表示吃东西。"}, {"text": "她用笔搭字。", "explanation": "这里应该用〈写〉。搭不表示写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把木架搭了好。", "corrected_sentence": "我们把木架搭好了。", "error_description": "结果补语“好”要紧跟动词，动态助词“了”放在“好”之后，应说“搭好了”，不能说“搭了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把帐篷搭很结实。", "corrected_sentence": "工人把帐篷搭得很结实。", "error_description": "“搭”后面的程度补语要用“得”，应说“搭得很结实”，这里漏了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90974, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆", "is_correct": true, "explanation": "正确：拆表示拆除、拆掉，与“搭帐篷”的架设义构成反义。"}, {"text": "扔", "is_correct": false, "explanation": "扔表示丢弃，与“搭”的架设义没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱表示唱歌，与“搭”没有反义关系。"}, {"text": "挖", "is_correct": false, "explanation": "挖表示掘取，与“搭”的架设义没有反义关系。"}], "correct_answer": "拆", "explanations": {"拆": "正确：拆表示拆除、拆掉，与“搭帐篷”的架设义构成反义。", "扔": "扔表示丢弃，与“搭”的架设义没有反义关系。", "唱": "唱表示唱歌，与“搭”没有反义关系。", "挖": "挖表示掘取，与“搭”的架设义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
