INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "支起；架设；连接在一起；乘坐。", "primary_collocate": null, "pronunciation": "dā", "ipa": "ta˥", "syllable_count": 1, "sentences": [{"text": "我每天搭地铁去上班。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在河上搭了一座小桥。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我搭朋友的车回家。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在操场上搭了帐篷。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在路边搭起了舞台。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两根电线搭在一起会短路。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去机场可以搭公共汽车。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用木板搭了一个小台子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们搭上了最后一班火车。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想搭一下你的车去车站。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搭了", "label": "体标"}, {"form": "搭着", "label": "体标"}, {"form": "搭过", "label": "体标"}, {"form": "搭建", "label": "复合"}, {"form": "搭桥", "label": "复合"}], "register": "通用", "sense_fingerprint": "搭：支起、架设、连接、乘坐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搭", "is_correct": true, "explanation": "正确：搭（dā）表示支起、架设、连接或乘坐。"}, {"text": "打", "is_correct": false, "explanation": "dǎ（第三声）与 dā（第一声）声调不同，意思是“打”，指击打。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dā（第一声）声调不同，意思是“大”。"}, {"text": "答", "is_correct": false, "explanation": "dá（第二声）与 dā（第一声）声调不同，意思是“回答”。"}, {"text": "他", "is_correct": false, "explanation": "tā 与 dā 声母不同（t 与 d），意思是“他”。"}, {"text": "灯", "is_correct": false, "explanation": "dēng 与 dā 韵母不同（eng 与 a），意思是“灯”。"}], "explanations": {"搭": "正确：搭（dā）表示支起、架设、连接或乘坐。", "打": "dǎ（第三声）与 dā（第一声）声调不同，意思是“打”，指击打。", "大": "dà（第四声）与 dā（第一声）声调不同，意思是“大”。", "答": "dá（第二声）与 dā（第一声）声调不同，意思是“回答”。", "他": "tā 与 dā 声母不同（t 与 d），意思是“他”。", "灯": "dēng 与 dā 韵母不同（eng 与 a），意思是“灯”。"}, "sentence_index": null, "correct_answer": "搭"}, "level_3": {"options": [{"text": "推", "is_correct": false, "explanation": "语义：推是用力使物体移动，地铁不能被推着去上班。"}, {"text": "搭", "is_correct": true, "explanation": "正确：搭表示乘坐，“我每天搭地铁去上班”成立。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于自行车、马等能骑的东西，不能说“骑地铁”。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是写字，不能用来表示乘坐交通工具去上班。"}], "explanations": {"推": "语义：推是用力使物体移动，地铁不能被推着去上班。", "搭": "正确：搭表示乘坐，“我每天搭地铁去上班”成立。", "骑": "搭配：“骑”用于自行车、马等能骑的东西，不能说“骑地铁”。", "写": "语义：写是写字，不能用来表示乘坐交通工具去上班。"}, "sentence_index": 0, "correct_answer": "搭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼是我们搭的。", "explanation": "这里应该用〈建〉。搭指支起或架设简单的东西，大楼这样的大型建筑要用“建”。"}, {"text": "他一个人搭着箱子上楼。", "explanation": "这里应该用〈扛〉。搭表示架设或连接，不表示扛着东西。"}, {"text": "妈妈在厨房里搭了一顿饭。", "explanation": "这里应该用〈做〉。搭不表示做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搭", "is_correct": true, "explanation": "正确：搭（dā）表示支起、架设、连接或乘坐。"}, {"text": "八", "is_correct": false, "explanation": "bā 与 dā 声母不同（b 与 d），意思是“八”。"}, {"text": "哈", "is_correct": false, "explanation": "hā 与 dā 声母不同（h 与 d），意思是“哈”。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dā 韵母不同（ang 与 a），意思是“当”。"}, {"text": "都", "is_correct": false, "explanation": "dōu 与 dā 韵母不同（ou 与 a），意思是“都”。"}, {"text": "低", "is_correct": false, "explanation": "dī 与 dā 韵母不同（i 与 a），意思是“低”。"}, {"text": "达", "is_correct": false, "explanation": "dá（第二声）与 dā（第一声）声调不同，意思是“到达”。"}], "explanations": {"搭": "正确：搭（dā）表示支起、架设、连接或乘坐。", "八": "bā 与 dā 声母不同（b 与 d），意思是“八”。", "哈": "hā 与 dā 声母不同（h 与 d），意思是“哈”。", "当": "dāng 与 dā 韵母不同（ang 与 a），意思是“当”。", "都": "dōu 与 dā 韵母不同（ou 与 a），意思是“都”。", "低": "dī 与 dā 韵母不同（i 与 a），意思是“低”。", "达": "dá（第二声）与 dā（第一声）声调不同，意思是“到达”。"}, "sentence_index": null, "correct_answer": "搭"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：烧是使东西燃烧，不能用来去机场。"}, {"text": "搭", "is_correct": true, "explanation": "正确：搭表示乘坐，“你去机场可以搭公共汽车”成立。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”是用脚踩，不能说“踩公共汽车”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，不能用来去机场。"}], "explanations": {"烧": "语义：烧是使东西燃烧，不能用来去机场。", "搭": "正确：搭表示乘坐，“你去机场可以搭公共汽车”成立。", "踩": "搭配：“踩”是用脚踩，不能说“踩公共汽车”。", "扔": "语义：扔是丢弃，不能用来去机场。"}, "sentence_index": 6, "correct_answer": "搭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他搭了一朵花送给妈妈。", "explanation": "这里应该用〈摘〉。搭不表示采摘花朵。"}, {"text": "她搭了一封信寄给朋友。", "explanation": "这里应该用〈写〉。搭不表示写字。"}, {"text": "我去超市搭了一些菜。", "explanation": "这里应该用〈买〉。搭不表示购买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在广场上搭下来了一个小舞台。", "corrected_sentence": "我们在广场上搭起了一个小舞台。", "error_description": "“搭”表示支起时，结果补语要用“起”，应说“搭起”；“搭下来”不成词，这里应改为“搭起了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我想搭了一下你的车去车站。", "corrected_sentence": "明天我想搭一下你的车去车站。", "error_description": "“想”后面的动词不带“了”，应说“想搭一下”，这里的“了”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
