INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西一个挨着一个，放得整整齐齐。", "primary_collocate": null, "pronunciation": "pái liè", "ipa": "pʰaɪ˧˥ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们把玩具排列得很整齐。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的书排列得整整齐齐。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这些椅子排列成一行。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友排列成一圈，手拉着手。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的饮料一瓶挨着一瓶排列着。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树在路的两边排列得很整齐。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把小石头排列在窗台上。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上，书一本挨着一本排列。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把照片排列在墙上，很好看。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里的水果排列成一朵花的样子。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "排列了", "label": "体标"}, {"form": "排列着", "label": "体标"}, {"form": "排列过", "label": "体标"}, {"form": "排列组合", "label": "复合"}], "register": "中性", "sense_fingerprint": "把具体的人或物一个挨一个整齐地摆放成行或成形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉的意思，不能把玩具扔得整整齐齐。"}, {"text": "排列", "is_correct": true, "explanation": "“排列”指把东西一个挨一个摆好，与“玩具……得很整齐”相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”会把东西弄坏，不能让玩具呈现整齐的状态。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象多是球类，不能说把玩具踢得很整齐。"}], "explanations": {"扔": "语义：“扔”是丢掉的意思，不能把玩具扔得整整齐齐。", "排列": "“排列”指把东西一个挨一个摆好，与“玩具……得很整齐”相符。", "摔": "语义：“摔”会把东西弄坏，不能让玩具呈现整齐的状态。", "踢": "搭配：“踢”的对象多是球类，不能说把玩具踢得很整齐。"}, "sentence_index": 0, "correct_answer": "排列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下班后把房间排列得干干净净。", "explanation": "这里应该用〈整理〉。排列指把具体的东西一个挨一个摆成行或成形，收拾房间要用整理。"}, {"text": "他把乱七八糟的垃圾排列在门口，等着收走。", "explanation": "这里应该用〈堆放〉。排列要求整齐有序地摆开，随意堆在一起的垃圾不能说排列。"}, {"text": "他把这支舞排列了三遍，明天就要上台了。", "explanation": "这里应该用〈排练〉。排列指把东西按次序安放，练习表演要用排练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说把小石头吃在窗台上。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题，不能带“在窗台上”这样的处所。"}, {"text": "排列", "is_correct": true, "explanation": "“排列”可以带“把”字结构和处所补语“在窗台上”，句子成立。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不带处所补语，“把小石头唱在窗台上”不成立。"}], "explanations": {"吃": "语义：“吃”的对象是食物，不能说把小石头吃在窗台上。", "讨论": "搭配：“讨论”的对象是问题，不能带“在窗台上”这样的处所。", "排列": "“排列”可以带“把”字结构和处所补语“在窗台上”，句子成立。", "唱": "配价：“唱”不带处所补语，“把小石头唱在窗台上”不成立。"}, "sentence_index": 6, "correct_answer": "排列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把汤排列在碗里，很好看。", "explanation": "这里应该用〈盛〉。排列指把具体的人或物一个挨一个摆整齐，汤是液体，只能盛。"}, {"text": "他把盒子排列得很高，快要倒了。", "explanation": "这里应该用〈摞〉。排列是平铺成行或成形，往高处叠放要用摞。"}, {"text": "他把花瓣排列得满地都是。", "explanation": "这里应该用〈撒〉。排列要求整齐摆开，满地都是的花瓣是散落的，应说撒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把书架上的书排列很整齐。", "corrected_sentence": "他们把书架上的书排列得很整齐。", "error_description": "状态补语前缺少“得”。“排列”后接描述结果的“很整齐”，应说“排列得很整齐”，不能直接说“排列很整齐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员瓶子排列在架子上。", "corrected_sentence": "店员把瓶子排列在架子上。", "error_description": "“排列”带处所补语“在架子上”时，受事“瓶子”要用“把”提到动词前，省略“把”不成立。应说“把瓶子排列在架子上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
