INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按一定的次序或规律把事物依次安放。", "primary_collocate": null, "pronunciation": "pái liè", "ipa": "pʰaɪ˧˥ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "请把名字按字母顺序排列。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数字是按大小排列的。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们按高矮顺序排列。", "target_word": "排列", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "词典里的字按拼音排列。", "target_word": "排列", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师把我们的名字按成绩排列了。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图片按时间先后排列，很清楚。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把名单按年龄排列起来，你最小。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按颜色把铅笔排列好了。", "target_word": "排列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书按号码排列，找起来很方便。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些词应该按先后次序排列。", "target_word": "排列", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "排列了", "label": "体标"}, {"form": "排列着", "label": "体标"}, {"form": "排列过", "label": "体标"}, {"form": "排列组合", "label": "复合"}], "register": "中性", "sense_fingerprint": "按大小、先后、字母等次序或规律给事物排出顺序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是需要去除污垢的东西，不能洗名字。"}, {"text": "排列", "is_correct": true, "explanation": "“排列”表示按一定次序摆放，与“按字母顺序”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说吃名字。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮的对象是食物，把名字煮起来说不通。"}], "explanations": {"洗": "语义：“洗”的对象是需要去除污垢的东西，不能洗名字。", "排列": "“排列”表示按一定次序摆放，与“按字母顺序”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说吃名字。", "煮": "语义：煮的对象是食物，把名字煮起来说不通。"}, "sentence_index": 0, "correct_answer": "排列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们每天把这首歌排列一遍，准备明天上台。", "explanation": "这里应该用〈排练〉。排列是按次序安放事物，练习表演要用排练。"}, {"text": "老师把奖状按成绩排列给学生。", "explanation": "这里应该用〈发〉。排列是依次安放，不能把东西交给人，应说发给学生。"}, {"text": "仓库管理员排列了货物的数量。", "explanation": "这里应该用〈清点〉。数量要数出来，不能排列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”会使东西燃烧，名单不能按年龄烧起来。"}, {"text": "泡", "is_correct": false, "explanation": "搭配：“泡”的对象是需要浸泡的东西，不能泡名单。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”需要用火加热食物，把名单烤起来说不通。"}, {"text": "排列", "is_correct": true, "explanation": "“排列起来”表示把名单按年龄排好，与“你最小”的语境相符。"}], "explanations": {"烧": "语义：“烧”会使东西燃烧，名单不能按年龄烧起来。", "泡": "搭配：“泡”的对象是需要浸泡的东西，不能泡名单。", "烤": "语义：“烤”需要用火加热食物，把名单烤起来说不通。", "排列": "“排列起来”表示把名单按年龄排好，与“你最小”的语境相符。"}, "sentence_index": 6, "correct_answer": "排列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校排列了一场期末考试，全年级都要参加。", "explanation": "这里应该用〈举行〉。排列指按次序安放事物，考试要举行，不能排列。"}, {"text": "他排列了一下学生的人数。", "explanation": "这里应该用〈数〉。人数要数出来，排列针对的是实际的人或物，不能说排列人数。"}, {"text": "会计把这笔钱排列成一个总数。", "explanation": "这里应该用〈算出〉。总数要算出来，不能排列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些照片应该把时间先后排列。", "corrected_sentence": "这些照片应该按时间先后排列。", "error_description": "表示依据的“按”不能换成“把”。“按时间先后”是方式状语，“把时间先后排列”不成立，应说“按时间先后排列”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些卡片应该先后次序排列。", "corrected_sentence": "这些卡片应该按先后次序排列。", "error_description": "表示方式的“按”不能省略。“按先后次序”是方式状语，缺少“按”则“先后次序排列”不成立，应说“按先后次序排列”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
