INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90985, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "杀人是把别人弄死，这是很坏的事，是犯法的。", "primary_collocate": null, "pronunciation": "shā rén", "ipa": "ʂa˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "杀人是犯法的。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察抓住了杀人的坏人。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在中国，杀人要受到法律的处罚。", "target_word": "杀人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都不能杀人，这是法律规定的。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他杀人以后，跑到了外地。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的坏人为了钱杀人。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "杀人的人要坐牢。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩子不懂什么叫杀人。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没想过要杀人。", "target_word": "杀人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认自己杀人了，要坐很多年牢。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀人犯", "label": "复合"}, {"form": "杀人案", "label": "复合"}], "register": "中性", "sense_fingerprint": "把别人弄死，是违法的坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90985, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人（shā rén）：把别人弄死，是违法的坏事。"}, {"text": "商人", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（多了 -ng），意思是做买卖的人，与“杀人”不同。"}, {"text": "伤人", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（多了 -ng），意思是使别人受伤，不是致人死亡。"}, {"text": "生人", "is_correct": false, "explanation": "shēng 与 shā 韵母不同（-eng 与 -a），意思是陌生人。"}, {"text": "善人", "is_correct": false, "explanation": "shàn 与 shā 韵母不同（-an 与 -a），声调也不同（第四声），意思是好人。"}], "explanations": {"杀人": "杀人（shā rén）：把别人弄死，是违法的坏事。", "商人": "shāng 与 shā 韵母不同（多了 -ng），意思是做买卖的人，与“杀人”不同。", "伤人": "shāng 与 shā 韵母不同（多了 -ng），意思是使别人受伤，不是致人死亡。", "生人": "shēng 与 shā 韵母不同（-eng 与 -a），意思是陌生人。", "善人": "shàn 与 shā 韵母不同（-an 与 -a），声调也不同（第四声），意思是好人。"}, "sentence_index": null, "correct_answer": "杀人"}, "level_3": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人：把别人弄死，是违法的坏事，与“是犯法的”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是违法的事，与“是犯法的”矛盾。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭是日常小事，不犯法，句子说不通。"}, {"text": "犯规", "is_correct": false, "explanation": "搭配：“犯规”指违反比赛或规则，不用于法律上的违法行为，不能说“犯规是犯法的”。"}], "explanations": {"杀人": "杀人：把别人弄死，是违法的坏事，与“是犯法的”相符。", "唱歌": "语义：唱歌不是违法的事，与“是犯法的”矛盾。", "吃饭": "语义：吃饭是日常小事，不犯法，句子说不通。", "犯规": "搭配：“犯规”指违反比赛或规则，不用于法律上的违法行为，不能说“犯规是犯法的”。"}, "sentence_index": 0, "correct_answer": "杀人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天一早在院子里杀人，给鸡和鸭子放血，再拿去卖。", "explanation": "这里应该用〈杀鸡〉〈杀鸭〉。杀人指害死人，宰杀禽类要说“杀鸡”“杀鸭”，不能用“杀人”。"}, {"text": "渔夫在船上杀人，把鱼一条条处理好再卖。", "explanation": "这里应该用〈杀鱼〉。杀人指害死人，处理活鱼要说“杀鱼”，不能用“杀人”。"}, {"text": "我在厨房里杀人，把蟑螂一只只打死。", "explanation": "这里应该用〈杀虫〉。杀人指害死人，消灭蟑螂等害虫要说“杀虫”，不能用“杀人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人：把别人弄死，是要坐牢的犯罪行为，与“要坐牢”相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞不是犯罪，不会要坐牢，与“要坐牢”矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不违法，与“要坐牢”的后果无关，句子说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是犯罪行为，唱歌的人不会坐牢，句子说不通。"}], "explanations": {"杀人": "杀人：把别人弄死，是要坐牢的犯罪行为，与“要坐牢”相符。", "跳舞": "语义：跳舞不是犯罪，不会要坐牢，与“要坐牢”矛盾。", "睡觉": "语义：睡觉不违法，与“要坐牢”的后果无关，句子说不通。", "唱歌": "语义：唱歌不是犯罪行为，唱歌的人不会坐牢，句子说不通。"}, "sentence_index": 6, "correct_answer": "杀人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在山上杀人，把大树一棵棵砍倒了。", "explanation": "这里应该用〈砍伐〉。杀人指害死人，砍树要说“砍伐”，不能用“杀人”。"}, {"text": "等车的时候，我看报纸来杀人。", "explanation": "这里应该用〈杀时间〉。杀时间指打发时间，杀人是致人死亡，不能用来指消磨时间。"}, {"text": "我跟卖菜的老板杀人，少付了五块钱。", "explanation": "这里应该用〈杀价〉。杀价指讨价还价压低价格，杀人是致人死亡，与讨价无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被杀人了，警察正在调查。", "corrected_sentence": "他被人杀了，警察正在调查。", "error_description": "错误：“被杀人了”；正确：“被人杀了”。“杀人”是动宾结构，用在“被”字句中，施事“人”要放到动词前，应说“被人杀了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杀人了，然后逃跑了。", "corrected_sentence": "他把人杀了，然后逃跑了。", "error_description": "错误：“把杀人了”；正确：“把人杀了”。“把”字句中，宾语“人”要放在“把”后、动词前，不能把“杀人”整体放在“把”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
