INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "故意致人死亡。", "primary_collocate": null, "pronunciation": "shā rén", "ipa": "ʂa˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "法律规定，故意杀人要受到严厉的处罚。", "target_word": "杀人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意杀人，法院判了他二十年。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察查清了他杀人的原因。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杀人要负法律责任。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说自己没有杀人。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "证人说，他亲眼看见那个人杀人。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里常有杀人的情节。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他杀人后很害怕，不敢回家。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官问他为什么要杀人。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了钱杀人，是不能原谅的。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀人犯", "label": "复合"}, {"form": "杀人案", "label": "复合"}], "register": "中性", "sense_fingerprint": "故意使他人死亡，法律意义上的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人（shā rén）：故意使别人死亡。"}, {"text": "商人", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（多了 -ng），意思是做买卖的人，与“杀人”不同。"}, {"text": "伤人", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（多了 -ng），意思是使别人受伤。"}, {"text": "生人", "is_correct": false, "explanation": "shēng 与 shā 韵母不同（-eng 与 -a），意思是陌生人。"}, {"text": "善人", "is_correct": false, "explanation": "shàn 与 shā 韵母不同（-an 与 -a），声调也不同（第四声），意思是好人。"}], "explanations": {"杀人": "杀人（shā rén）：故意使别人死亡。", "商人": "shāng 与 shā 韵母不同（多了 -ng），意思是做买卖的人，与“杀人”不同。", "伤人": "shāng 与 shā 韵母不同（多了 -ng），意思是使别人受伤。", "生人": "shēng 与 shā 韵母不同（-eng 与 -a），意思是陌生人。", "善人": "shàn 与 shā 韵母不同（-an 与 -a），声调也不同（第四声），意思是好人。"}, "sentence_index": null, "correct_answer": "杀人"}, "level_3": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人：故意致人死亡，与“故意”搭配，是要受严厉处罚的行为。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是违法行为，“故意唱歌要受处罚”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是正常活动，不会受到严厉处罚，句子说不通。"}, {"text": "伤", "is_correct": false, "explanation": "配价：“伤”必须带宾语（如“伤人”），单独放在“故意”后语义不完整。"}], "explanations": {"杀人": "杀人：故意致人死亡，与“故意”搭配，是要受严厉处罚的行为。", "唱歌": "语义：唱歌不是违法行为，“故意唱歌要受处罚”说不通。", "散步": "语义：散步是正常活动，不会受到严厉处罚，句子说不通。", "伤": "配价：“伤”必须带宾语（如“伤人”），单独放在“故意”后语义不完整。"}, "sentence_index": 0, "correct_answer": "杀人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天一早在院子里杀人，给鸡和鸭子放血，再拿去卖。", "explanation": "这里应该用〈杀鸡〉〈杀鸭〉。杀人指害死人，宰杀禽类要说“杀鸡”“杀鸭”，不能用“杀人”。"}, {"text": "渔夫在船上杀人，把鱼一条条处理好再卖。", "explanation": "这里应该用〈杀鱼〉。杀人指害死人，处理活鱼要说“杀鱼”，不能用“杀人”。"}, {"text": "我在厨房里杀人，把蟑螂一只只打死。", "explanation": "这里应该用〈杀虫〉。杀人指害死人，消灭蟑螂等害虫要说“杀虫”，不能用“杀人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人：致人死亡，是常见的犯罪题材，与“情节”相符。"}, {"text": "缴费", "is_correct": false, "explanation": "语义：缴费是日常生活事务，不构成影视剧中的常见情节，句子意思不通。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印是办公操作，与“电影里常有……的情节”的语境不符。"}, {"text": "杀", "is_correct": false, "explanation": "配价：“杀”必须带宾语（如“杀人”），单独作“的情节”的定语时宾语缺失，句子不成立。"}], "explanations": {"杀人": "杀人：致人死亡，是常见的犯罪题材，与“情节”相符。", "缴费": "语义：缴费是日常生活事务，不构成影视剧中的常见情节，句子意思不通。", "打印": "语义：打印是办公操作，与“电影里常有……的情节”的语境不符。", "杀": "配价：“杀”必须带宾语（如“杀人”），单独作“的情节”的定语时宾语缺失，句子不成立。"}, "sentence_index": 6, "correct_answer": "杀人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在山上杀人，把大树一棵棵砍倒了。", "explanation": "这里应该用〈砍伐〉。杀人指害死人，砍树要说“砍伐”，不能用“杀人”。"}, {"text": "我在车站看杂志来杀人。", "explanation": "这里应该用〈杀时间〉。杀时间指打发时间，杀人是致人死亡，不能用来指消磨时间。"}, {"text": "这件衣服我跟老板杀人，便宜了十块。", "explanation": "这里应该用〈杀价〉。杀价指讨价还价压低价格，杀人是致人死亡，与讨价无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被杀人了，案件正在调查。", "corrected_sentence": "他被人杀了，案件正在调查。", "error_description": "错误：“被杀人了”；正确：“被人杀了”。“杀人”是动宾结构，用在“被”字句中，施事“人”要放到动词前，应说“被人杀了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杀人了，然后去自首了。", "corrected_sentence": "他把人杀了，然后去自首了。", "error_description": "错误：“把杀人了”；正确：“把人杀了”。“把”字句中，宾语“人”要放在“把”后、动词前，不能把“杀人”整体放在“把”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
