INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装有炸药、能爆炸的武器。", "primary_collocate": null, "pronunciation": "zhà dàn", "ipa": "tʂa˥˩ tan˥˩", "syllable_count": 2, "sentences": [{"text": "战争中，飞机向城市扔下了很多炸弹。", "target_word": "炸弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队用炸弹炸坏了那座桥。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵手里拿着一颗炸弹。", "target_word": "炸弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种炸弹是一种危险的武器。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争时期，人们都怕飞机上的炸弹。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂不能生产炸弹这样的武器。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工兵把地下的炸弹拆了。", "target_word": "炸弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，田里还有没爆炸的炸弹。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机上的炸弹炸中了仓库。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在博物馆看到了战争时用的炸弹。", "target_word": "炸弹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "枚", "label": "量词"}, {"form": "炸彈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "装有炸药的爆炸武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "炸弹", "is_correct": true, "explanation": "正确：飞机可以向城市扔下炸弹，符合战争的语境。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：飞机不会扔下很多小鸟，这个说法在语义上不通。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雪花不是飞机扔下的东西，和战争语境冲突。"}, {"text": "时光", "is_correct": false, "explanation": "搭配：时光是抽象的时间概念，不能被〈扔下〉，与战争语境不符。"}], "explanations": {"炸弹": "正确：飞机可以向城市扔下炸弹，符合战争的语境。", "小鸟": "语义：飞机不会扔下很多小鸟，这个说法在语义上不通。", "雪花": "语义：雪花不是飞机扔下的东西，和战争语境冲突。", "时光": "搭配：时光是抽象的时间概念，不能被〈扔下〉，与战争语境不符。"}, "sentence_index": 0, "correct_answer": "炸弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵把炸弹当成手电筒，照亮了黑暗的走廊。", "explanation": "这里把炸弹当成了手电筒。手电筒用来照明，炸弹会爆炸，不能用来照亮。"}, {"text": "士兵朝敌人射出了一颗炸弹。", "explanation": "这里应该用〈子弹〉。枪支射出的是子弹，炸弹要投放或扔下，不能说“射出”。"}, {"text": "他用炸弹在墙上画了一幅画。", "explanation": "这里把炸弹当成了画画的工具。画画用画笔和颜料，炸弹会爆炸，不能用来作画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炸弹", "is_correct": true, "explanation": "正确：工兵拆除的是埋在地下的炸弹，符合语境。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不可能埋在地下，也不能被拆。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是天气现象，不是埋在地下、可以拆的东西。"}, {"text": "烽火", "is_correct": false, "explanation": "语域：烽火是古代的书面词，指报警的火光，不能用“拆”，口语里也不这样说。"}], "explanations": {"炸弹": "正确：工兵拆除的是埋在地下的炸弹，符合语境。", "月亮": "语义：月亮不可能埋在地下，也不能被拆。", "闪电": "语义：闪电是天气现象，不是埋在地下、可以拆的东西。", "烽火": "语域：烽火是古代的书面词，指报警的火光，不能用“拆”，口语里也不这样说。"}, "sentence_index": 6, "correct_answer": "炸弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩把炸弹当成了气球，抱着它到处跑。", "explanation": "这里把炸弹当成了气球。气球可以玩耍、装饰，炸弹会爆炸，不能当成气球。"}, {"text": "他把炸弹当作枕头，每天晚上都靠着睡觉。", "explanation": "炸弹的用途是爆炸，不能当枕头，这里用错了“炸弹”的用途。"}, {"text": "他穿上一颗炸弹去上班了。", "explanation": "炸弹不能穿在身上，“穿”的对象应是衣服、鞋子等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员在仓库里找到了一张炸弹。", "corrected_sentence": "消防员在仓库里找到了一颗炸弹。", "error_description": "量词错误：炸弹不是平面物件，不能用量词〈张〉，应改为“一颗炸弹”（也可用〈枚〉〈个〉）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工兵把那张炸弹拆除了。", "corrected_sentence": "工兵把那颗炸弹拆除了。", "error_description": "量词错误：炸弹不是平面物件，不能用量词〈张〉，应改为“那颗炸弹”（也可用〈枚〉〈个〉）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
