INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90996, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "定期举办的、集中放映和评选影片的电影活动。", "primary_collocate": null, "pronunciation": "diàn yǐng jié", "ipa": "tiɛn⁵¹ iŋ²¹⁴ tɕiɛ³⁵", "syllable_count": 3, "sentences": [{"text": "这部电影在电影节上得了最佳影片奖。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节每年举办一次，今年是第十届。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多导演带着新电影来参加电影节。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节的评委正在选今年最好的影片。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电影院为电影节放了三十部新片。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员在电影节上拿到了最佳女演员奖。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节每年九月在这座城市举行。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的第一部电影去年参加了电影节。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节结束后，评委会公布了获奖名单。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想拍一部能进入电影节的电影。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "电影節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "定期举办、放映并评奖的电影活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电影节", "is_correct": true, "explanation": "正确答案：电影节（diàn yǐng jié），指定期举办、集中放映并评奖的电影活动。"}, {"text": "电影界", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是电影行业、影视圈。"}, {"text": "电影级", "is_correct": false, "explanation": "jí 与 jié 韵母不同，意思是达到电影水准的。"}, {"text": "电影季", "is_correct": false, "explanation": "jì 与 jié 韵母和声调都不同，意思是电影放映的季节或系列。"}, {"text": "电影街", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是放映或售卖电影的街道。"}], "explanations": {"电影节": "正确答案：电影节（diàn yǐng jié），指定期举办、集中放映并评奖的电影活动。", "电影界": "jiè（第四声）与 jié（第二声）声调不同，意思是电影行业、影视圈。", "电影级": "jí 与 jié 韵母不同，意思是达到电影水准的。", "电影季": "jì 与 jié 韵母和声调都不同，意思是电影放映的季节或系列。", "电影街": "jiē（第一声）与 jié（第二声）声调不同，意思是放映或售卖电影的街道。"}, "sentence_index": null, "correct_answer": "电影节"}, "level_3": {"options": [{"text": "动物园", "is_correct": false, "explanation": "语义：动物园是展示动物的地方，不会颁发最佳影片奖。"}, {"text": "电影节", "is_correct": true, "explanation": "正确：“在电影节上得了最佳影片奖”指在影片评选中获奖，与“最佳影片奖”相符。"}, {"text": "音乐会", "is_correct": false, "explanation": "搭配：“最佳影片奖”只在电影评选中颁发，不能在音乐会上得到。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是评选影片的场所，“得了最佳影片奖”无法在这里发生。"}], "explanations": {"动物园": "语义：动物园是展示动物的地方，不会颁发最佳影片奖。", "电影节": "正确：“在电影节上得了最佳影片奖”指在影片评选中获奖，与“最佳影片奖”相符。", "音乐会": "搭配：“最佳影片奖”只在电影评选中颁发，不能在音乐会上得到。", "厨房": "语义：厨房不是评选影片的场所，“得了最佳影片奖”无法在这里发生。"}, "sentence_index": 0, "correct_answer": "电影节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的电影节被摆在了桌子上。", "explanation": "这里应该用〈海报〉。电影节是定期举办的活动，不是可以摆在桌上的实物。"}, {"text": "这次电影节陈列着三百件古代陶器。", "explanation": "这里应该用〈展览〉。展览陈列实物，电影节放映影片，陶器不属于它的内容。"}, {"text": "这场电影节的球员都很努力。", "explanation": "这里应该用〈球赛〉。球员和比赛是球赛的内容，电影节没有球员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景观，不能“举行”。"}, {"text": "电影节", "is_correct": true, "explanation": "正确：“电影节每年九月在这座城市举行”指定期举办的影片活动，与“每年九月”相符。"}, {"text": "地震", "is_correct": false, "explanation": "搭配：“举行”接活动、仪式，不接地震，应说“发生”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是场所，不是能“举行”的活动，句中指的是每年一次的活动。"}], "explanations": {"河流": "语义：河流是自然景观，不能“举行”。", "电影节": "正确：“电影节每年九月在这座城市举行”指定期举办的影片活动，与“每年九月”相符。", "地震": "搭配：“举行”接活动、仪式，不接地震，应说“发生”。", "图书馆": "语义：图书馆是场所，不是能“举行”的活动，句中指的是每年一次的活动。"}, "sentence_index": 6, "correct_answer": "电影节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在城里参加了一座电影节。", "explanation": "这里量词用错了。“座”用于山、桥、楼等大型固定物，不能用来数电影节，应说〈届〉。"}, {"text": "我们在电影节上挂了号，排队等了两个小时。", "explanation": "这里应该用〈医院〉。挂号、排队看病是医院的事，电影节放映和评选影片，不能在电影节上挂号。"}, {"text": "电影节上老师讲了一节数学课。", "explanation": "这里应该用〈课堂〉。讲课、上课属于学校的教学活动，电影节放映和评选影片，不能说“讲了一节数学课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的电影节办很成功。", "corrected_sentence": "今年的电影节办得很成功。", "error_description": "补语前缺少“得”。“办”后接“很成功”要用“办得很成功”，不能说“办很成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年电影节上看了很多电影。", "corrected_sentence": "我去年在电影节上看了很多电影。", "error_description": "介词“在”漏掉了。地点“电影节上”前要加“在”，说“在电影节上看”，不能说“电影节上看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
