INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90997, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90997, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "为止是说到这里就结束了。", "primary_collocate": null, "pronunciation": "wéi zhǐ", "ipa": "wei˧˥ tʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天的课就上到这里为止。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的话到此为止，不说了。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事就讲到这里为止吧。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的比赛到这里为止，明天再来。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的介绍到这里为止，谢谢大家。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的会议就开到这里为止。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作先做到这里为止，我们去吃饭吧。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的作业写到这里为止，剩下的明天写。", "target_word": "为止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系到这里为止。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影放到这里为止，下面是休息时间。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "到此为止", "label": "复合"}], "register": "中性", "sense_fingerprint": "说到、做到这里就结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为止", "is_correct": true, "explanation": "正确：“为止”表示说到这里就结束，符合“今天的课就上到这里”的语境。"}, {"text": "呢", "is_correct": false, "explanation": "语义：呢表示疑问或动作还在继续，与“就上到这里”的结束语义不符。"}, {"text": "吗", "is_correct": false, "explanation": "语义：吗表示疑问，这句是陈述，不能用吗收尾。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“的”不能收尾这个陈述句，“上到这里的”说不完整。"}], "explanations": {"为止": "正确：“为止”表示说到这里就结束，符合“今天的课就上到这里”的语境。", "呢": "语义：呢表示疑问或动作还在继续，与“就上到这里”的结束语义不符。", "吗": "语义：吗表示疑问，这句是陈述，不能用吗收尾。", "的": "搭配：“的”不能收尾这个陈述句，“上到这里的”说不完整。"}, "sentence_index": 0, "correct_answer": "为止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从第三课为止学习。", "explanation": "这里应该用〈开始〉。“从……”表示起点，为止表示终点，不能用于起点。"}, {"text": "这场演出从十点为止，之后大家可以离开。", "explanation": "这里应该用〈开始〉。“从……”表示起点，“为止”表示终点，不能用于起点。"}, {"text": "他的话刚说了一半，就到此为止了，然后又接着说下去。", "explanation": "这里应该用〈停下〉。“到此为止”表示说到这里就结束，后面不能又接着说，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为止", "is_correct": true, "explanation": "正确：“为止”表示做到这里就停，符合“工作先做到这里”的语境。"}, {"text": "过", "is_correct": false, "explanation": "搭配：“过”接在动词后表示经历，不能收尾，“做到这里过”不完整。"}, {"text": "着", "is_correct": false, "explanation": "搭配：“着”表示持续状态，不能这样收尾，“做到这里着”不通顺。"}, {"text": "乎", "is_correct": false, "explanation": "语域：乎是文言语气词，口语句子里不自然。"}], "explanations": {"为止": "正确：“为止”表示做到这里就停，符合“工作先做到这里”的语境。", "过": "搭配：“过”接在动词后表示经历，不能收尾，“做到这里过”不完整。", "着": "搭配：“着”表示持续状态，不能这样收尾，“做到这里着”不通顺。", "乎": "语域：乎是文言语气词，口语句子里不自然。"}, "sentence_index": 6, "correct_answer": "为止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们从明天为止开始工作。", "explanation": "这里把“为止”误用为表示起点的词。“为止”只能表示终点，应说〈到……为止〉，不能和“从明天”这样的起点搭配。"}, {"text": "这家店每天营业，从早上为止。", "explanation": "这里把“为止”当成了表示起点的词。应表示起点的是〈开始〉，“为止”只能引出终点。"}, {"text": "我们明天玩到去年为止。", "explanation": "这里应该用〈到后天为止〉。“为止”引出的终点要在动作之后，“去年”已经过去，与“明天玩”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "讨论先进行这里为止吧。", "corrected_sentence": "讨论先进行到这里为止吧。", "error_description": "缺少“到”：此句应为“进行到这里为止吧”，“到……为止”的“到”引出终点，此处漏掉了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议开到这里为止着，大家先回家吧。", "corrected_sentence": "会议开到这里为止了，大家先回家吧。", "error_description": "体标错误：“为止”表示动作到此完成，应用“了”，不能用“着”（表示持续）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
