INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "到某个时间或地点结束。", "primary_collocate": null, "pronunciation": "wéi zhǐ", "ipa": "wei˧˥ tʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "到现在为止，我一次都没迟到。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到上个月为止，他已经学了一年中文。", "target_word": "为止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到昨天为止，这本书我看了一半。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到五点为止，学校的门都开着。", "target_word": "为止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到今天为止，我们见过三次面。", "target_word": "为止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路只修到前面的桥为止。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁只开到这个站为止。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到目前为止，我们还没有找到他。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报名到星期五为止，请不要太晚。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到去年为止，她一直住在北京。", "target_word": "为止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "到目前为止", "label": "复合"}], "register": "中性", "sense_fingerprint": "到某个时间或地点为界限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为止", "is_correct": true, "explanation": "正确：“到现在为止”表示到目前为止的时间界限，符合“我一次都没迟到”。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“到现在的”不完整，不能用来开头、收尾这个分句。"}, {"text": "吗", "is_correct": false, "explanation": "语义：吗表示疑问，与“我一次都没迟到”这样的陈述语气不符。"}, {"text": "而已", "is_correct": false, "explanation": "语义：而已表示“只是如此”，与表示时间界限的“到现在”意思不符。"}], "explanations": {"为止": "正确：“到现在为止”表示到目前为止的时间界限，符合“我一次都没迟到”。", "的": "搭配：“到现在的”不完整，不能用来开头、收尾这个分句。", "吗": "语义：吗表示疑问，与“我一次都没迟到”这样的陈述语气不符。", "而已": "语义：而已表示“只是如此”，与表示时间界限的“到现在”意思不符。"}, "sentence_index": 0, "correct_answer": "为止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从五点为止，学校的门都开着。", "explanation": "这里应该用〈开始〉。“从五点”表示起点，“为止”表示终点，二者不能同用。"}, {"text": "会议从两点为止，之后大家自由活动。", "explanation": "这里应该用〈开始〉。“从……”表示起点，“为止”表示终点，不能用于起点。"}, {"text": "学校的门从八点为止都开着。", "explanation": "这里把“为止”误用为起点标记。“从八点”已是起点，要和“为止”（终点）相接只能说“到八点为止”，这里起点与终点冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为止", "is_correct": true, "explanation": "正确：“只开到这个站为止”表示以这个站为终点，符合语境。"}, {"text": "过", "is_correct": false, "explanation": "搭配：“过”接在动词后表示经历，不能收尾，“开到这个站过”不完整。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”需要后接补语，这里句子不完整，“开到这个站得”不通。"}, {"text": "乎", "is_correct": false, "explanation": "语域：乎是文言语气词，口语句子里不自然。"}], "explanations": {"为止": "正确：“只开到这个站为止”表示以这个站为终点，符合语境。", "过": "搭配：“过”接在动词后表示经历，不能收尾，“开到这个站过”不完整。", "得": "搭配：“得”需要后接补语，这里句子不完整，“开到这个站得”不通。", "乎": "语域：乎是文言语气词，口语句子里不自然。"}, "sentence_index": 6, "correct_answer": "为止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从去年为止，她一直住在北京。", "explanation": "这里应该用〈开始〉。“从去年”表示起点，“为止”表示终点，不能同用。"}, {"text": "她一直住在北京，从去年为止。", "explanation": "这里把“为止”当成了表示起点的词。应表示起点的是〈开始〉，“为止”只能引出终点。"}, {"text": "我们明天学习到去年为止。", "explanation": "这里应该用〈到后天为止〉。“为止”引出的终点要在动作之后，“去年”已经过去，与“明天学习”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作干去年为止，他就辞职了。", "corrected_sentence": "这份工作干到去年为止，他就辞职了。", "error_description": "缺少“到”：应说“到去年为止”，此处“干去年为止”漏掉了引出终点的“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地铁运营从晚上十一点为止。", "corrected_sentence": "地铁运营到晚上十一点为止。", "error_description": "介词错误：“为止”前引出终点要用“到”，不能用“从”（表示起点）。应改为“到晚上十一点为止”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
