INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墙是房子四周立起来的，把里面和外面分开。", "primary_collocate": null, "pronunciation": "qiáng", "ipa": "tɕʰiɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我家的墙是白色的。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上挂着一张全家的照片。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面墙太薄了，隔壁说话我都听得到。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把画挂在墙上了。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在房子外面刷墙。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，厚墙能让屋里暖和一些。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在客厅的墙上画了一只猫。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子的墙还没有干，不能碰。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你站在墙边，别挡着门。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在墙上钉了一个钉子。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "堵", "label": "量词"}, {"form": "墙壁", "label": "复合词"}, {"form": "围墙", "label": "复合词"}, {"form": "牆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "房子的墙壁，分开屋里屋外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '171bfaad-7331-4fb7-ab07-ca6c9f52da30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙是房子四周立起来的墙壁，正是听到的词。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是钱。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng 声调不同，意思是枪。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng（第三声）与 qiáng 声调不同，意思是抢夺。"}, {"text": "情", "is_correct": false, "explanation": "qíng 与 qiáng 韵母不同（ing 与 ang），意思是感情。"}], "explanations": {"墙": "墙是房子四周立起来的墙壁，正是听到的词。", "钱": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是钱。", "枪": "qiāng（第一声）与 qiáng 声调不同，意思是枪。", "抢": "qiǎng（第三声）与 qiáng 声调不同，意思是抢夺。", "情": "qíng 与 qiáng 韵母不同（ing 与 ang），意思是感情。"}, "sentence_index": null, "correct_answer": "墙"}, "level_3": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙指房子四周的墙壁，可以是白色的。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无色的，不能说“白色的”。"}, {"text": "水", "is_correct": false, "explanation": "语义：水本身没有固定颜色，“我家的水是白色的”不成立。"}, {"text": "煤", "is_correct": false, "explanation": "语义：煤通常是黑色的，「我家的煤是白色的」不成立。"}], "explanations": {"墙": "墙指房子四周的墙壁，可以是白色的。", "空气": "语义：空气是无色的，不能说“白色的”。", "水": "语义：水本身没有固定颜色，“我家的水是白色的”不成立。", "煤": "语义：煤通常是黑色的，「我家的煤是白色的」不成立。"}, "sentence_index": 0, "correct_answer": "墙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子前面有一只墙。", "explanation": "这里应该用〈面〉。“只”用于动物等，墙用“面”或“堵”计量。"}, {"text": "他推开墙，走进了房间。", "explanation": "这里应该用〈门〉。墙是固定的，推不开；走进房间要推开的是门。"}, {"text": "客厅里立着一扇墙，挡住了窗户。", "explanation": "这里应该用〈面〉。“扇”用于门窗，墙要说“一面墙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91001, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙是房子四周立起来的墙壁，正是听到的词。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是前面。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiáng 声调不同，意思是呛住。"}, {"text": "腔", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng 声调不同，意思是腔调。"}], "explanations": {"墙": "墙是房子四周立起来的墙壁，正是听到的词。", "前": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是前面。", "呛": "qiàng（第四声）与 qiáng 声调不同，意思是呛住。", "腔": "qiāng（第一声）与 qiáng 声调不同，意思是腔调。"}, "sentence_index": null, "correct_answer": "墙"}, "level_3": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙上可以画画，“墙上”指客厅的墙面。"}, {"text": "天空", "is_correct": false, "explanation": "语义：客厅里没有天空，画不到天空上。"}, {"text": "云", "is_correct": false, "explanation": "语义：云飘在天上，客厅里不会有可以画的云。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“画”需要有形的表面，不能说在“声音”上画。"}], "explanations": {"墙": "墙上可以画画，“墙上”指客厅的墙面。", "天空": "语义：客厅里没有天空，画不到天空上。", "云": "语义：云飘在天上，客厅里不会有可以画的云。", "声音": "搭配：“画”需要有形的表面，不能说在“声音”上画。"}, "sentence_index": 6, "correct_answer": "墙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一根墙，很高。", "explanation": "这里应该用〈面〉。“根”用于细长的东西，墙不用“根”计量。"}, {"text": "院子里有一把墙，挡着风。", "explanation": "这里应该用〈面〉。“把”用于有柄的器具，墙不用“把”计量。"}, {"text": "我家有一张墙，刷成了白色。", "explanation": "这里应该用〈面〉。“张”用于纸、桌子等平面的东西，墙不说“一张墙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子有三只墙。", "corrected_sentence": "这间屋子有三面墙。", "error_description": "墙的量词应为“面”或“堵”，“只”用于动物等，“三只墙”属于量词误用，应改为“三面墙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙在挂着一幅地图。", "corrected_sentence": "墙上挂着一幅地图。", "error_description": "方位词“上”不能换成“在”。“墙在挂着一幅地图”是误用，方位词“上”表示位置，应写成“墙上挂着一幅地图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61d0e39e-4c35-4167-9e75-b01603a60506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
