INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人出生的日子，也指每年纪念的这一天。", "primary_collocate": null, "pronunciation": "shēng rì", "ipa": "ʂɤŋ˥ ɻʅ˥˩", "syllable_count": 2, "sentences": [{"text": "今天是我的生日，朋友送了我一份礼物。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的生日是几月几号？", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生日在十二月，天气很冷。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每年生日都回老家看妈妈。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是爸爸的生日，我想给他买蛋糕。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了妈妈的生日，所以很难过。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们每个人的生日是哪一天。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和姐姐的生日只差一天。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的生日快到了，我们准备去看她。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生日是三月八号，所以我记得很清楚。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个生日", "label": "量词"}, {"form": "生日蛋糕", "label": "复合"}, {"form": "生日礼物", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人出生的日期，或每年纪念的这一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生日", "is_correct": true, "explanation": "生日（shēng rì）：一个人出生的日子，也指每年纪念的这一天。"}, {"text": "生意", "is_correct": false, "explanation": "rì 与 yì 声母不同（r 与零声母），意思是做买卖。"}, {"text": "圣日", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，圣日指神圣的日子。"}, {"text": "胜日", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，胜日是书面语，指美好的日子。"}], "explanations": {"生日": "生日（shēng rì）：一个人出生的日子，也指每年纪念的这一天。", "生意": "rì 与 yì 声母不同（r 与零声母），意思是做买卖。", "圣日": "shèng（第四声）与 shēng（第一声）声调不同，圣日指神圣的日子。", "胜日": "shèng（第四声）与 shēng（第一声）声调不同，胜日是书面语，指美好的日子。"}, "sentence_index": null, "correct_answer": "生日"}, "level_3": {"options": [{"text": "生日", "is_correct": true, "explanation": "生日：一个人出生的日子，与“今天是我的……”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“今天是我的作业”说不通，作业不是日子。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“今天是”后只能接日期或节日等时间名词，“手机”不能与之搭配。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“今天是我的书包”说不通，书包是物品，不是日子。"}], "explanations": {"生日": "生日：一个人出生的日子，与“今天是我的……”相符。", "作业": "语义：“今天是我的作业”说不通，作业不是日子。", "手机": "搭配：“今天是”后只能接日期或节日等时间名词，“手机”不能与之搭配。", "书包": "语义：“今天是我的书包”说不通，书包是物品，不是日子。"}, "sentence_index": 0, "correct_answer": "生日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节是中国最重要的生日。", "explanation": "这里应该用〈节日〉。生日指个人出生的日子，春节是全民节日，不能说“生日”。"}, {"text": "合同的生日是五月一号，大家记得签字。", "explanation": "这里应该用〈签订日期〉。生日指个人出生或每年纪念的日子，合同的签订时间要说“签订日期”。"}, {"text": "他今年的生日是十八岁。", "explanation": "这里应该用〈年龄〉。生日指个人出生的日子，人的岁数要说“年龄”，不能用“生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生日", "is_correct": true, "explanation": "生日：一个人出生的日子，与“是哪一天”相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是日子，“每个人的名字是哪一天”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不能用“哪一天”来问。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：问身高要说“多高”，“身高”不与“是哪一天”搭配。"}], "explanations": {"生日": "生日：一个人出生的日子，与“是哪一天”相符。", "名字": "语义：名字不是日子，“每个人的名字是哪一天”说不通。", "体重": "语义：体重是身体的数值，不能用“哪一天”来问。", "身高": "搭配：问身高要说“多高”，“身高”不与“是哪一天”搭配。"}, "sentence_index": 6, "correct_answer": "生日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "航班的生日改到晚上八点，大家要注意。", "explanation": "这里应该用〈时间〉。生日指个人出生的日子，航班的时刻要说“时间”，不能用“生日”。"}, {"text": "暑假是学生最喜欢的生日。", "explanation": "这里应该用〈假期〉。生日指出生的日子，不能指一段放假的时间。"}, {"text": "会议的生日定在十号。", "explanation": "这里应该用〈日期〉。生日是某人出生的日子，会议的时间安排要说“日期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起给奶奶过了一只生日。", "corrected_sentence": "我们一起给奶奶过了一个生日。", "error_description": "错误：“一只生日”；正确：“一个生日”。“生日”作名词，量词用“个”，“只”一般用于动物等，不能用于“生日”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祝你一个生日快乐！", "corrected_sentence": "祝你生日快乐！", "error_description": "错误：“一个生日快乐”；正确：“生日快乐”。祝贺语中“生日”前不加数量词“一个”，直接说“生日快乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
