INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91016, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "使人摸不透、难以理解的。", "primary_collocate": null, "pronunciation": "shén mì", "ipa": "ʂən˧˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "这个人很神秘，没有人知道他的来历。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的笑容很神秘，让人摸不透。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人的身份非常神秘。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话的方式很神秘，我听不懂。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事太神秘了，谁也解释不了。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他神秘地笑了笑，什么也没说。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家发现了一个神秘的信号。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的过去很神秘，朋友们也不清楚。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位画家的作品风格神秘，很难看懂。", "target_word": "神秘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个神秘的电话打来，他吓了一跳。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "神秘感", "label": "复合"}, {"form": "神秘兮兮", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事让人摸不透、难以理解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91016, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神秘", "is_correct": true, "explanation": "正确答案。神秘（shén mì）指让人摸不透、难以理解。"}, {"text": "沉迷", "is_correct": false, "explanation": "chén（第二声）与 shén 声母不同（ch 与 sh），第二个音节 mí 声调也不同，沉迷指迷恋某事。"}, {"text": "慎密", "is_correct": false, "explanation": "shèn（第四声）与 shén（第二声）声调不同，慎密指谨慎周密。"}, {"text": "神迷", "is_correct": false, "explanation": "第二个音节 mí（第二声）与 mì（第四声）声调不同，神迷指着迷。"}, {"text": "甚密", "is_correct": false, "explanation": "shèn（第四声）与 shén（第二声）声调不同，甚密指关系十分亲近。"}], "explanations": {"神秘": "正确答案。神秘（shén mì）指让人摸不透、难以理解。", "沉迷": "chén（第二声）与 shén 声母不同（ch 与 sh），第二个音节 mí 声调也不同，沉迷指迷恋某事。", "慎密": "shèn（第四声）与 shén（第二声）声调不同，慎密指谨慎周密。", "神迷": "第二个音节 mí（第二声）与 mì（第四声）声调不同，神迷指着迷。", "甚密": "shèn（第四声）与 shén（第二声）声调不同，甚密指关系十分亲近。"}, "sentence_index": null, "correct_answer": "神秘"}, "level_3": {"options": [{"text": "神秘", "is_correct": true, "explanation": "神秘指让人摸不透，与“没有人知道他的来历”相符。"}, {"text": "透明", "is_correct": false, "explanation": "语义：透明指清楚可见，与“没有人知道他的来历”相矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多形容光线或眼睛，一般不说人很明亮。"}, {"text": "公开", "is_correct": false, "explanation": "语义：公开指不隐瞒，与“没有人知道他的来历”相矛盾。"}], "explanations": {"神秘": "神秘指让人摸不透，与“没有人知道他的来历”相符。", "透明": "语义：透明指清楚可见，与“没有人知道他的来历”相矛盾。", "明亮": "搭配：“明亮”多形容光线或眼睛，一般不说人很明亮。", "公开": "语义：公开指不隐瞒，与“没有人知道他的来历”相矛盾。"}, "sentence_index": 0, "correct_answer": "神秘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣很神秘，穿起来特别暖和。", "explanation": "这里应该用〈暖和〉。神秘指让人摸不透，不能形容衣服的保暖效果；衣服保暖要说暖和。"}, {"text": "这道数学题很神秘，同学们很快就做完了。", "explanation": "这里应该用〈简单〉。神秘指让人摸不透，题目不难时应说简单，不说神秘。"}, {"text": "他的名字很神秘，全校的人都知道。", "explanation": "这里应该用〈有名〉。神秘指让人摸不透，名字人人都知道时要说有名，不说神秘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神秘", "is_correct": true, "explanation": "神秘指让人摸不透，与“科学家发现了一个…的信号”相符。"}, {"text": "高矮", "is_correct": false, "explanation": "语义：“高矮”描述身高或个头，信号没有高矮，说不通。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的言谈，不能用来形容信号。"}, {"text": "胖乎乎", "is_correct": false, "explanation": "语义：“胖乎乎”形容人或动物的样子，不能用来形容信号，说不通。"}], "explanations": {"神秘": "神秘指让人摸不透，与“科学家发现了一个…的信号”相符。", "高矮": "语义：“高矮”描述身高或个头，信号没有高矮，说不通。", "幽默": "语义：“幽默”形容人的言谈，不能用来形容信号。", "胖乎乎": "语义：“胖乎乎”形容人或动物的样子，不能用来形容信号，说不通。"}, "sentence_index": 6, "correct_answer": "神秘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种饼干很神秘，吃起来很脆。", "explanation": "这里应该用〈脆〉。神秘指让人摸不透，不能形容口感；饼干松脆要说脆。"}, {"text": "这杯咖啡很神秘，喝起来很苦。", "explanation": "这里应该用〈苦〉。神秘指让人摸不透，不能用来形容味道，味道苦要说苦。"}, {"text": "孩子们在院子里玩得很神秘，笑个不停。", "explanation": "这里应该用〈开心〉。神秘用于让人摸不透的事物，不能形容玩耍时的愉快心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事神秘很得，没人说得清。", "corrected_sentence": "这件事神秘得很，没人说得清。", "error_description": "“神秘得很”是程度补语结构，“神秘很得”是语序错误，母语者会立即察觉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛屿的历史很神秘地，至今没人弄清楚。", "corrected_sentence": "这座岛屿的历史很神秘，至今没人弄清楚。", "error_description": "错误：“很神秘地”；正确：“很神秘”。“地”是状语标志，后面要接动词，“历史很神秘地”作谓语不完整，应去掉“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
