INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家机关颁布的具有法律效力的命令、规章的总称。", "primary_collocate": null, "pronunciation": "fǎ lìng", "ipa": "fa˨˩˦ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "国务院颁布了新的法令。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新法令自下月起施行。", "target_word": "法令", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府依照法令处理这件事。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各级机关都必须执行国家法令。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "违反法令的企业会受到处罚。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项法令对环境保护作了明确规定。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公民应当遵守国家的法律和法令。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法令发布以后，全国各地都要执行。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是研究古代法令的学者。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国务院公布了有关交通的法令。", "target_word": "法令", "complexity_tier": "T3", "furigana": "fǎ lìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项法令", "label": "量词"}, {"form": "一条法令", "label": "量词"}], "register": "书面", "sense_fingerprint": "国家机关颁布的有法律效力的命令和规章的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "搭配：“颁布”用于法令、规章，不能用于食品。"}, {"text": "法令", "is_correct": true, "explanation": "“法令”是国家机关颁布的规范，与“国务院颁布了新的”相符。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：小说是出版或发表的，不能说颁布小说。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是国家机关颁布的东西，句子说不通。"}], "explanations": {"饼干": "搭配：“颁布”用于法令、规章，不能用于食品。", "法令": "“法令”是国家机关颁布的规范，与“国务院颁布了新的”相符。", "小说": "搭配：小说是出版或发表的，不能说颁布小说。", "花园": "语义：花园不是国家机关颁布的东西，句子说不通。"}, "sentence_index": 0, "correct_answer": "法令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校制定了一项法令，要求学生按时到校。", "explanation": "这里应该用〈章程〉。法令由国家机关颁布，学校或社团的规章要用章程。"}, {"text": "老师布置的法令，学生要认真完成。", "explanation": "这里应该用〈作业〉。法令是颁布的规定，不能布置或完成，应说作业。"}, {"text": "牛顿发现了一项法令，解释了物体运动。", "explanation": "这里应该用〈定律〉。法令是国家机关颁布的规章，自然界的规律要用定律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "搭配：“遵守”的宾语应是法律、规定，不能说遵守歌曲。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能要求人遵守。"}, {"text": "法令", "is_correct": true, "explanation": "“法令”是国家颁布、公民应当遵守的规范，与“遵守国家的法律和”相符。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不是需要遵守的规范，“遵守笑话”说不通。"}], "explanations": {"歌曲": "搭配：“遵守”的宾语应是法律、规定，不能说遵守歌曲。", "天气": "语义：天气是自然现象，不能要求人遵守。", "法令": "“法令”是国家颁布、公民应当遵守的规范，与“遵守国家的法律和”相符。", "笑话": "语义：笑话不是需要遵守的规范，“遵守笑话”说不通。"}, "sentence_index": 6, "correct_answer": "法令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歌手发布了一项法令，大家都在听。", "explanation": "这里应该用〈新歌〉。歌手发布的是歌曲，不是国家机关颁布的法令。"}, {"text": "校长做了一项法令，全校都要听。", "explanation": "这里应该用〈报告〉。法令是颁布的，不是做出来的；做出来的汇报要用报告。"}, {"text": "国务院发出了一项法令，通知各单位放假。", "explanation": "这里应该用〈通知〉。法令是具有法律效力的命令、规章，单纯告知事项要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国务院这次颁布了一把法令。", "corrected_sentence": "国务院这次颁布了一项法令。", "error_description": "“法令”的量词应为“项”或“条”。“把”用于有柄的东西，不能用于法令，应说“一项法令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国务院发布了一幅法令。", "corrected_sentence": "国务院发布了一项法令。", "error_description": "“法令”的量词应为“项”或“条”。“幅”用于字画、图片，不能用于法令，应说“一项法令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
