INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大海旁边有沙子的地方。", "primary_collocate": null, "pronunciation": "hǎi tān", "ipa": "xaɪ˨˩˦ tʰan˥", "syllable_count": 2, "sentences": [{"text": "我想带孩子去海滩玩。", "target_word": "海滩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海滩上到处都是沙子。", "target_word": "海滩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天我们在海滩看日落。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海滩离我家不远，坐车二十分钟。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在海滩上踢足球。", "target_word": "海滩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个海滩夏天人特别多。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在海滩上画了一条大鱼。", "target_word": "海滩", "complexity_tier": "T3", "furigana": "wǒ zài hǎi tān shàng huà le yī tiáo dà yú。", "sentence_source": "generated"}, {"text": "海滩的水很浅，小孩可以玩。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，海滩上没有人。", "target_word": "海滩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在海滩上找到了一个小贝壳。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片海滩", "label": "量词"}, {"form": "海灘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大海旁边有沙子的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海滩", "is_correct": true, "explanation": "正确：海滩是可以去玩的沙地，符合“带孩子去……玩”的语境。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不是带孩子去玩的地方。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“去……玩”的地点一般是游乐场所，不能和“图书馆”搭配。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，与“去……玩”不相符。"}], "explanations": {"海滩": "正确：海滩是可以去玩的沙地，符合“带孩子去……玩”的语境。", "医院": "语义：医院是看病的地方，不是带孩子去玩的地方。", "图书馆": "搭配：“去……玩”的地点一般是游乐场所，不能和“图书馆”搭配。", "教室": "语义：教室是上课的地方，与“去……玩”不相符。"}, "sentence_index": 0, "correct_answer": "海滩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在海滩里游泳。", "explanation": "这里应该用〈海洋〉。游泳要在水里进行，海滩是岸边的沙地，不能说“在海滩里游泳”。"}, {"text": "这只海滩很长。", "explanation": "这里应该用〈片〉。海滩是一大片沙地，量词要用“片”，不用“只”。"}, {"text": "海滩拍打着海岸。", "explanation": "这里应该用〈海浪〉。拍打是海浪的动作，海滩是沙地，不能拍打海岸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海滩", "is_correct": true, "explanation": "正确：海滩是平坦的沙地，可以在上面画画，符合“在……上画了一条大鱼”的语境。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见、摸不着，不能作为画画的平面，不能说“在声音上画了一条大鱼”。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：方位词“上”不和“房间”搭配，要说“房间里”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能作为画画的平面。"}], "explanations": {"海滩": "正确：海滩是平坦的沙地，可以在上面画画，符合“在……上画了一条大鱼”的语境。", "声音": "语义：声音看不见、摸不着，不能作为画画的平面，不能说“在声音上画了一条大鱼”。", "房间": "搭配：方位词“上”不和“房间”搭配，要说“房间里”。", "空气": "语义：空气是看不见的气体，不能作为画画的平面。"}, "sentence_index": 6, "correct_answer": "海滩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船在海滩上航行。", "explanation": "这里应该用〈海上〉。船要在水面上航行，海滩是沙地，不能说“在海滩上航行”。"}, {"text": "这颗海滩很大。", "explanation": "这里应该用〈片〉。海滩是一大片沙地，量词要用“片”，“颗”用于小而圆的东西。"}, {"text": "她把海滩装进口袋里。", "explanation": "这里应该用〈沙子〉。沙子可以装进口袋，海滩是一大片地方，不能装进口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一只海滩上捡贝壳。", "corrected_sentence": "我们在一片海滩上捡贝壳。", "error_description": "错误：量词“只”不能用于“海滩”，应用“片”；正确为“一片海滩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚的时候，我们在一只海滩边散步。", "corrected_sentence": "傍晚的时候，我们在海滩边散步。", "error_description": "错误：“海滩”前多了“一只”，量词“只”不能用于“海滩”；正确为“在海滩边散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
