INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91034, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无拘无束；安闲舒适。", "primary_collocate": null, "pronunciation": "zì zài", "ipa": "tsɿ˥˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟在天空中自在地飞。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在树下喝茶，十分自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里没有人打扰，大家都很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了工作，每天都自在多了。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老朋友面前，我说话很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "躺在床上听音乐，多么自在！", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过着自在的日子。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚来新学校，他还不太自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在院子里睡得很自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期里，我们过得轻松又自在。", "target_word": "自在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自自在在", "label": "重叠"}], "register": "中性", "sense_fingerprint": "自在：无拘无束，安闲舒适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47ca02c-da77-46cf-8e0b-0a9f8df1a1a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自在", "is_correct": true, "explanation": "自在：无拘无束，安闲舒适。"}, {"text": "志在", "is_correct": false, "explanation": "志在的声母是 zh，自在的声母是 z（zhì 与 zì），意思是立志、以……为目标。"}, {"text": "只在", "is_correct": false, "explanation": "只在的声母是 zh，声调也不同（zhǐ 与 zì），意思是仅仅在。"}, {"text": "自带", "is_correct": false, "explanation": "自带的第二音节声母是 d（dài 与 zài），意思是自己携带。"}], "explanations": {"自在": "自在：无拘无束，安闲舒适。", "志在": "志在的声母是 zh，自在的声母是 z（zhì 与 zì），意思是立志、以……为目标。", "只在": "只在的声母是 zh，声调也不同（zhǐ 与 zì），意思是仅仅在。", "自带": "自带的第二音节声母是 d（dài 与 zài），意思是自己携带。"}, "sentence_index": null, "correct_answer": "自在"}, "level_3": {"options": [{"text": "自在", "is_correct": true, "explanation": "自在：“小鸟在天空中自在地飞”表示无拘无束地飞翔，符合语境。"}, {"text": "拘谨", "is_correct": false, "explanation": "语义：拘谨指放不开，与小鸟在天空中自由飞翔的画面相反。"}, {"text": "呆板", "is_correct": false, "explanation": "搭配：呆板多形容表情、姿态，不说鸟飞得呆板。"}, {"text": "僵硬", "is_correct": false, "explanation": "语义：僵硬指身体或动作不灵活，与轻快的飞翔不符。"}], "explanations": {"自在": "自在：“小鸟在天空中自在地飞”表示无拘无束地飞翔，符合语境。", "拘谨": "语义：拘谨指放不开，与小鸟在天空中自由飞翔的画面相反。", "呆板": "搭配：呆板多形容表情、姿态，不说鸟飞得呆板。", "僵硬": "语义：僵硬指身体或动作不灵活，与轻快的飞翔不符。"}, "sentence_index": 0, "correct_answer": "自在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他换了工作，每天很自在，连饭都顾不上吃。", "explanation": "这里应该用〈忙碌〉。自在指安闲舒适，与“连饭都顾不上吃”的状态不符；形容忙碌要用〈忙碌〉。"}, {"text": "他第一次坐飞机，自在得直哆嗦。", "explanation": "这里应该用〈害怕〉。自在表示安闲舒适，与发抖的状态相矛盾；心里害怕要用〈害怕〉。"}, {"text": "他换了工作，却总是自在地抱怨。", "explanation": "这里应该用〈不满〉。自在表示安闲舒适、不拘束；抱怨是心里不满，要用〈不满〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自在", "is_correct": true, "explanation": "自在：“她过着自在的日子”表示生活无拘无束、心里舒服。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：拥挤多说地方或人群，不说“拥挤的日子”。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：狭窄多形容空间或道路，“狭窄的日子”不通。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音，与日子的状态无关。"}], "explanations": {"自在": "自在：“她过着自在的日子”表示生活无拘无束、心里舒服。", "拥挤": "搭配：拥挤多说地方或人群，不说“拥挤的日子”。", "狭窄": "搭配：狭窄多形容空间或道路，“狭窄的日子”不通。", "清脆": "语义：清脆形容声音，与日子的状态无关。"}, "sentence_index": 6, "correct_answer": "自在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位厨师一上手就自在地把锅打翻了。", "explanation": "这里应该用〈慌忙〉。自在表示安闲舒适，与打翻锅的意外相矛盾；慌乱地做事要用〈慌忙〉。"}, {"text": "他一出门就自在地迷了路。", "explanation": "这里应该用〈慌张〉。自在表示安闲舒适，迷路时的心境要用〈慌张〉。"}, {"text": "孩子一看到生人，就自在地躲到了妈妈身后。", "explanation": "这里应该用〈胆怯〉。躲到妈妈身后是因为胆怯，自在表示安闲舒适，不能用来形容这种反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人在公园里散步，走地很自在。", "corrected_sentence": "老人在公园里散步，走得很自在。", "error_description": "“走”后面的补语要用“得”，不能用“地”；“地”用在动词前作状语。错误形式是“走地”，正确形式是“走得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末的时候，我在家看书，觉得很很自在。", "corrected_sentence": "周末的时候，我在家看书，觉得很自在。", "error_description": "程度副词“很”只能用一次，放在形容词“自在”前面，不能重复。错误是“很很自在”，正确是“很自在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
