INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91046, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于车辆。", "primary_collocate": null, "pronunciation": "liàng", "ipa": "ljɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这辆车是我爸爸的。", "target_word": "辆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每天有很多辆公共汽车经过这里。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校门口停了十辆校车。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一辆大货车在路边坏了。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想租一辆车去海边。", "target_word": "辆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他骑着一辆旧自行车去上班。", "target_word": "辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面那辆出租车开得太慢了。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里新来了四辆卡车。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐的那辆公共汽车很挤。", "target_word": "辆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸把两辆车洗得很干净。", "target_word": "辆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "輛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词，用于计数各类车辆，如一辆卡车、十辆校车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辆", "is_correct": true, "explanation": "正确：“辆”（liàng）是数车辆的量词。"}, {"text": "两", "is_correct": false, "explanation": "“两”（liǎng，第三声）与“辆”（liàng，第四声）声调不同，意思是数量“两”。"}, {"text": "粮", "is_correct": false, "explanation": "“粮”（liáng，第二声）与“辆”声调不同，意思是粮食。"}, {"text": "浪", "is_correct": false, "explanation": "“浪”（làng）与“辆”只差韵母中间的 i，意思是波浪。"}], "explanations": {"辆": "正确：“辆”（liàng）是数车辆的量词。", "两": "“两”（liǎng，第三声）与“辆”（liàng，第四声）声调不同，意思是数量“两”。", "粮": "“粮”（liáng，第二声）与“辆”声调不同，意思是粮食。", "浪": "“浪”（làng）与“辆”只差韵母中间的 i，意思是波浪。"}, "sentence_index": null, "correct_answer": "辆"}, "level_3": {"options": [{"text": "辆", "is_correct": true, "explanation": "“辆”是车的量词，与“这辆车”搭配，正确。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于树木、植物，不能用来数车。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、建筑等大型固定的东西，车不属于这一类。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书籍、册子，不能用来数车。"}], "explanations": {"辆": "“辆”是车的量词，与“这辆车”搭配，正确。", "棵": "搭配：“棵”用于树木、植物，不能用来数车。", "座": "语义：“座”指山、建筑等大型固定的东西，车不属于这一类。", "本": "搭配：“本”用于书籍、册子，不能用来数车。"}, "sentence_index": 0, "correct_answer": "辆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里种着一辆大树。", "explanation": "这里应该用〈棵〉。“辆”只用于车，树木要用“棵”。"}, {"text": "他买了一辆新衣服。", "explanation": "这里应该用〈件〉。“辆”只用于车，衣服要用“件”。"}, {"text": "屋里放着一辆旧桌子。", "explanation": "这里应该用〈张〉。“辆”只用于车，桌子要用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91046, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "辆", "is_correct": true, "explanation": "正确：“辆”（liàng）是数车辆的量词。"}, {"text": "梁", "is_correct": false, "explanation": "“梁”（liáng，第二声）与“辆”声调不同，意思是房屋的横木。"}, {"text": "良", "is_correct": false, "explanation": "“良”（liáng，第二声）与“辆”声调不同，意思是好。"}, {"text": "酿", "is_correct": false, "explanation": "“酿”（niàng）与“辆”只差声母 n 和 l，意思是酿造。"}], "explanations": {"辆": "正确：“辆”（liàng）是数车辆的量词。", "梁": "“梁”（liáng，第二声）与“辆”声调不同，意思是房屋的横木。", "良": "“良”（liáng，第二声）与“辆”声调不同，意思是好。", "酿": "“酿”（niàng）与“辆”只差声母 n 和 l，意思是酿造。"}, "sentence_index": null, "correct_answer": "辆"}, "level_3": {"options": [{"text": "辆", "is_correct": true, "explanation": "“辆”是车的量词，与“前面那辆出租车”搭配，正确。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物，不能用来数出租车。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”用于花朵、云彩等，不能用于出租车。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”指有柄的物件，出租车不属于这一类。"}], "explanations": {"辆": "“辆”是车的量词，与“前面那辆出租车”搭配，正确。", "只": "搭配：“只”用于动物，不能用来数出租车。", "朵": "搭配：“朵”用于花朵、云彩等，不能用于出租车。", "把": "语义：“把”指有柄的物件，出租车不属于这一类。"}, "sentence_index": 6, "correct_answer": "辆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家养着一辆小猫。", "explanation": "这里应该用〈只〉。“辆”只用于车，猫要用“只”。"}, {"text": "她手里拿着一辆笔。", "explanation": "这里应该用〈支〉。“辆”只用于车，笔要用“支”。"}, {"text": "他刚买了一辆房子。", "explanation": "这里应该用〈套〉。“辆”只用于车，房子要用“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家车库里停着二辆自行车。", "corrected_sentence": "他家车库里停着两辆自行车。", "error_description": "数词“二”不能直接与“辆”搭配，应说“两辆”，不说“二辆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那个辆旧车卖掉了。", "corrected_sentence": "他把那辆旧车卖掉了。", "error_description": "量词重复：“辆”前面不能再加“个”，应说“那辆旧车”，不说“那个辆旧车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
