INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91051, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "随便是想怎么做就怎么做，不用管那么多。", "primary_collocate": null, "pronunciation": "suí biàn", "ipa": "suei˧˥ pian˥˩", "syllable_count": 2, "sentences": [{"text": "这里的椅子你可以随便坐。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想吃什么，你就随便吃吧。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上的书，你随便看。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别客气，东西随便拿。", "target_word": "随便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些笔随便用，不用问我。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你随便选一个，哪个都可以。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们可以在这里随便玩。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，大家有问题可以随便问。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单在这儿，你随便点。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末去哪儿玩，你随便定就行。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "随随便便", "label": "重叠"}, {"form": "隨便", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想怎么做就怎么做，不受限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随便", "is_correct": true, "explanation": "“随便”表示想怎么坐就怎么坐，不受限制，正确。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”说做事的态度专注，与“可以……坐”的随意语境不符。"}, {"text": "讲究", "is_correct": false, "explanation": "搭配：“讲究”说挑剔、精致，不用来形容坐的方式。"}, {"text": "正式", "is_correct": false, "explanation": "语域：“正式”指庄重的场合，与随便坐的语境相反。"}], "explanations": {"随便": "“随便”表示想怎么坐就怎么坐，不受限制，正确。", "认真": "语义：“认真”说做事的态度专注，与“可以……坐”的随意语境不符。", "讲究": "搭配：“讲究”说挑剔、精致，不用来形容坐的方式。", "正式": "语域：“正式”指庄重的场合，与随便坐的语境相反。"}, "sentence_index": 0, "correct_answer": "随便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他签合同时很随便，每一条条款都逐字核对。", "explanation": "这里应该用〈谨慎〉。随便表示想怎么做就怎么做，与“每一条条款都逐字核对”矛盾；签合同要说“谨慎”。"}, {"text": "他对安全问题很随便，每天都要检查三遍。", "explanation": "这里应该用〈小心〉。随便表示想怎么做就怎么做，与“每天都要检查三遍”矛盾；对安全问题要说“小心”。"}, {"text": "他做实验很随便，从不马虎。", "explanation": "这里应该用〈认真〉。随便表示不计较，与“从不马虎”矛盾；做实验要说“认真”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随便", "is_correct": true, "explanation": "“随便”表示想怎么玩就怎么玩，不受限制，正确。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”说排列有序，不说玩耍的方式。"}, {"text": "严格", "is_correct": false, "explanation": "搭配：“严格”说规定或要求，不用来形容玩。"}, {"text": "郑重", "is_correct": false, "explanation": "语域：“郑重”带有庄重色彩，与孩子随意玩耍的场景不合。"}], "explanations": {"随便": "“随便”表示想怎么玩就怎么玩，不受限制，正确。", "整齐": "语义：“整齐”说排列有序，不说玩耍的方式。", "严格": "搭配：“严格”说规定或要求，不用来形容玩。", "郑重": "语域：“郑重”带有庄重色彩，与孩子随意玩耍的场景不合。"}, "sentence_index": 6, "correct_answer": "随便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的操作规程很随便，每一步都要经过三人核对。", "explanation": "这里应该用〈严格〉。随便表示想怎么做就怎么做，与“每一步都要经过三人核对”矛盾；规程的要求要说“严格”。"}, {"text": "他签名字很随便，每一笔都写得工工整整。", "explanation": "这里应该用〈认真〉。随便表示想怎么做就怎么做，与“每一笔都写得工工整整”矛盾；写字要说“认真”。"}, {"text": "这场入学考试很随便，考生们都紧张得整晚没睡。", "explanation": "这里应该用〈严肃〉。随便表示想怎么做就怎么做，与“考生们都紧张得整晚没睡”的郑重场面矛盾；考试的态度要说“严肃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些笔你随便便用，别客气。", "corrected_sentence": "这些笔你随便用，别客气。", "error_description": "“随便”不能重叠成“随便便”，多出的“便”应删去，说“随便用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事随便便便，从不考虑别人。", "corrected_sentence": "他做事随随便便，从不考虑别人。", "error_description": "“随便”的重叠形式是“随随便便”（AABB），不说“随便便便”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拘束", "is_correct": true, "explanation": "“拘束”指言行受约束，与“随便”的“不拘束”意义相反。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”说待人的热烈态度，与“不拘束”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”说智力高，与“随便”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”说平和、不吵闹，与“不拘束”没有反义关系。"}], "correct_answer": "拘束", "explanations": {"拘束": "“拘束”指言行受约束，与“随便”的“不拘束”意义相反。", "热情": "“热情”说待人的热烈态度，与“不拘束”没有反义关系。", "聪明": "“聪明”说智力高，与“随便”没有反义关系。", "安静": "“安静”说平和、不吵闹，与“不拘束”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拘束", "is_correct": true, "explanation": "“拘束”指言行受约束，与“随便”的“不拘束”意义相反。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”说明白、不模糊，与“不拘束”没有反义关系。"}, {"text": "公平", "is_correct": false, "explanation": "“公平”说对待一视同仁，与“不拘束”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”说心情愉快，与“不拘束”没有反义关系。"}], "correct_answer": "拘束", "explanations": {"拘束": "“拘束”指言行受约束，与“随便”的“不拘束”意义相反。", "清楚": "“清楚”说明白、不模糊，与“不拘束”没有反义关系。", "公平": "“公平”说对待一视同仁，与“不拘束”没有反义关系。", "高兴": "“高兴”说心情愉快，与“不拘束”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不加限制；不拘束；任意。", "primary_collocate": null, "pronunciation": "suí biàn", "ipa": "suei˧˥ pian˥˩", "syllable_count": 2, "sentences": [{"text": "他穿得很随便。", "target_word": "随便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在家里，我们说话很随便。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间不用客气，随便一点。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是一个很随便的人，不太在意小事。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆很随便，穿拖鞋也可以进去。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次见面很随便，大家边吃边聊。", "target_word": "随便", "complexity_tier": "T3", "furigana": "zhè cì jiàn miàn hěn suí biàn, dà jiā biān chī biān liáo", "sentence_source": "generated"}, {"text": "今天的聚会很随便，不用准备礼物。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对朋友向来很随便，不太讲究礼节。", "target_word": "随便", "complexity_tier": "T3", "furigana": "tā duì péng you xiàng lái hěn suí biàn, bú tài jiǎng jiu lǐ jié", "sentence_source": "generated"}, {"text": "我们家很随便，你不要紧张。", "target_word": "随便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友来家里吃饭，我们准备得很随便，几个菜就行。", "target_word": "随便", "complexity_tier": "T3", "furigana": "péng you lái jiā lǐ chī fàn, wǒ men zhǔn bèi de hěn suí biàn, jǐ gè cài jiù xíng", "sentence_source": "generated"}], "morphological_forms": [{"form": "随随便便", "label": "重叠"}, {"form": "隨便", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不拘束、不太讲究的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '155cb381-df48-4f0d-a482-c866d65aa334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随便", "is_correct": true, "explanation": "“随便”指不拘束、不讲究，与“穿得很”搭配，正确。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”说气味，不能用来形容穿衣的样子。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体需要进食，与穿着无关。"}, {"text": "客气", "is_correct": false, "explanation": "语义：“客气”说待人的态度，不说穿衣的样子。"}], "explanations": {"随便": "“随便”指不拘束、不讲究，与“穿得很”搭配，正确。", "香": "搭配：“香”说气味，不能用来形容穿衣的样子。", "饿": "语义：“饿”指身体需要进食，与穿着无关。", "客气": "语义：“客气”说待人的态度，不说穿衣的样子。"}, "sentence_index": 0, "correct_answer": "随便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议很随便，大家都穿西装。", "explanation": "这里应该用〈正式〉。随便表示不拘束，与“大家都穿西装”的正式场合不符；会议的正式程度要说“正式”。"}, {"text": "这位医生对病人的治疗方案很随便，每一步都仔细推敲。", "explanation": "这里应该用〈认真〉。随便表示不拘束，与“每一步都仔细推敲”矛盾；对治疗方案的态度要说“认真”。"}, {"text": "他吃饭很随便，不肯将就。", "explanation": "这里应该用〈讲究〉。随便指不拘束，与“不肯将就”矛盾；说对吃的挑剔要用“讲究”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随便", "is_correct": true, "explanation": "“随便”指轻松、不正式，与“不用准备礼物”的语境一致。"}, {"text": "严格", "is_correct": false, "explanation": "搭配：“严格”说规定或纪律，不用来形容聚会。"}, {"text": "深刻", "is_correct": false, "explanation": "搭配：“深刻”说印象或道理，不用来形容聚会。"}, {"text": "隆重", "is_correct": false, "explanation": "语义：“隆重”说场面盛大，与“不用准备礼物”的轻松语境矛盾。"}], "explanations": {"随便": "“随便”指轻松、不正式，与“不用准备礼物”的语境一致。", "严格": "搭配：“严格”说规定或纪律，不用来形容聚会。", "深刻": "搭配：“深刻”说印象或道理，不用来形容聚会。", "隆重": "语义：“隆重”说场面盛大，与“不用准备礼物”的轻松语境矛盾。"}, "sentence_index": 6, "correct_answer": "随便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次开幕式办得很随便，来了很多领导。", "explanation": "这里应该用〈隆重〉。随便表示简单、不拘束，与“来了很多领导”的正式场面不符；开幕式要说“隆重”。"}, {"text": "这位老师上课很随便，学生都不敢说话。", "explanation": "这里应该用〈严肃〉。随便指不拘束，与“学生都不敢说话”的语境矛盾；讲课的态度要说“严肃”。"}, {"text": "这家公司的数据很随便，每个数字都经过了反复核对。", "explanation": "这里应该用〈严谨〉。随便表示不拘束，与“每个数字都经过了反复核对”矛盾；对数据的态度要说“严谨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们聊很随便，像老朋友一样。", "corrected_sentence": "我们聊得很随便，像老朋友一样。", "error_description": "单音节动词后接“很随便”作状态补语时，中间须加“得”：应说“聊得很随便”，不说“聊很随便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个很随便人，从来不挑剔。", "corrected_sentence": "他是个很随便的人，从来不挑剔。", "error_description": "“随便”修饰名词时，中间要加“的”。应说“很随便的人”，不说“很随便人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd9eba83-7914-436d-a952-f8845b46dd7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
