INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91062, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "现在正在施行或使用的。", "primary_collocate": null, "pronunciation": "xiàn xíng", "ipa": "ɕjɛn˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "按照现行规定，新生必须先交材料。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行的办法已经用了十年。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项现行制度需要改一改。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行法律不允许这样做。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行政策对小公司很有帮助。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司现行的标准比以前严格。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据现行规定，这里不能停车。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想修改现行的考试办法。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行税法让很多人少交了钱。", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现行的做法有哪些问题？", "target_word": "现行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "现在正在施行的规定、制度、政策", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34cd94a-28b4-4837-b0b6-593d7d226e00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91062, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现行", "is_correct": true, "explanation": "正确：现行，指现在正在施行的规定、制度。"}, {"text": "先行", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，先行意思是事先行动，与现行不同。"}, {"text": "线性", "is_correct": false, "explanation": "xiàn 相同，xìng（第四声）与 xíng（第二声）声调不同，线性指呈直线关系的性质，意思不同。"}, {"text": "显性", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，显性指表现出来的性状，意思不同。"}, {"text": "显形", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，显形意思是显露出原形，与现行不同。"}], "explanations": {"现行": "正确：现行，指现在正在施行的规定、制度。", "先行": "xiān（第一声）与 xiàn（第四声）声调不同，先行意思是事先行动，与现行不同。", "线性": "xiàn 相同，xìng（第四声）与 xíng（第二声）声调不同，线性指呈直线关系的性质，意思不同。", "显性": "xiǎn（第三声）与 xiàn（第四声）声调不同，显性指表现出来的性状，意思不同。", "显形": "xiǎn（第三声）与 xiàn（第四声）声调不同，显形意思是显露出原形，与现行不同。"}, "sentence_index": null, "correct_answer": "现行"}, "level_3": {"options": [{"text": "现行", "is_correct": true, "explanation": "正确：“现行”表示现在正在施行，与“按照……规定”和“新生必须先交材料”相符。"}, {"text": "历史的", "is_correct": false, "explanation": "语义：“历史的”指已经过去的，与“新生必须先交材料”所说的现行要求相矛盾。"}, {"text": "私人的", "is_correct": false, "explanation": "语义：规定须是公开的集体要求，“私人的”与“按照……规定”不相容。"}, {"text": "美丽的", "is_correct": false, "explanation": "搭配：“美丽”形容外观或风貌，不能修饰“规定”。"}], "explanations": {"现行": "正确：“现行”表示现在正在施行，与“按照……规定”和“新生必须先交材料”相符。", "历史的": "语义：“历史的”指已经过去的，与“新生必须先交材料”所说的现行要求相矛盾。", "私人的": "语义：规定须是公开的集体要求，“私人的”与“按照……规定”不相容。", "美丽的": "搭配：“美丽”形容外观或风貌，不能修饰“规定”。"}, "sentence_index": 0, "correct_answer": "现行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的现行人口已超过三百万。", "explanation": "这里应该用〈现有〉。现行指正在施行的规章、制度、办法，不用于人口等数量。"}, {"text": "妹妹现行的成绩很好。", "explanation": "这里应该用〈现在的〉。现行指规章、制度已经施行，不用来形容成绩。"}, {"text": "现行的情况对公司很不利。", "explanation": "这里应该用〈目前的〉。现行强调规章、制度已经施行，不用来形容情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现行", "is_correct": true, "explanation": "正确：“现行”表示现在正在施行，与“根据……规定，这里不能停车”相符。"}, {"text": "过期的", "is_correct": false, "explanation": "语义：过期的规定已经失效，不能作为“这里不能停车”的依据。"}, {"text": "甜蜜的", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或味道，不能修饰“规定”。"}, {"text": "口语的", "is_correct": false, "explanation": "语域：“规定”属于正式书面用语，不能用“口语的”修饰。"}], "explanations": {"现行": "正确：“现行”表示现在正在施行，与“根据……规定，这里不能停车”相符。", "过期的": "语义：过期的规定已经失效，不能作为“这里不能停车”的依据。", "甜蜜的": "搭配：“甜蜜”形容感情或味道，不能修饰“规定”。", "口语的": "语域：“规定”属于正式书面用语，不能用“口语的”修饰。"}, "sentence_index": 6, "correct_answer": "现行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现行的困难很多。", "explanation": "这里应该用〈眼下的〉。现行用于已经施行的规章、制度，不说“现行的困难”。"}, {"text": "他现行的身高是一米八。", "explanation": "这里应该用〈现在的〉。现行指规章、制度已经施行，不用来形容身高等人的状况。"}, {"text": "现行的形势很复杂。", "explanation": "这里应该用〈当前的〉。现行指规章、制度已经施行，不用来形容形势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套制度是很现行的，大家都要遵守。", "corrected_sentence": "这套制度是现行的，大家都要遵守。", "error_description": "错误：“很现行”。“现行”不能受“很”修饰，应说“是现行的”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要遵守现行地规定。", "corrected_sentence": "我们要遵守现行规定。", "error_description": "错误：“现行地规定”。“现行”作定语修饰名词时后面不加“地”，应说“现行规定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
