INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91071, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看着别人有没有做错事。", "primary_collocate": null, "pronunciation": "jiān chá", "ipa": "tɕjɛn˥ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "保安在门口监察进出的人员。", "target_word": "监察", "complexity_tier": "T3", "furigana": "bǎo ān zài mén kǒu jiān chá jìn chū de rén yuán。", "sentence_source": "generated"}, {"text": "他每天监察工人有没有按规定做事。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理派人监察仓库的工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人在旁边监察，大家都很小心。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "值日老师负责监察学生有没有乱扔垃圾。", "target_word": "监察", "complexity_tier": "T3", "furigana": "zhí rì lǎo shī fù zé jiān chá xué shēng yǒu méi yǒu luàn rēng lā jī。", "sentence_source": "generated"}, {"text": "公司请专人监察每个人的工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他负责监察大家是不是迟到。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他监察别人的时候总是很认真。", "target_word": "监察", "complexity_tier": "T3", "furigana": "tā jiān chá bié rén de shí hou zǒng shì hěn rèn zhēn。", "sentence_source": "generated"}, {"text": "谁来监察车间里的安全情况？", "target_word": "监察", "complexity_tier": "T3", "furigana": "shéi lái jiān chá chē jiān lǐ de ān quán qíng kuàng？", "sentence_source": "generated"}, {"text": "他们监察过这里的安全情况。", "target_word": "监察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监察了", "label": "体标"}, {"form": "监察过", "label": "体标"}, {"form": "监察员", "label": "复合"}, {"form": "監察", "label": "繁体"}], "register": "中性", "sense_fingerprint": "看着别人有没有做错事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监察", "is_correct": true, "explanation": "正确：“监察”指看着人员有没有做错事，符合“保安在门口……进出的人员”的语境。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：“拍卖”的对象是物品，不能用于进出的人员。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象不能是人员，不能说“洗进出的人员”。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”的对象是地面，不能和“人员”搭配。"}], "explanations": {"监察": "正确：“监察”指看着人员有没有做错事，符合“保安在门口……进出的人员”的语境。", "拍卖": "搭配：“拍卖”的对象是物品，不能用于进出的人员。", "洗": "搭配：“洗”的对象不能是人员，不能说“洗进出的人员”。", "扫": "搭配：“扫”的对象是地面，不能和“人员”搭配。"}, "sentence_index": 0, "correct_answer": "监察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每天监察病人的身体。", "explanation": "这里应该用〈检查〉。监察是看着别人有没有做错事，不用来说身体状况，检查身体要用〈检查〉。"}, {"text": "科学家仔细监察蚂蚁的行动。", "explanation": "这里应该用〈观察〉。监察针对人的行为是否合规，观察动物的行动要用〈观察〉。"}, {"text": "妈妈每天监察生病的爷爷。", "explanation": "这里应该用〈照顾〉。监察是看着别人有没有做错事，照顾生病的人要用〈照顾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监察", "is_correct": true, "explanation": "正确：“监察”指看着别人有没有做错事，符合“他负责……大家是不是迟到”的语境。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是支持和激励，不能用来核查“是不是迟到”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地，不能和“大家是不是迟到”搭配。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是接待来人，不能用来核查“是不是迟到”。"}], "explanations": {"监察": "正确：“监察”指看着别人有没有做错事，符合“他负责……大家是不是迟到”的语境。", "鼓励": "语义：“鼓励”是支持和激励，不能用来核查“是不是迟到”。", "打扫": "搭配：“打扫”的对象是场地，不能和“大家是不是迟到”搭配。", "欢迎": "语义：“欢迎”是接待来人，不能用来核查“是不是迟到”。"}, "sentence_index": 6, "correct_answer": "监察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在美术馆监察名画。", "explanation": "这里应该用〈欣赏〉。监察是看着人的行为是否合规，欣赏名画要用〈欣赏〉。"}, {"text": "他仔细监察这道菜。", "explanation": "这里应该用〈品尝〉。监察针对人的行为，品尝食物要用〈品尝〉。"}, {"text": "我周末去医院监察朋友。", "explanation": "这里应该用〈探望〉。监察不用来说探访朋友，去医院看朋友要用〈探望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在教室后面监察同学们的身高。", "corrected_sentence": "老师在教室后面监察同学们的纪律。", "error_description": "错误：“监察”的对象是人的行为是否合规，不能是“身高”；正确为“监察同学们的纪律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上级定期监察在各分公司的账目。", "corrected_sentence": "上级定期监察各分公司的账目。", "error_description": "错误：宾语“各分公司的账目”前多了“在”，“监察”直接带宾语，不能加“在”；正确为“监察各分公司的账目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
