INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "监督检查机关或人员的工作和行为是否合乎规定。", "primary_collocate": null, "pronunciation": "jiān chá", "ipa": "tɕjɛn˥ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "纪检部门负责监察公务员的行为。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上级正在监察各部门的工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家设立专门机构监察官员的行为。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们监察了这个部门一年的工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个委员会负责监察政府是否守法。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "必须有人监察官员有没有违反规定。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校成立小组监察食堂的卫生工作。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里派人监察各个医院的收费情况。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司内部有人专门监察员工的行为。", "target_word": "监察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上级已经监察过这家银行的工作。", "target_word": "监察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监察了", "label": "体标"}, {"form": "监察过", "label": "体标"}, {"form": "监察机关", "label": "复合"}, {"form": "監察", "label": "繁体"}], "register": "书面", "sense_fingerprint": "监督检查机关或人员的工作和行为是否合规", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监察", "is_correct": true, "explanation": "正确：“监察”指监督检查人员的行为是否合规，符合“纪检部门负责……公务员的行为”的语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏观看，不是监督检查工作和行为。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”的对象是影片，不能用于“公务员的行为”。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”是招待客人，与“监督公务员的行为”无关。"}], "explanations": {"监察": "正确：“监察”指监督检查人员的行为是否合规，符合“纪检部门负责……公务员的行为”的语境。", "欣赏": "语义：“欣赏”是赞赏观看，不是监督检查工作和行为。", "放映": "搭配：“放映”的对象是影片，不能用于“公务员的行为”。", "款待": "语义：“款待”是招待客人，与“监督公务员的行为”无关。"}, "sentence_index": 0, "correct_answer": "监察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人监察了这台机器。", "explanation": "这里应该用〈检查〉。监察指监督检查机关或人员的工作和行为是否合规，检查机器的状况要用〈检查〉。"}, {"text": "他每天监察这片花园。", "explanation": "这里应该用〈照看〉。监察针对机关或人员的工作和行为，照看花园要用〈照看〉。"}, {"text": "医生监察了这位病人。", "explanation": "这里应该用〈检查〉。监察指监督检查人员的工作和行为，给病人做身体检查要用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监察", "is_correct": true, "explanation": "正确：“监察”指监督检查工作，符合“学校成立小组……食堂的卫生工作”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能和“卫生工作”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修复器物，不能用于“卫生工作”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”没有“卫生工作”这样的宾语。"}], "explanations": {"监察": "正确：“监察”指监督检查工作，符合“学校成立小组……食堂的卫生工作”的语境。", "吃": "搭配：“吃”不能和“卫生工作”搭配。", "修理": "语义：“修理”是修复器物，不能用于“卫生工作”。", "唱": "搭配：“唱”没有“卫生工作”这样的宾语。"}, "sentence_index": 6, "correct_answer": "监察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在厨房监察蛋糕。", "explanation": "这里应该用〈照看〉。监察指监督检查人员的工作和行为，看着蛋糕防止烤焦要用〈照看〉。"}, {"text": "我们在河边监察风景。", "explanation": "这里应该用〈欣赏〉。监察不用于观看风景，欣赏风景要用〈欣赏〉。"}, {"text": "孩子们在院子里监察蝴蝶。", "explanation": "这里应该用〈观察〉。监察针对人的行为，观察蝴蝶要用〈观察〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上级部门派专人仔细监察在各乡镇的财务。", "corrected_sentence": "上级部门派专人仔细监察各乡镇的财务。", "error_description": "错误：“各乡镇的财务”前多了“在”，“监察”直接带宾语，不能加“在”；正确为“仔细监察各乡镇的财务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会计部门定期监察在公司的账目。", "corrected_sentence": "会计部门定期监察公司的账目。", "error_description": "错误：“公司的账目”前多了“在”，“监察”直接带宾语，不能加“在”；正确为“监察公司的账目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
