INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一家公司里管事情最多的人。", "primary_collocate": null, "pronunciation": "zǒng jīng lǐ", "ipa": "tsʊŋ˨˩˦ tɕiŋ˥ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "总经理在办公室开会。", "target_word": "总经理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司的总经理很年轻。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理每天都很忙。", "target_word": "总经理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是这家公司的总经理。", "target_word": "总经理", "complexity_tier": "T3", "furigana": "tā shì zhè jiā gōng sī de zǒng jīng lǐ", "sentence_source": "generated"}, {"text": "大家都听总经理的话。", "target_word": "总经理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总经理说明天不用上班。", "target_word": "总经理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王想见一下总经理。", "target_word": "总经理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新来的总经理对我们很好。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理请大家一起吃饭。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸是一家小公司的总经理。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位总经理", "label": "量词"}, {"form": "副总经理", "label": "复合"}, {"form": "總經理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司里管事情最多的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总经理", "is_correct": true, "explanation": "正确。总经理是公司里管事情最多的人，在办公室开会符合语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是公司的管理者，也不会在办公室开会。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能在办公室开会。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是物品，不能在办公室开会。"}], "explanations": {"总经理": "正确。总经理是公司里管事情最多的人，在办公室开会符合语境。", "小猫": "语义：小猫不是公司的管理者，也不会在办公室开会。", "冰箱": "语义：冰箱是家用电器，不能在办公室开会。", "窗帘": "语义：窗帘是物品，不能在办公室开会。"}, "sentence_index": 0, "correct_answer": "总经理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司的财务部当总经理，负责报销的工作。", "explanation": "这里应该用〈经理〉。总经理管的是整个公司，只负责一个部门时要用〈经理〉。"}, {"text": "今天的董事会由总经理主持。", "explanation": "这里应该用〈董事长〉。董事会由董事长主持，总经理是公司的执行负责人，不主持董事会。"}, {"text": "我们部门的总经理每天检查库存。", "explanation": "这里应该用〈主管〉。总经理统管全公司，部门的负责人要用〈主管〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总经理", "is_correct": true, "explanation": "正确。“小王想见一下”的对象是人，总经理符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物品，不是可以见面的人，“想见一下钥匙”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能被“见一下”，句子不成立。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不是人，“想见一下白菜”说不通。"}], "explanations": {"总经理": "正确。“小王想见一下”的对象是人，总经理符合语境。", "钥匙": "语义：钥匙是物品，不是可以见面的人，“想见一下钥匙”说不通。", "天空": "语义：天空是自然景象，不能被“见一下”，句子不成立。", "白菜": "语义：白菜是蔬菜，不是人，“想见一下白菜”说不通。"}, "sentence_index": 6, "correct_answer": "总经理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的总经理今天给新生讲话。", "explanation": "这里应该用〈校长〉。总经理用于公司，学校的负责人要用〈校长〉。"}, {"text": "这支部队的总经理下令出发。", "explanation": "这里应该用〈司令〉。总经理用于公司，部队的指挥官要用〈司令〉。"}, {"text": "这个村的总经理今天开会。", "explanation": "这里应该用〈村长〉。总经理用于公司，村里的负责人要用〈村长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司新总经理很年轻。", "corrected_sentence": "我们公司的新总经理很年轻。", "error_description": "“的”漏掉。“我们公司”修饰“新总经理”时，中间要加“的”，应说“我们公司的新总经理”，不能说“我们公司新总经理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他了当三年总经理。", "corrected_sentence": "他当了三年总经理。", "error_description": "“了”位置错误。“了”应紧跟动词“当”表示完成，应说“他当了三年总经理”，不能放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
