INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责主持公司全面日常经营管理工作的最高行政负责人。", "primary_collocate": null, "pronunciation": "zǒng jīng lǐ", "ipa": "tsʊŋ˨˩˦ tɕiŋ˥ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "总经理负责公司的日常经营工作。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事会任命他为公司总经理。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理向董事会报告今年的情况。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位总经理管理着三千名员工。", "target_word": "总经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司总经理签了这份合同。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理主持了今天的管理会议。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了十年总经理。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理要对公司的经营结果负责。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新总经理明天正式上任。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总经理召集各部门负责人开会。", "target_word": "总经理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位总经理", "label": "量词"}, {"form": "副总经理", "label": "复合"}, {"form": "總經理", "label": "繁体"}], "register": "书面", "sense_fingerprint": "主持公司全面日常经营管理的最高行政负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总经理", "is_correct": true, "explanation": "正确。总经理负责公司的日常经营工作，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能负责公司的经营工作。"}, {"text": "图纸", "is_correct": false, "explanation": "语义：图纸是纸张，不能负责公司的经营管理。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本是记账的册子，不能负责公司的经营工作。"}], "explanations": {"总经理": "正确。总经理负责公司的日常经营工作，符合句意。", "石头": "语义：石头不能负责公司的经营工作。", "图纸": "语义：图纸是纸张，不能负责公司的经营管理。", "账本": "语义：账本是记账的册子，不能负责公司的经营工作。"}, "sentence_index": 0, "correct_answer": "总经理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位总经理负责一所学校的日常工作。", "explanation": "这里应该用〈校长〉。总经理用于公司，学校的负责人要用〈校长〉。"}, {"text": "我们班的总经理今天请假了。", "explanation": "这里应该用〈班长〉。总经理是公司的最高负责人，班里负责管事的同学要用〈班长〉。"}, {"text": "这位总经理负责本部门的采购工作。", "explanation": "这里应该用〈部长〉。总经理统管全公司，不只负责一个部门，部门的负责人要用〈部长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总经理", "is_correct": true, "explanation": "正确。“当了十年”后接担任的职务，总经理符合句意。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：冰山是自然景物，不能“当”某种职务。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗像，不能担任职务。"}, {"text": "阁下", "is_correct": false, "explanation": "语域：“阁下”是书面的敬称，用来称呼人，不能表示担任的职务，与句子的口语语境也不符。"}], "explanations": {"总经理": "正确。“当了十年”后接担任的职务，总经理符合句意。", "冰山": "语义：冰山是自然景物，不能“当”某种职务。", "影子": "语义：影子是光线形成的暗像，不能担任职务。", "阁下": "语域：“阁下”是书面的敬称，用来称呼人，不能表示担任的职务，与句子的口语语境也不符。"}, "sentence_index": 6, "correct_answer": "总经理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的总经理今天宣布了新政策。", "explanation": "这里应该用〈市长〉。总经理用于公司，城市的行政负责人要用〈市长〉。"}, {"text": "这个连的总经理今天下令出发。", "explanation": "这里应该用〈连长〉。总经理用于公司，带领一个连的军官要用〈连长〉。"}, {"text": "这个派出所的总经理今天抓了一个小偷。", "explanation": "这里应该用〈所长〉。总经理用于公司，派出所的负责人要用〈所长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司的一只总经理上周签了合同。", "corrected_sentence": "我们公司的一位总经理上周签了合同。", "error_description": "量词错误。“总经理”指人，量词应用“位”，“只”多用于动物等，不能说“一只总经理”，应说“一位总经理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "董事会推举他是总经理。", "corrected_sentence": "董事会推举他为总经理。", "error_description": "连接词错误。“推举”后表示当选职务，应说“推举他为总经理”，不能用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
