INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "普通的民众；平民。", "primary_collocate": null, "pronunciation": "lǎo bǎi xìng", "ipa": "lau²¹⁴ pai²¹⁴ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "老百姓最怕物价上涨。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束了，老百姓终于能回家。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓都爱看这个电视节目。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多老百姓晚上喜欢去公园散步。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆很便宜，老百姓都吃得起。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，老百姓和士兵都很苦。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓每天都要买菜做饭。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁开了，老百姓上班方便了。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西很贵，老百姓买不起。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓过年时喜欢和家人吃饺子。", "target_word": "老百姓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "百姓", "label": "简称"}], "register": "口语", "sense_fingerprint": "普通民众、平民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5dc62fb-f015-4a98-8321-fde426f86ecf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老百姓", "is_correct": true, "explanation": "正确。指普通民众，「最怕物价上涨」符合人的心理，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能「怕」物价上涨。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有感情，不能说「最怕」。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有感情，不能「最怕」物价上涨，与句意不合。"}], "explanations": {"老百姓": "正确。指普通民众，「最怕物价上涨」符合人的心理，句意通顺。", "石头": "语义：石头没有感情，不能「怕」物价上涨。", "房子": "语义：房子没有感情，不能说「最怕」。", "电脑": "语义：电脑没有感情，不能「最怕」物价上涨，与句意不合。"}, "sentence_index": 0, "correct_answer": "老百姓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院的老百姓都是医生，每天忙着看病。", "explanation": "这里是把〈老百姓〉当成有专业身份的职业人员来用，它指平常的普通人，不指这类人。"}, {"text": "他是公司的老百姓，负责管钱。", "explanation": "这里是把〈老百姓〉当成掌握权力的人来用，它指普通民众，不指掌握钱财的人。"}, {"text": "这家店的老百姓都是老板，说话很有权威。", "explanation": "这里是把〈老百姓〉当成有权力的人来用，它指平常的普通人，不指掌权的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老百姓", "is_correct": true, "explanation": "正确。指普通民众，「每天都要买菜做饭」是普通人的日常，句意通顺。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会买菜做饭，与句意不合。"}, {"text": "太子", "is_correct": false, "explanation": "语义：太子身份尊贵，一般不做买菜做饭的家务，与句意相抵触。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会买菜做饭，与句意不合。"}], "explanations": {"老百姓": "正确。指普通民众，「每天都要买菜做饭」是普通人的日常，句意通顺。", "狗": "语义：狗不会买菜做饭，与句意不合。", "太子": "语义：太子身份尊贵，一般不做买菜做饭的家务，与句意相抵触。", "石头": "语义：石头不会买菜做饭，与句意不合。"}, "sentence_index": 6, "correct_answer": "老百姓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个商店只收老百姓币。", "explanation": "这里应该用〈人民〉。「人民币」是固定说法，不能换成「老百姓」。"}, {"text": "他在电影里演老百姓演员。", "explanation": "这里应该用〈群众〉。「群众演员」是固定说法，「老百姓演员」不这样说。"}, {"text": "这栋老百姓楼很旧了。", "explanation": "这里应该用〈居民〉。「居民楼」是固定说法，「老百姓楼」不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条老百姓家里有三个孩子。", "corrected_sentence": "那位老百姓家里有三个孩子。", "error_description": "错误：量词「条」。正确：量词「位」或「个」。「老百姓」指人，「条」不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这老百姓每天都早起散步。", "corrected_sentence": "这位老百姓每天都早起散步。", "error_description": "错误：指示代词「这」后缺少量词。正确：应说「这位老百姓」，「这」后面需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede13a33-aff7-4ccd-b7b5-7f12e5b94997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
