INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91105, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多大战船排在一起，在海上一起走。", "primary_collocate": null, "pronunciation": "jiàn duì", "ipa": "tɕjɛn˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "海上来了一支大舰队。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队在海上慢慢往前走。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看到了一支很大的舰队。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支舰队有三十多条船。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队今天早上离开了港口。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，舰队到了小岛旁边。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的舰队排成一条长长的线。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在海边看舰队经过。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，舰队停在海上不动。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一张舰队的画。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "舰队司令", "label": "复合"}], "register": "中性", "sense_fingerprint": "许多大战船在海上排队同行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舰队", "is_correct": true, "explanation": "正确。“一支”用于部队，“海上来了一支大舰队”符合句意。"}, {"text": "小区", "is_correct": false, "explanation": "语义：小区是居民住宅区，不能在海上“来”。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林长在陆地上，不能说海上来了一支大森林。"}, {"text": "风", "is_correct": false, "explanation": "搭配：“支”不用于风，风应说“一阵”，“一支大风”搭配不当。"}], "explanations": {"舰队": "正确。“一支”用于部队，“海上来了一支大舰队”符合句意。", "小区": "语义：小区是居民住宅区，不能在海上“来”。", "森林": "语义：森林长在陆地上，不能说海上来了一支大森林。", "风": "搭配：“支”不用于风，风应说“一阵”，“一支大风”搭配不当。"}, "sentence_index": 0, "correct_answer": "舰队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支舰队有三十多辆车。", "explanation": "这里应该用〈车队〉。舰队由军舰组成，车辆组成的队伍要用〈车队〉。"}, {"text": "这支舰队有三十多匹马。", "explanation": "这里应该用〈马队〉。舰队由军舰组成，马匹组成的队伍要用〈马队〉。"}, {"text": "这支舰队在舞台上唱了一首歌。", "explanation": "这里应该用〈合唱团〉。舰队是由军舰组成的海军部队，在舞台上唱歌的人要用〈合唱团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舰队", "is_correct": true, "explanation": "正确。舰队可以排成一条长长的线，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不能“排成一条长长的线”。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆是抽象的心理内容，不能排成一条线。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的观念，不能排成一条线。"}], "explanations": {"舰队": "正确。舰队可以排成一条长长的线，符合句意。", "月亮": "语义：月亮在天上，不能“排成一条长长的线”。", "回忆": "语义：回忆是抽象的心理内容，不能排成一条线。", "道理": "语义：道理是抽象的观念，不能排成一条线。"}, "sentence_index": 6, "correct_answer": "舰队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支舰队的渔民每天出海打鱼。", "explanation": "这里应该用〈船队〉。舰队是军舰组成的海军部队，出海打鱼的船只组成的队伍要用〈船队〉。"}, {"text": "这支舰队在球场上赢了比赛。", "explanation": "这里应该用〈球队〉。舰队是海军部队，参加比赛的队伍要用〈球队〉。"}, {"text": "这支舰队在广场上演奏了一首歌。", "explanation": "这里应该用〈乐队〉。舰队是海军部队，演奏乐器的队伍要用〈乐队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海上舰队很壮观。", "corrected_sentence": "海上的舰队很壮观。", "error_description": "“的”漏掉。“海上”修饰“舰队”时，中间要加“的”，应说“海上的舰队”，不能说“海上舰队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支舰队们昨天傍晚就出发了。", "corrected_sentence": "这支舰队昨天傍晚就出发了。", "error_description": "复数错误。“舰队”本身指由多艘军舰组成的整体，不能再加“们”表示复数，应说“这支舰队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
