INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由若干军舰编成的海军作战部队。", "primary_collocate": null, "pronunciation": "jiàn duì", "ipa": "tɕjɛn˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "海军派出了一支舰队。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支舰队的任务是保护海上的航线。", "target_word": "舰队", "complexity_tier": "T3", "furigana": "zhè zhī jiàn duì de rèn wu shì bǎo hù hǎi shàng de háng xiàn", "sentence_source": "generated"}, {"text": "舰队已经出发了。", "target_word": "舰队", "complexity_tier": "T3", "furigana": "jiàn duì yǐ jīng chū fā le", "sentence_source": "generated"}, {"text": "敌人的舰队开始向我们靠近。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队由十艘军舰组成。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，这支舰队立过大功。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家派舰队去海外训练。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰队在演习中打了一场胜仗。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的舰队已经建成了。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支舰队的指挥官很有经验。", "target_word": "舰队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "舰队司令", "label": "复合"}], "register": "中性", "sense_fingerprint": "海军编制的军舰作战部队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eafbf73-fe6d-4ac7-932f-9a09579e5b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舰队", "is_correct": true, "explanation": "正确。海军派出的是由军舰编成的作战部队，“一支舰队”符合句意。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是存放书籍的场所，不能被海军派出去作战。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能被派出。"}, {"text": "大炮", "is_correct": false, "explanation": "搭配：大炮的量词是“门”，“一支大炮”搭配不当，句子也不宜这样说。"}], "explanations": {"舰队": "正确。海军派出的是由军舰编成的作战部队，“一支舰队”符合句意。", "图书馆": "语义：图书馆是存放书籍的场所，不能被海军派出去作战。", "空气": "语义：空气是无形的气体，不能被派出。", "大炮": "搭配：大炮的量词是“门”，“一支大炮”搭配不当，句子也不宜这样说。"}, "sentence_index": 0, "correct_answer": "舰队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支舰队在公路上行驶。", "explanation": "这里应该用〈车队〉。舰队是由军舰组成的海军部队，不能在公路上行驶。"}, {"text": "这支舰队在草原上奔跑。", "explanation": "这里应该用〈马队〉。舰队由军舰组成，不能在草原上奔跑。"}, {"text": "这支舰队在海上捕鱼，每天收获很多。", "explanation": "这里应该用〈船队〉。舰队是军舰组成的海军部队，出海捕鱼的船只组成的队伍要用〈船队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舰队", "is_correct": true, "explanation": "正确。国家派舰队去海外训练，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是水域，不能被派去海外训练。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能被派去海外训练。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是粮食，不能被派去海外训练。"}], "explanations": {"舰队": "正确。国家派舰队去海外训练，符合句意。", "大海": "语义：大海是水域，不能被派去海外训练。", "太阳": "语义：太阳是天体，不能被派去海外训练。", "大米": "语义：大米是粮食，不能被派去海外训练。"}, "sentence_index": 6, "correct_answer": "舰队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支舰队在篮球场上赢了比赛。", "explanation": "这里应该用〈球队〉。舰队是海军部队，打篮球比赛的队伍要用〈球队〉。"}, {"text": "这支舰队在广场上唱了一首歌。", "explanation": "这里应该用〈合唱团〉。舰队是海军部队，一起唱歌的人要用〈合唱团〉。"}, {"text": "这支舰队在山里修了一条路。", "explanation": "这里应该用〈工程队〉。舰队是海军部队，负责修路的队伍要用〈工程队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘舰队已经出发了。", "corrected_sentence": "这支舰队已经出发了。", "error_description": "量词错误。“舰队”是由多艘军舰组成的编队，量词应用“支”；“艘”只用于单艘船，不能说“这艘舰队”，应说“这支舰队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支舰队们的指挥官很年轻。", "corrected_sentence": "这支舰队的指挥官很年轻。", "error_description": "复数错误。“舰队”本身是整体名词，不能加“们”表示复数，应说“这支舰队的指挥官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b5abab-9083-4c62-a67d-86f0c420e057') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "停留", "is_correct": false, "explanation": "与到来无反义关系：停留是待在原地，并不是与“来临”相对的意思。"}, {"text": "保持", "is_correct": false, "explanation": "与到来无反义关系：保持表示维持原状，不表示离开。"}, {"text": "继续", "is_correct": false, "explanation": "与到来无反义关系：继续表示接着做下去，不与“来临”相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "停留": "与到来无反义关系：停留是待在原地，并不是与“来临”相对的意思。", "保持": "与到来无反义关系：保持表示维持原状，不表示离开。", "继续": "与到来无反义关系：继续表示接着做下去，不与“来临”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "坚持", "is_correct": false, "explanation": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。"}, {"text": "停止", "is_correct": false, "explanation": "与到来无反义关系：停止与“继续”相对，并不与“到来”相对。"}, {"text": "等待", "is_correct": false, "explanation": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "坚持": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。", "停止": "与到来无反义关系：停止与“继续”相对，并不与“到来”相对。", "等待": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到来是时间或客人来了。", "primary_collocate": null, "pronunciation": "dào lái", "ipa": "taʊ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "客人到来时，妈妈正在做饭。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们热情欢迎客人的到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的到来让我很意外。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到来以前，我们先把房间打扫好。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到来，树叶慢慢变黄了。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课的时间还没到来，同学们在教室里聊天。", "target_word": "到来", "complexity_tier": "T3", "furigana": "dào lái", "sentence_source": "generated"}, {"text": "周末到来，大家都想出去玩。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学的到来让班里更热闹了。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等了很久，客人才到来。", "target_word": "到来", "complexity_tier": "T3", "furigana": "dào lái", "sentence_source": "generated"}, {"text": "节日到来之前，街上就挂满了灯。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到来了", "label": "体标"}, {"form": "到来的", "label": "复合"}], "register": "中性", "sense_fingerprint": "时间到了或客人、人来了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是时间到了或人来了。"}, {"text": "带来", "is_correct": false, "explanation": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。"}, {"text": "打来", "is_correct": false, "explanation": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。"}, {"text": "得来", "is_correct": false, "explanation": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”。"}, {"text": "道路", "is_correct": false, "explanation": "lù 与 lái 的韵母与声调都不同，意思是“道路”。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是时间到了或人来了。", "带来": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。", "打来": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。", "得来": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”。", "道路": "lù 与 lái 的韵母与声调都不同，意思是“道路”。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来表示客人来了，与“妈妈正在做饭”的情境相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：人不会融化，“客人融化时”说不通，与“妈妈正在做饭”的情境不合。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“客人消失时”与“妈妈正在做饭”的情境不合，人不会这样出现。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“客人结束时”说不通，客人不能“结束”。"}], "explanations": {"到来": "正确：到来表示客人来了，与“妈妈正在做饭”的情境相符。", "融化": "语义：人不会融化，“客人融化时”说不通，与“妈妈正在做饭”的情境不合。", "消失": "语义：“客人消失时”与“妈妈正在做饭”的情境不合，人不会这样出现。", "结束": "语义：“客人结束时”说不通，客人不能“结束”。"}, "sentence_index": 0, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林到来了。", "explanation": "这里应该用〈出现〉。到来用于时间或客人来临，森林不能“到来”，森林映入眼帘应说“出现”。"}, {"text": "这座城市到来了。", "explanation": "这里应该用〈建成〉。到来用于时间或客人来临，城市不能“到来”，城市建成应说“建成”。"}, {"text": "这片草地到来了。", "explanation": "这里应该用〈长满〉。到来用于时间或客人来临，草地不能“到来”，草地长满了花应说“长满”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是时间到了或人来了。"}, {"text": "调来", "is_correct": false, "explanation": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位同事）。"}, {"text": "叫来", "is_correct": false, "explanation": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。"}, {"text": "早来", "is_correct": false, "explanation": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。"}, {"text": "讨来", "is_correct": false, "explanation": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是时间到了或人来了。", "调来": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位同事）。", "叫来": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。", "早来": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。", "讨来": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来表示周末来临，与“大家都想出去玩”的语境相符。"}, {"text": "远去", "is_correct": false, "explanation": "语义：“周末远去”与“大家都想出去玩”的时间语境相悖。"}, {"text": "光临", "is_correct": false, "explanation": "语域：“光临”是敬辞，用于客人到访，不宜用来叙述周末。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“周末撤离”说不通，周末不会像人一样撤走。"}], "explanations": {"到来": "正确：到来表示周末来临，与“大家都想出去玩”的语境相符。", "远去": "语义：“周末远去”与“大家都想出去玩”的时间语境相悖。", "光临": "语域：“光临”是敬辞，用于客人到访，不宜用来叙述周末。", "撤离": "语义：“周末撤离”说不通，周末不会像人一样撤走。"}, "sentence_index": 6, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌到来了。", "explanation": "这里应该用〈响起〉。到来用于时间或客人来临，歌不能“到来”，歌声响起应说“响起”。"}, {"text": "这间教室到来了。", "explanation": "这里应该用〈布置好〉。到来不能用于教室，教室布置好了应说“布置好”。"}, {"text": "这盆花到来了。", "explanation": "这里应该用〈开〉。到来不能用于花，花开了应说“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人到来了时，我们正在吃饭。", "corrected_sentence": "客人到来时，我们正在吃饭。", "error_description": "错误：“到来了时”不成立。“到来了”可作谓语（如“春天到来了”），但接“时”组成时间状语时不带“了”，应为“客人到来时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天节日就要到来过，街上很热闹。", "corrected_sentence": "明天节日就要到来，街上很热闹。", "error_description": "错误：“到来”后多加了“过”。“过”表示曾经的经历，与“就要”所表示的将来不符。正确形式是去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "停留", "is_correct": false, "explanation": "与到来无反义关系：停留是待在原地，并不是与“来临”相对的意思。"}, {"text": "保持", "is_correct": false, "explanation": "与到来无反义关系：保持表示维持原状，不表示离开。"}, {"text": "继续", "is_correct": false, "explanation": "与到来无反义关系：继续表示接着做下去，不与“来临”相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "停留": "与到来无反义关系：停留是待在原地，并不是与“来临”相对的意思。", "保持": "与到来无反义关系：保持表示维持原状，不表示离开。", "继续": "与到来无反义关系：继续表示接着做下去，不与“来临”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离去", "is_correct": true, "explanation": "正确：到来（来临）的反义是离去，指时间、季节或人离开。"}, {"text": "坚持", "is_correct": false, "explanation": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。"}, {"text": "停止", "is_correct": false, "explanation": "与到来无反义关系：停止表示不再继续，它与“继续”相对，而不与“到来”相对。"}, {"text": "等待", "is_correct": false, "explanation": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}], "correct_answer": "离去", "explanations": {"离去": "正确：到来（来临）的反义是离去，指时间、季节或人离开。", "坚持": "与到来无反义关系：坚持表示持续做某事，不与“来临”相对。", "停止": "与到来无反义关系：停止表示不再继续，它与“继续”相对，而不与“到来”相对。", "等待": "与到来无反义关系：等待表示期望某事发生，与“来临”并不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来到；来临。", "primary_collocate": null, "pronunciation": "dào lái", "ipa": "taʊ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "春天到来了，花都开了。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年就要到来，大家都很高兴。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一直期待着比赛的到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试到来之前，我每天复习。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到来，天气一天比一天冷。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等新年的到来。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息的到来让全家人很开心。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天到来了，我们去海边玩吧。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期快要到来，同学们很兴奋。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨季到来后，这里常常下雨。", "target_word": "到来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到来了", "label": "体标"}, {"form": "到来的", "label": "复合"}], "register": "中性", "sense_fingerprint": "某个时刻、季节或事情来临、来到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf90865-4d6c-41d7-9be1-67a6da867aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是来到、来临。"}, {"text": "带来", "is_correct": false, "explanation": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。"}, {"text": "讨来", "is_correct": false, "explanation": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。"}, {"text": "打来", "is_correct": false, "explanation": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。"}, {"text": "得来", "is_correct": false, "explanation": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”（如得来不易）。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是来到、来临。", "带来": "dài（第四声）与 dào 的韵母不同（ai 与 ao），声调相同，意思是“带来”。", "讨来": "tǎo（第三声）与 dào 声母不同（t 与 d），声调也不同，意思是“讨来”。", "打来": "dǎ（第三声）与 dào 韵母和声调都不同，意思是“打来”（如打来电话）。", "得来": "dé（第二声）与 dào 韵母与声调都不同，意思是“得来”（如得来不易）。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来表示春天来临，与后文“花都开了”相符。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“春天离开了”与后文“花都开了”的时令冲突。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“春天结束了”与“花都开了”的时令不合。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：春天不能被“拆除”，“春天拆除了”说不通，与“花都开了”也不合。"}], "explanations": {"到来": "正确：到来表示春天来临，与后文“花都开了”相符。", "离开": "语义：“春天离开了”与后文“花都开了”的时令冲突。", "结束": "语义：“春天结束了”与“花都开了”的时令不合。", "拆除": "语义：春天不能被“拆除”，“春天拆除了”说不通，与“花都开了”也不合。"}, "sentence_index": 0, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山到来了。", "explanation": "这里应该用〈出现〉。到来用于人、季节或事情来临，山不能“到来”，山映入眼帘应说“出现”。"}, {"text": "他的身高到来了。", "explanation": "这里应该用〈长高〉。到来指人、季节或事情来临，身高是人的属性，不能说“到来”，应说“长高”。"}, {"text": "这条路到来了。", "explanation": "这里应该用〈延伸〉。到来指人、季节或事情来临，道路不能“到来”，表示道路向前伸展应说“延伸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91110, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确答案。到来（dào lái）意思是来到、来临。"}, {"text": "调来", "is_correct": false, "explanation": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位老师）。"}, {"text": "叫来", "is_correct": false, "explanation": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。"}, {"text": "早来", "is_correct": false, "explanation": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。"}, {"text": "道理", "is_correct": false, "explanation": "lǐ（第三声）与 lái 的韵母和声调都不同，意思是“道理”。"}], "explanations": {"到来": "正确答案。到来（dào lái）意思是来到、来临。", "调来": "diào（第四声）比 dào 多一个介音 i，意思是“调来”（如调来一位老师）。", "叫来": "jiào（第四声）与 dào 声母不同（j 与 d），意思是“叫来”。", "早来": "zǎo（第三声）与 dào 声母不同（z 与 d），声调也不同，意思是“早来”。", "道理": "lǐ（第三声）与 lái 的韵母和声调都不同，意思是“道理”。"}, "sentence_index": null, "correct_answer": "到来"}, "level_3": {"options": [{"text": "到来", "is_correct": true, "explanation": "正确：到来作名词，指好消息的来临，与“让全家人很开心”相符。"}, {"text": "远去", "is_correct": false, "explanation": "语义：“好消息远去”与“全家人很开心”的结果相悖。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“好消息撤离”说不通，与全家人开心的结果不合。"}, {"text": "消逝", "is_correct": false, "explanation": "搭配：“消逝”多用于时光、记忆，不宜说好消息的消逝。"}], "explanations": {"到来": "正确：到来作名词，指好消息的来临，与“让全家人很开心”相符。", "远去": "语义：“好消息远去”与“全家人很开心”的结果相悖。", "撤离": "语义：“好消息撤离”说不通，与全家人开心的结果不合。", "消逝": "搭配：“消逝”多用于时光、记忆，不宜说好消息的消逝。"}, "sentence_index": 6, "correct_answer": "到来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥到来了。", "explanation": "这里应该用〈建成〉。到来用于人、季节或事情来临，桥不能“到来”，桥修好了应说“建成”。"}, {"text": "这首诗到来了。", "explanation": "这里应该用〈写成〉。到来不能用于作品，诗写成了应说“写成”。"}, {"text": "这个道理到来了。", "explanation": "这里应该用〈懂得〉。到来不能用于道理，懂得一个道理应说“懂得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a871bfef-9455-4623-b20a-d6c7f36cbc8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
